window.PACK={"book":{"id":"umdat-ahkam","title":"عمدة الأحكام من كلام خير الأنام","type":"usulbook","ilm":"madhhab","author":"عبد الغني المقدسي (ت ٦٠٠هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"دار الثقافة العربية، دمشق - بيروت، مؤسسة قرطبة، مدينة الأندلس","optional":true,"packVersion":"59337ec0867b"},"items":[{"id":"umdat-ahkam:1","bookId":"umdat-ahkam","type":"section","seq":1,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"عمدة الأحكام\nمن كلام خير الأنام\nعليه\nالصلاة والسلام\nتأليف\nالإمام الحافظ تقي الدين، أبي محمد\nعبد الغني المقدسي الجماعيلي الحنبلي\nولد في سنة 541 ه وتوفي في22 من شهر ربيع الأول سنة 600 ه\nرحمه الله وغفر له وللمؤمنين"},{"id":"umdat-ahkam:2","bookId":"umdat-ahkam","type":"section","seq":2,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"بسم الله الرحمن الرحيم\nالحمد لله والصلاة والسلام على رسول الله وبعد:\nيعتبر كتاب عمدة الأحكام للإمام الحافظ تقي الدين، أبي محمد عبد الغني المقدسي الجماعيلي الحنبلي من أجود الكتب التي صنفت في أحاديث الأحكام، حيث انتقى المؤلف أحاديثه مما اتفق عليه الإمامان البخاري ومسلم في صحيحيهما إلا في القليل منها ممن انفرد به أحدهما، وألفه استجابة لطلب بعض طلبة العلم في اختصار جملة من أحاديث رسول الله - صلى الله عليه وسلم -، وقد أجاد فيه وأفاد، وسهل على طلبة العلم حفظه ودراسته حيث إن أحاديثه لاتزيد على أربعمائة حديث ونيف، والكتاب مشروح ومتداول بين أيدي الدارسين، وعنوانه اسم مطابق لمسماه فهو عمدة لكل من يرغب في دراسة الفقه الإسلامي على طريقة أهل الحديث والأثر، الذين يدورون مع الدليل الصحيح أينما دار لتطمئن بذلك قلوبهم بأنهم يعبدون الله بما شرع على لسان نبيه - صلى الله عليه وسلم -.\nوإسهاما في خدمة الكتاب قمت بشرح غريبه بشكل مختصر ليكون بجانب المتن معينا لمن عقد العزم على حفظه ودراسته، عسى أن أحظى بدعوة مستجابة بظهر الغيب من قلب مخلص بمغفرة ذنوبى والعفو عن زلاتي تنفعني في قبري ويوم القيامة عند لقاء ربي، وأرجو من كل من يجد خطأ أن يخبرني به لتصحيحه وله مني الشكر والتقدير.\nوآخر دعوانا أن الحمد لله رب العالمين\nعادل بن حسن نصار\nدير البلح/ غزة / فلسطين\nتلفاكس/ 2535022"},{"id":"umdat-ahkam:3","bookId":"umdat-ahkam","type":"section","seq":3,"chapter":"مقدمة","title":"مقدمة المؤلف","page":"ص0","text":"بسم الله الرحمن الرحيم\nقال الشيخ الحافظ، تقي الدين، أبو محمد عبد الغني بن عبد الواحد بن على بن سرور المقدسي - رحمه الله تعالى -:\nالحمد لله الملك الجبار، الواحد القهار. وأشهد أن لاإله إلاالله وحده لاشريك له، رب السموات والأرض ومابينهما العزيز الغفار، وأشهد أن محمدا عبده ورسوله المصطفى المختار. صلى الله عليه وعلى آله وصحبه الأخيار. أما بعد:\nفإن بعض إخواني سألني اختصار جملة في أحاديث الأحكام، مما اتفق عليه الإمامان: أبو عبد الله محمد بن إسماعيل بن إبراهيم البخاري، ومسلم بن الحجاج بن مسلم القشيري"},{"id":"umdat-ahkam:4","bookId":"umdat-ahkam","type":"section","seq":4,"chapter":"مقدمة","title":"ص: 30","page":"ص0","text":"النيسابوري.\nفأجبته إلى سؤاله رجاء المنفعة به.\nوأسأل الله أن ينفعنا به، ومن كتبه أوسمعه أوقرأه أو حفظه أو نظر فيه، وأن يجعله خالصا لوجهه الكريم، موجبا للفوز لديه في جنات النعيم. فإنه حسبنا ونعم الوكيل."},{"id":"umdat-ahkam:5","bookId":"umdat-ahkam","type":"section","seq":5,"chapter":"كتاب الطهارة","title":"1- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ج1 ص31","text":"عن عمر بن الخطاب - رضي الله عنه - قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((إنما الأعمال بالنيات - وفي رواية: بالنية - وإنما لكل امرئ ما نوى , فمن كانت هجرته إلى الله ورسوله , فهجرته إلى الله ورسوله , ومن كانت هجرته إلى دنيا يصيبها أو امرأة يتزوجها , فهجرته إلى ما هاجر إليه)) .\nالنية: القصد والعزم على الشيء."},{"id":"umdat-ahkam:6","bookId":"umdat-ahkam","type":"section","seq":6,"chapter":"كتاب الطهارة","title":"2- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا يقبل الله صلاة أحدكم إذا أحدث حتى يتوضأ))\nأحدث: حصل منه الحدث، وهو الخارج من أحد السبيلين أوغيره من نواقض الوضوء"},{"id":"umdat-ahkam:7","bookId":"umdat-ahkam","type":"section","seq":7,"chapter":"كتاب الطهارة","title":"3- عن عبد الله بن عمرو بن العاص وأبي هريرة وعائشة","page":"ص0","text":"عن عبد الله بن عمرو بن العاص وأبي هريرة وعائشة"},{"id":"umdat-ahkam:8","bookId":"umdat-ahkam","type":"section","seq":8,"chapter":"كتاب الطهارة","title":"ص: 32","page":"ص0","text":"رضي الله عنهم قالوا: قال رسول الله - صلى الله عليه وسلم -:\n((ويل للأعقاب من النار)) .\nالويل: العذاب والهلاك، وجاء في بعض الآثار أنه واد في جهنم.\nالأعقاب: جمع عقب، وهو مؤخر القدم. والمراد أصحابها."},{"id":"umdat-ahkam:9","bookId":"umdat-ahkam","type":"section","seq":9,"chapter":"كتاب الطهارة","title":"4- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((إذا توضأ أحدكم فليجعل في أنفه ماء , ثم لينتثر , ومن استجمر فليوتر , وإذا استيقظ أحدكم من نومه فليغسل يديه قبل أن يدخلهما في الإناء ثلاثا، فإن أحدكم لا يدري أين باتت يده)) .\nوفي لفظ لمسلم: ((فليستنشق بمنخريه من الماء))\nوفي لفظ: ((من توضأ فليستنشق)) .\nلينثر: يعني يخرج الماء من أنفه، بعد إدخاله فيه، وهو الاستنشاق.\nاستجمر: استعمل الحجارة في مسح البول والغائط.\nفليوتر: أي لينه استجماره على وتر، ثلاث أوخمس أوأكثر.\nفليستنشق: الاستنشاق هو إدخال الماء في الأنف ثم نثره خارجه."},{"id":"umdat-ahkam:10","bookId":"umdat-ahkam","type":"section","seq":10,"chapter":"كتاب الطهارة","title":"5- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال:"},{"id":"umdat-ahkam:11","bookId":"umdat-ahkam","type":"section","seq":11,"chapter":"كتاب الطهارة","title":"ص: 33","page":"ص0","text":"((لا يبولن أحدكم في الماء الدائم الذي لا يجري , ثم يغتسل منه)) ولمسلم: ((لا يغتسل أحدكم في الماء الدائم وهو جنب)) .\nالماء الدائم: المستقر في مكانه كالغدران والبرك.\nجنب: الجنب، من أصابته الجنابة، يطلق على المذكر والمؤنث، والفرد والجماعة."},{"id":"umdat-ahkam:12","bookId":"umdat-ahkam","type":"section","seq":12,"chapter":"كتاب الطهارة","title":"6- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -، أن رسول الله - صلى الله عليه وسلم - قال: ((إذا شرب الكلب في إناء أحدكم فليغسله سبعا)) .\nولمسلم: ((أولاهن بالتراب)) ."},{"id":"umdat-ahkam:13","bookId":"umdat-ahkam","type":"section","seq":13,"chapter":"كتاب الطهارة","title":"7- وله في حديث عبد الله بن مغفل","page":"ص0","text":"وله في حديث عبد الله بن مغفل: أن رسول الله - صلى الله عليه وسلم - قال: ((إذا ولغ الكلب في الإناء فاغسلوه سبعا وعفروه الثامنة بالتراب)) .\nولغ: شرب بطرف لسانه\nعفروه: التعفير: التمريغ في العفر وهو التراب."},{"id":"umdat-ahkam:14","bookId":"umdat-ahkam","type":"section","seq":14,"chapter":"كتاب الطهارة","title":"8- عن حمران مولى عثمان بن عفان رضي الله عنهما","page":"ص0","text":"عن حمران مولى عثمان بن عفان رضي الله عنهما: ((أنه رأى عثمان دعا بوضوء , فأفرغ على يديه من إنائه , فغسلهما ثلاث مرات، ثم أدخل يمينه في الوضوء , ثم تمضمض واستنشق واستنثر، ثم غسل وجهه ثلاثا , ويديه إلى المرفقين ثلاثا , ثم مسح برأسه , ثم غسل كلتا رجليه ثلاثا , ثم قال: رأيت النبي - صلى الله عليه وسلم - يتوضأ نحو وضوئي هذا، وقال: ((من توضأ نحو وضوئي هذا , ثم صلى ركعتين , لا يحدث فيهما نفسه غفر له ما تقدم من ذنبه))\nبوضوء: الوضوء بفتح الواو، معناه الماء الذي يتوضأ به، وبضمها، فعل الوضوء."},{"id":"umdat-ahkam:15","bookId":"umdat-ahkam","type":"section","seq":15,"chapter":"كتاب الطهارة","title":"9- عن عمرو بن يحيى المازني عن أبيه قال","page":"ص0","text":"عن عمرو بن يحيى المازني عن أبيه قال: ((شهدت عمرو بن أبي حسن سأل عبد الله بن زيد عن وضوء النبي - صلى الله عليه وسلم -؟ فدعا بتور من ماء , فتوضأ لهم وضوء رسول الله - صلى الله عليه وسلم - فأكفأ على يديه من التور , فغسل يديه ثلاثا , ثم أدخل يده في التور , فمضمض واستنشق واستنثر ثلاثا بثلاث غرفات , ثم أدخل يده فغسل وجهه ثلاثا , ثم أدخل يده في التور , فغسلهما مرتين إلى المرفقين ثم أدخل"},{"id":"umdat-ahkam:16","bookId":"umdat-ahkam","type":"section","seq":16,"chapter":"كتاب الطهارة","title":"ص: 35","page":"ص0","text":"يده في التور , فمسح رأسه , فأقبل بهما وأدبر مرة واحدة، ثم غسل رجليه)) .\nوفي رواية: ((بدأ بمقدم رأسه , حتى ذهب بهما إلى قفاه , ثم ردهما حتى رجع إلى المكان الذي بدأ منه)) . وفي رواية ((أتانا رسول الله - صلى الله عليه وسلم - فأخرجنا له ماء في تور من صفر)) . التور: شبه الطست. أه\nالتور: هو إناء صغير.\nفأكفأ على يديه: أمال وصب على يديه.\nقفاه: مؤخرة رأسه.\nمن صفر: هو نوع من النحاس."},{"id":"umdat-ahkam:17","bookId":"umdat-ahkam","type":"section","seq":17,"chapter":"كتاب الطهارة","title":"10- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان رسول الله - صلى الله عليه وسلم - يعجبه التيمن في تنعله , وترجله , وطهوره , وفي شأنه كله)) .\nيعجبه التيمن: استعمال اليد اليمين، والبدء باليمين في كل ماهو شريف وطاهر وطيب.\nتنعله: لبس النعل وهو الحذاء.\nترجله: تسريح شعره بالمشط.\nطهوره: بضم الطاء: يشمل الوضوء والغسل.\nوفي شأنه كله: في الأمور الشريفة المستطابة."},{"id":"umdat-ahkam:18","bookId":"umdat-ahkam","type":"section","seq":18,"chapter":"كتاب الطهارة","title":"11- عن نعيم المجمر عن أبي هريرة - رضي الله عنه - عن","page":"ص0","text":"عن نعيم المجمر عن أبي هريرة - رضي الله عنه - عن"},{"id":"umdat-ahkam:19","bookId":"umdat-ahkam","type":"section","seq":19,"chapter":"كتاب الطهارة","title":"ص: 36","page":"ص0","text":"النبي - صلى الله عليه وسلم - أنه قال: ((إن أمتي يدعون يوم القيامة غرا محجلين من آثار الوضوء)) . فمن استطاع منكم أن يطيل غرته فليفعل.\nوفي لفظ لمسلم: ((رأيت أبا هريرة يتوضأ , فغسل وجهه ويديه حتى كاد يبلغ المنكبين , ثم غسل رجليه حتى رفع إلى الساقين , ثم قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: إن أمتي يدعون يوم القيامة غرا محجلين من آثار الوضوء)) فمن استطاع منكم أن يطيل غرته وتحجيله فليفعل."},{"id":"umdat-ahkam:20","bookId":"umdat-ahkam","type":"section","seq":20,"chapter":"كتاب الطهارة","title":"12- وفي لفظ لمسلم","page":"ص0","text":"وفي لفظ لمسلم: سمعت خليلي - صلى الله عليه وسلم - يقول: ((تبلغ الحلية من المؤمن حيث يبلغ الوضوء)) ."},{"id":"umdat-ahkam:21","bookId":"umdat-ahkam","type":"section","seq":21,"chapter":"كتاب الطهارة","title":"ص: 37","page":"ص0","text":"يدعون: ينادون.\nغرا: الغرة: بياض في وجه الفرس، أطلقت على نور وجوههم المشبهة بغرة الفرس.\nمحجلين: من التحجيل وهو بياض في قوائم الفرس. والمراد بذلك النور الذي يعلو وجوههم وأيديهم وأرجلهم يوم القيامة، وهذا من خصائص هذه الأمة.\nالحلية: حلية النور التي تبلغ مابلغ ماء الوضوء."},{"id":"umdat-ahkam:22","bookId":"umdat-ahkam","type":"section","seq":22,"chapter":"كتاب الطهارة","title":"13- عن أنس بن مالك - رضي الله عنه -","page":"ج1 ص37","text":"عن أنس بن مالك - رضي الله عنه -: أن النبي - صلى الله عليه وسلم - كان إذا دخل الخلاء قال: ((اللهم إني أعوذ بك من الخبث والخبائث)) .\nالاستطابة: الاستنجاء.\nالخبث: بضم الخاء والباء، جمع خبيث، وهم ذكران الشياطين.\nالخبائث: جمع خبيثة، وهن إناث الشياطين.","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:23","bookId":"umdat-ahkam","type":"section","seq":23,"chapter":"كتاب الطهارة","title":"14- عن أبي أيوب الأنصاري - رضي الله عنه - قال","page":"ص0","text":"عن أبي أيوب الأنصاري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إذا أتيتم الغائط , فلا تستقبلوا القبلة بغائط ولا بول , ولا تستدبروها , ولكن شرقوا أو غربوا)) .","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:24","bookId":"umdat-ahkam","type":"section","seq":24,"chapter":"كتاب الطهارة","title":"ص: 38","page":"ص0","text":"قال أبو أيوب: «فقدمنا الشام , فوجدنا مراحيض قد بنيت نحو الكعبة , فننحرف عنها , ونستغفر الله عز وجل» .\nشرقوا أو غربوا: اتجهوا نحو المشرق أوالمغرب. وهذا بالنسبة لأهل المدينة المنورة.","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:25","bookId":"umdat-ahkam","type":"section","seq":25,"chapter":"كتاب الطهارة","title":"15- عن عبد الله بن عمر بن الخطاب رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر بن الخطاب رضي الله عنهما قال: ((رقيت يوما على بيت حفصة , فرأيت النبي - صلى الله عليه وسلم - يقضي حاجته مستقبل الشام , مستدبر الكعبة)) . وفي رواية ((مستقبلا بيت المقدس)) .\nرقيت: صعدت.","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:26","bookId":"umdat-ahkam","type":"section","seq":26,"chapter":"كتاب الطهارة","title":"16- عن أنس بن مالك - رضي الله عنه - أنه قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - أنه قال: ((كان رسول الله - صلى الله عليه وسلم - يدخل الخلاء , فأحمل أنا وغلام نحوي إداوة من ماء وعنزة , فيستنجي بالماء)) .\nالعنزة: الحربة الصغيرة. والإداوة: إناء صغير من جلد.\nغلام نحوي: غلام مقارب لي في السن.","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:27","bookId":"umdat-ahkam","type":"section","seq":27,"chapter":"كتاب الطهارة","title":"17- عن أبي قتادة الحارث بن ربعي الأنصاري - رضي الله عنه -","page":"ص0","text":"عن أبي قتادة الحارث بن ربعي الأنصاري - رضي الله عنه -: أن النبي - صلى الله عليه وسلم - قال: ((لا يمسكن أحدكم ذكره بيمينه وهو يبول ولا يتمسح من الخلاء بيمينه ولا يتنفس في الإناء)) .","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:28","bookId":"umdat-ahkam","type":"section","seq":28,"chapter":"كتاب الطهارة","title":"18- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: مر النبي - صلى الله عليه وسلم - بقبرين , فقال: ((إنهما ليعذبان , وما يعذبان في كبير أما أحدهما: فكان لا يستتر من البول , وأما الآخر: فكان يمشي بالنميمة فأخذ جريدة رطبة , فشقها نصفين , فغرز في كل قبر واحدة، فقالوا: يا رسول الله , لم فعلت هذا؟ قال: لعله يخفف عنهما ما لم ييبسا)) .\nلايستتر من البول: لايجعل سترة تقيه من بوله.\nالنميمة: نقل كلام الغير على وجه الإفساد والإضرار.","bab":"باب دخول الخلاء والاستطابة"},{"id":"umdat-ahkam:29","bookId":"umdat-ahkam","type":"section","seq":29,"chapter":"كتاب الطهارة","title":"19- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ج1 ص39","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة)) .","bab":"باب السواك"},{"id":"umdat-ahkam:30","bookId":"umdat-ahkam","type":"section","seq":30,"chapter":"كتاب الطهارة","title":"ص: 40","page":"ج1 ص39","text":"السواك: اسم للعود الذي يتسوك به، ولفعل الاستياك نفسه. وخير مايستاك به عود جذور شجر الأراك.","bab":"باب السواك"},{"id":"umdat-ahkam:31","bookId":"umdat-ahkam","type":"section","seq":31,"chapter":"كتاب الطهارة","title":"20- عن حذيفة بن اليمان رضي الله عنهما قال","page":"ص0","text":"عن حذيفة بن اليمان رضي الله عنهما قال: ((كان رسول الله - صلى الله عليه وسلم - إذا قام من الليل يشوص فاه بالسواك)) .\nيشوص فاه: يدلك أسنانه وينقيها.","bab":"باب السواك"},{"id":"umdat-ahkam:32","bookId":"umdat-ahkam","type":"section","seq":32,"chapter":"كتاب الطهارة","title":"21- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((دخل عبد الرحمن بن أبي بكر الصديق - رضي الله عنه - على النبي - صلى الله عليه وسلم - وأنا مسندته إلى صدري , ومع عبد الرحمن سواك رطب يستن به فأبده رسول الله - صلى الله عليه وسلم - بصره. فأخذت السواك فقضمته , فطيبته , ثم دفعته إلى النبي - صلى الله عليه وسلم - فاستن به فما رأيت رسول الله - صلى الله عليه وسلم - استن استنانا أحسن منه , فما عدا أن فرغ رسول الله - صلى الله عليه وسلم -: رفع يده - أو إصبعه - ثم قال: في الرفيق الأعلى - ثلاثا - ثم قضى. وكانت تقول: مات بين حاقنتي وذاقنتي)) .","bab":"باب السواك"},{"id":"umdat-ahkam:33","bookId":"umdat-ahkam","type":"section","seq":33,"chapter":"كتاب الطهارة","title":"ص: 41","page":"ص0","text":"وفي لفظ ((فرأيته ينظر إليه , وعرفت: أنه يحب السواك فقلت: آخذه لك؟ فأشار برأسه: أن نعم)) هذا لفظ البخاري ولمسلم نحوه.\nيستن به: يمر السواك على أسنانه.\nفأبده: مد إليه بصره وأطاله.\nبين حاقنتي وذاقنتي: الحاقنة: مابين الترقوتين وحبل العاتق، والذاقنة: طرف الحلقوم الأعلى.\nفقضمته: مضغته بأسنانها ليكون لينا.","bab":"باب السواك"},{"id":"umdat-ahkam:34","bookId":"umdat-ahkam","type":"section","seq":34,"chapter":"كتاب الطهارة","title":"22- عن أبي موسى الأشعري - رضي الله عنه - قال","page":"ص0","text":"عن أبي موسى الأشعري - رضي الله عنه - قال: ((أتيت النبي - صلى الله عليه وسلم - وهو يستاك بسواك رطب , قال: وطرف السواك على لسانه , وهو يقول: أع , أع , والسواك في فيه , كأنه يتهوع)) .\nيتهوع: يتقيأ.","bab":"باب السواك"},{"id":"umdat-ahkam:35","bookId":"umdat-ahkam","type":"section","seq":35,"chapter":"كتاب الطهارة","title":"23- عن المغيرة بن شعبة - رضي الله عنه - قال","page":"ج1 ص41","text":"عن المغيرة بن شعبة - رضي الله عنه - قال: ((كنت مع النبي - صلى الله عليه وسلم - في سفر , فأهويت لأنزع خفيه , فقال: دعهما , فإني أدخلتهما طاهرتين , فمسح عليهما)) .\nفأهويت لأنزع خفيه: مددت يدي لإخراجهما من رجليه لغسلهما.\nخفيه: تثنية خف، وهو نعل من جلد يغطي القدمين.","bab":"باب المسح على الخفين"},{"id":"umdat-ahkam:36","bookId":"umdat-ahkam","type":"section","seq":36,"chapter":"كتاب الطهارة","title":"24- عن حذيفة بن اليمان رضي الله عنهما قال","page":"ص0","text":"عن حذيفة بن اليمان رضي الله عنهما قال: ((كنت مع النبي - صلى الله عليه وسلم - فبال , وتوضأ , ومسح على خفيه)) .","bab":"باب المسح على الخفين"},{"id":"umdat-ahkam:37","bookId":"umdat-ahkam","type":"section","seq":37,"chapter":"كتاب الطهارة","title":"25- عن علي بن أبي طالب - رضي الله عنه - قال","page":"ج1 ص42","text":"عن علي بن أبي طالب - رضي الله عنه - قال: ((كنت رجلا مذاء , فاستحييت أن أسأل رسول الله - صلى الله عليه وسلم - لمكان ابنته مني , فأمرت المقداد بن الأسود فسأله , فقال: يغسل ذكره , ويتوضأ)) .\nوللبخاري ((اغسل ذكرك وتوضأ)) . ولمسلم ((توضأ وانضح فرجك)) .\nالمذي: سائل يخرج من الرجل والمرأة عند الشهوة، ويخرج بلا تدفق ولالذة.\nمذاء: كثير المذي.\nانضح فرجك: اغسل فرجك.","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:38","bookId":"umdat-ahkam","type":"section","seq":38,"chapter":"كتاب الطهارة","title":"26- عن عباد بن تميم عن عبد الله بن زيد بن عاصم المازني - رضي الله عنه - قال","page":"ص0","text":"عن عباد بن تميم عن عبد الله بن زيد بن عاصم المازني - رضي الله عنه - قال: ((شكي إلى النبي - صلى الله عليه وسلم - الرجل يخيل إليه أنه يجد الشيء في الصلاة, فقال: لا ينصرف حتى يسمع صوتا, أو يجد ريحا)) .","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:39","bookId":"umdat-ahkam","type":"section","seq":39,"chapter":"كتاب الطهارة","title":"27- عن أم قيس بنت محصن الأسدية","page":"ص0","text":"عن أم قيس بنت محصن الأسدية ((أنها أتت بابن لها","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:40","bookId":"umdat-ahkam","type":"section","seq":40,"chapter":"كتاب الطهارة","title":"ص: 43","page":"ص0","text":"صغير , لم يأكل الطعام إلى رسول الله - صلى الله عليه وسلم - فأجلسه في حجره , فبال على ثوبه , فدعا بماء فنضحه على ثوبه , ولم يغسله)) .\nنضحه: رشه.","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:41","bookId":"umdat-ahkam","type":"section","seq":41,"chapter":"كتاب الطهارة","title":"28- وعن عائشة أم المؤمنين رضي الله عنها","page":"ص0","text":"وعن عائشة أم المؤمنين رضي الله عنها ((أن النبي - صلى الله عليه وسلم - أتي بصبي , فبال على ثوبه , فدعا بماء , فأتبعه إياه)) ولمسلم: ((فأتبعه بوله , ولم يغسله)) .","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:42","bookId":"umdat-ahkam","type":"section","seq":42,"chapter":"كتاب الطهارة","title":"29- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: ((جاء أعرابي , فبال في طائفة المسجد , فزجره الناس , فنهاهم النبي - صلى الله عليه وسلم - فلما قضى بوله أمر النبي - صلى الله عليه وسلم - بذنوب من ماء , فأهريق عليه)) .","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:43","bookId":"umdat-ahkam","type":"section","seq":43,"chapter":"كتاب الطهارة","title":"ص: 44","page":"ص0","text":"طائفة المسجد: ناحية المسجد.\nفزجره الناس: نهروه.\nالذنوب: الدلو الكبير مليء بالماء.\nأهريق عليه: صب عليه.","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:44","bookId":"umdat-ahkam","type":"section","seq":44,"chapter":"كتاب الطهارة","title":"30- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((الفطرة خمس: الختان , والاستحداد , وقص الشارب , وتقليم الأظفار , ونتف الإبط)) .\nالختان: قطع الجلدة التي تغطي الحشفة في الذكر لكي لايجتمع فيها الأوساخ.\nالاستحداد: حلق شعر العانة.","bab":"باب في المذي وغيره"},{"id":"umdat-ahkam:45","bookId":"umdat-ahkam","type":"section","seq":45,"chapter":"كتاب الطهارة","title":"31- عن أبي هريرة - رضي الله عنه -","page":"ج1 ص44","text":"عن أبي هريرة - رضي الله عنه - ((أن النبي - صلى الله عليه وسلم - لقيه في بعض طرق المدينة وهو جنب، قال: فانخنست منه، فذهبت فاغتسلت ثم جئت، فقال: أين كنت ياأبا هريرة؟ قال: كنت جنبا فكرهت أن أجالسك على غير طهارة، فقال: سبحان الله، إن المؤمن لاينجس)) .","bab":"باب الجنابة"},{"id":"umdat-ahkam:46","bookId":"umdat-ahkam","type":"section","seq":46,"chapter":"كتاب الطهارة","title":"ص: 45","page":"ج1 ص44","text":"انخنست: من الخنوس، وهو التأخر والاختفاء والتستر.","bab":"باب الجنابة"},{"id":"umdat-ahkam:47","bookId":"umdat-ahkam","type":"section","seq":47,"chapter":"كتاب الطهارة","title":"32- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان النبي - صلى الله عليه وسلم - إذا اغتسل من الجنابة غسل يديه , ثم توضأ وضوءه للصلاة , ثم اغتسل , ثم يخلل بيديه شعره , حتى إذا ظن أنه قد أروى بشرته , أفاض عليه الماء ثلاث مرات , ثم غسل سائر جسده ,","bab":"باب الجنابة"},{"id":"umdat-ahkam:48","bookId":"umdat-ahkam","type":"section","seq":48,"chapter":"كتاب الطهارة","title":"33- وكانت تقول","page":"ص0","text":"وكانت تقول: كنت أغتسل أنا ورسول الله - صلى الله عليه وسلم - من إناء واحد , نغترف منه جميعا)) .\nأروى بشرته: أوصل الماء إلى أصول الشعر، والبشرة: الجلد.\nأفاض عليه: أسال الماء على شعره.","bab":"باب الجنابة"},{"id":"umdat-ahkam:49","bookId":"umdat-ahkam","type":"section","seq":49,"chapter":"كتاب الطهارة","title":"34- عن ميمونة بنت الحارث رضي الله عنها زوج النبي - صلى الله عليه وسلم - أنها قالت","page":"ص0","text":"عن ميمونة بنت الحارث رضي الله عنها زوج النبي - صلى الله عليه وسلم - أنها قالت: ((وضعت لرسول الله - صلى الله عليه وسلم - وضوء الجنابة , فأكفأ بيمينه على يساره مرتين - أو ثلاثا - ثم غسل فرجه , ثم ضرب يده بالأرض , أو الحائط , مرتين - أو ثلاثا - ثم تمضمض واستنشق , وغسل وجهه وذراعيه , ثم أفاض على رأسه الماء , ثم غسل جسده , ثم تنحى , فغسل","bab":"باب الجنابة"},{"id":"umdat-ahkam:50","bookId":"umdat-ahkam","type":"section","seq":50,"chapter":"كتاب الطهارة","title":"ص: 46","page":"ص0","text":"رجليه , فأتيته بخرقة فلم يردها , فجعل ينفض الماء بيده)) .\nفلم يردها: من الإرادة لا من الرد.","bab":"باب الجنابة"},{"id":"umdat-ahkam:51","bookId":"umdat-ahkam","type":"section","seq":51,"chapter":"كتاب الطهارة","title":"35- عن عبد الله بن عمر","page":"ص0","text":"عن عبد الله بن عمر: أن عمر بن الخطاب - رضي الله عنه - قال: ((يا رسول الله , أيرقد أحدنا وهو جنب؟ قال: نعم , إذا توضأ أحدكم فليرقد)) .\nيرقد: ينام.","bab":"باب الجنابة"},{"id":"umdat-ahkam:52","bookId":"umdat-ahkam","type":"section","seq":52,"chapter":"كتاب الطهارة","title":"36- عن أم سلمة رضي الله عنها - زوج النبي - صلى الله عليه وسلم - قالت","page":"ص0","text":"عن أم سلمة رضي الله عنها - زوج النبي - صلى الله عليه وسلم - قالت: ((جاءت أم سليم امرأة أبي طلحة - إلى رسول الله - صلى الله عليه وسلم - فقالت: يا رسول الله , إن الله لا يستحيي من الحق , فهل على المرأة من غسل إذا هي احتلمت؟ فقال رسول الله - صلى الله عليه وسلم -: نعم , إذا رأت الماء)) .","bab":"باب الجنابة"},{"id":"umdat-ahkam:53","bookId":"umdat-ahkam","type":"section","seq":53,"chapter":"كتاب الطهارة","title":"ص: 47","page":"ص0","text":"احتلمت: الاحتلام: هو مايراه النائم في نومه، ومايصحب ذلك من إنزال المني، ويكون من الرجل والمرأة.","bab":"باب الجنابة"},{"id":"umdat-ahkam:54","bookId":"umdat-ahkam","type":"section","seq":54,"chapter":"كتاب الطهارة","title":"37- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كنت أغسل الجنابة من ثوب رسول الله - صلى الله عليه وسلم - فيخرج إلى الصلاة , وإن بقع الماء في ثوبه)) .\nوفي لفظ لمسلم ((لقد كنت أفركه من ثوب رسول الله - صلى الله عليه وسلم - فركا, فيصلي فيه)) .","bab":"باب الجنابة"},{"id":"umdat-ahkam:55","bookId":"umdat-ahkam","type":"section","seq":55,"chapter":"كتاب الطهارة","title":"38- عن أبي هريرة - رضي الله عنه - أن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - أن النبي - صلى الله عليه وسلم - قال: ((إذا جلس بين شعبها الأربع , ثم جهدها , فقد وجب الغسل)) , وفي لفظ ((وإن لم ينزل)) .\nشعبها الأربع: رجلاها ويداها، وهو كناية عن الجماع.\nجهدها: بلغ المشقة بكدها، وهو كناية عن المباشرة بالتقاء الختانين.","bab":"باب الجنابة"},{"id":"umdat-ahkam:56","bookId":"umdat-ahkam","type":"section","seq":56,"chapter":"كتاب الطهارة","title":"39- عن أبي جعفر محمد بن علي بن الحسين بن علي بن أبي طالب رضي الله عنهم","page":"ص0","text":"عن أبي جعفر محمد بن علي بن الحسين بن علي بن أبي طالب رضي الله عنهم ((أنه كان هو وأبوه عند جابر بن عبد الله ,","bab":"باب الجنابة"},{"id":"umdat-ahkam:57","bookId":"umdat-ahkam","type":"section","seq":57,"chapter":"كتاب الطهارة","title":"ص: 48","page":"ص0","text":"وعنده قوم , فسألوه عن الغسل؟ فقال: صاع يكفيك، فقال رجل: ما يكفيني , فقال جابر: كان يكفي من هو أوفى منك شعرا , وخيرا منك - يريد رسول الله - صلى الله عليه وسلم - ثم أمنا في ثوب)) , وفي لفظ ((كان رسول الله - صلى الله عليه وسلم - يفرغ الماء على رأسه ثلاثا)) .\nالصاع: مكيال يسع أربعة أمداد، والمد: ملء كفي الرجل الوسط.","bab":"باب الجنابة"},{"id":"umdat-ahkam:58","bookId":"umdat-ahkam","type":"section","seq":58,"chapter":"كتاب الطهارة","title":"40- عن عمران بن حصين - رضي الله عنه -","page":"ج1 ص48","text":"عن عمران بن حصين - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - رأى رجلا معتزلا , لم يصل في القوم؟ فقال: يا فلان , ما منعك أن تصلي في القوم؟ فقال: يا رسول الله أصابتني جنابة , ولا ماء , فقال: عليك بالصعيد , فإنه يكفيك)) .\nالتيمم لغة: القصد، قال تعالى: (ولا آمين البيت الحرام) [المائدة:2] .\nالتيمم شرعا: هو القصد إلى الصعيد لمسح الوجه واليدين بنية استباحة الصلاة وغيرها\nالصعيد: التراب.\nيكفيك: يجزئك عن الماء.","bab":"باب التيمم"},{"id":"umdat-ahkam:59","bookId":"umdat-ahkam","type":"section","seq":59,"chapter":"كتاب الطهارة","title":"41- عن عمار بن ياسر رضي الله عنهما قال","page":"ص0","text":"عن عمار بن ياسر رضي الله عنهما قال: ((بعثني النبي - صلى الله عليه وسلم - في حاجة , فأجنبت , فلم أجد الماء , فتمرغت في الصعيد , كما تمرغ الدابة , ثم أتيت النبي - صلى الله عليه وسلم - فذكرت ذلك له , فقال: إنما","bab":"باب التيمم"},{"id":"umdat-ahkam:60","bookId":"umdat-ahkam","type":"section","seq":60,"chapter":"كتاب الطهارة","title":"ص: 49","page":"ص0","text":"يكفيك أن تقول بيديك هكذا - ثم ضرب بيديه الأرض ضربة واحدة , ثم مسح الشمال على اليمين , وظاهر كفيه ووجهه)) .\nتمرغت في الصعيد: تقلبت في الأرض حتى عم بدني التراب.","bab":"باب التيمم"},{"id":"umdat-ahkam:61","bookId":"umdat-ahkam","type":"section","seq":61,"chapter":"كتاب الطهارة","title":"42- عن جابر بن عبد الله رضي الله عنهما","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما: أن النبي - صلى الله عليه وسلم - قال: ((أعطيت خمسا, لم يعطهن أحد من الأنبياء قبلي: نصرت بالرعب مسيرة شهر , وجعلت لي الأرض مسجدا وطهورا , فأيما رجل من أمتي أدركته الصلاة فليصل , وأحلت لي المغانم , ولم تحل لأحد قبلي , وأعطيت الشفاعة، وكان النبي يبعث إلى قومه خاصة , وبعثت إلى الناس عامة)) .\nنصرت بالرعب: أي ينصرني الله بإلقاء الخوف في قلوب أعدائي.","bab":"باب التيمم"},{"id":"umdat-ahkam:62","bookId":"umdat-ahkam","type":"section","seq":62,"chapter":"كتاب الطهارة","title":"43- عن عائشة رضي الله عنها","page":"ج1 ص49","text":"عن عائشة رضي الله عنها ((أن فاطمة بنت أبي حبيش: سألت النبي - صلى الله عليه وسلم - فقالت: إني أستحاض فلا أطهر , أفأدع الصلاة؟ قال: لا، إن ذلك عرق , ولكن دعي الصلاة قدر الأيام التي كنت تحيضين فيها , ثم اغتسلي وصلي)) .","bab":"باب الحيض"},{"id":"umdat-ahkam:63","bookId":"umdat-ahkam","type":"section","seq":63,"chapter":"كتاب الطهارة","title":"ص: 50","page":"ج1 ص49","text":"وفي رواية ((وليست بالحيضة , فإذا أقبلت الحيضة: فاتركي الصلاة فيها , فإذا ذهب قدرها فاغسلي عنك الدم وصلي)) .\nالحيض: جريان دم المرأة في أوقات معلومة يرخيه رحمها بعد بلوغها.\nالاستحاضة: جريان الدم في غير أوانه.\nعرق: يقال له: العاذل، ويكون في أدنى الرحم يسيل منه الدم في غير أيام الحيض.","bab":"باب الحيض"},{"id":"umdat-ahkam:64","bookId":"umdat-ahkam","type":"section","seq":64,"chapter":"كتاب الطهارة","title":"44- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها ((أن أم حبيبة استحيضت سبع سنين , فسألت رسول الله - صلى الله عليه وسلم - عن ذلك؟ فأمرها أن تغتسل , قالت: فكانت تغتسل لكل صلاة)) .","bab":"باب الحيض"},{"id":"umdat-ahkam:65","bookId":"umdat-ahkam","type":"section","seq":65,"chapter":"كتاب الطهارة","title":"45- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كنت أغتسل أنا ورسول الله - صلى الله عليه وسلم - من إناء واحد , كلانا جنب.","bab":"باب الحيض"},{"id":"umdat-ahkam:66","bookId":"umdat-ahkam","type":"section","seq":66,"chapter":"كتاب الطهارة","title":"46- وكان يأمرني فأتزر","page":"ص0","text":"وكان يأمرني فأتزر , فيباشرني وأنا حائض.","bab":"باب الحيض"},{"id":"umdat-ahkam:67","bookId":"umdat-ahkam","type":"section","seq":67,"chapter":"كتاب الطهارة","title":"47- وكان يخرج رأسه إلي","page":"ص0","text":"وكان يخرج رأسه إلي , وهو معتكف , فأغسله وأنا حائض)) .\nأتزر: أي تشد إزارا يسترها من السرة إلى الركبة وماتحتها.\nيباشرني: المباشرة هنا الاستمتاع من غير جماع.","bab":"باب الحيض"},{"id":"umdat-ahkam:68","bookId":"umdat-ahkam","type":"section","seq":68,"chapter":"كتاب الطهارة","title":"48- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان رسول الله - صلى الله عليه وسلم - يتكئ في حجري , فيقرأ القرآن وأنا حائض)) .\nالحجر: حضن الإنسان.","bab":"باب الحيض"},{"id":"umdat-ahkam:69","bookId":"umdat-ahkam","type":"section","seq":69,"chapter":"كتاب الطهارة","title":"49- عن معاذة قالت","page":"ص0","text":"عن معاذة قالت: ((سألت عائشة رضي الله عنها فقلت: ما بال الحائض تقضي الصوم , ولا تقضي الصلاة؟","bab":"باب الحيض"},{"id":"umdat-ahkam:70","bookId":"umdat-ahkam","type":"section","seq":70,"chapter":"كتاب الطهارة","title":"ص: 52","page":"ص0","text":"فقالت: أحرورية أنت؟ فقلت: لست بحرورية , ولكني أسأل. فقالت: كان يصيبنا ذلك , فنؤمر بقضاء الصوم , ولا نؤمر بقضاء الصلاة)) .","bab":"باب الحيض"},{"id":"umdat-ahkam:71","bookId":"umdat-ahkam","type":"section","seq":71,"chapter":"كتاب الطهارة","title":"ص: 53","page":"ص0","text":"أحرورية أنت: نسبة إلى بلدة قرب الكوفة، اسمها حروراء، خرجت منها فرقة من الخوارج على علي بن أبي طالب - رضي الله عنه -، ويسمى الخوارج حرورية لتعنتهم ومخالفتهم السنة وخروجهم على جماعة المسلمين.","bab":"باب الحيض"},{"id":"umdat-ahkam:72","bookId":"umdat-ahkam","type":"section","seq":72,"chapter":"كتاب الصلاة","title":"كتاب الصلاة","page":"ص0","text":"الصلاة لغة: الدعاء.\nوشرعا: أقوال وأفعال مخصوصة مفتتحة بالتكبير ومختتمة بالتسليم."},{"id":"umdat-ahkam:73","bookId":"umdat-ahkam","type":"section","seq":73,"chapter":"كتاب الصلاة","title":"باب المواقيت","page":"ج1 ص53","text":"المواقيت: جمع «ميقات» ، وهي المواقيت الزمانية، التي هي القدر المحدود لفعل الصلوات المفروضات وغيرها.45-","bab":"باب المواقيت"},{"id":"umdat-ahkam:74","bookId":"umdat-ahkam","type":"section","seq":74,"chapter":"كتاب الصلاة","title":"50- عن أبي عمرو الشيباني واسمه سعد بن إياس - قال","page":"ج1 ص53","text":"عن أبي عمرو الشيباني واسمه سعد بن إياس - قال: حدثني صاحب هذه الدار - وأشار بيده إلى دار عبد الله بن مسعود - رضي الله عنه - قال: ((سألت النبي - صلى الله عليه وسلم -: أي العمل أحب إلى الله؟ قال: الصلاة على وقتها. قلت: ثم أي؟ قال: بر الوالدين , قلت: ثم أي؟ قال: الجهاد في سبيل الله , قال: حدثني بهن رسول الله - صلى الله عليه وسلم - ولو استزدته لزادني)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:75","bookId":"umdat-ahkam","type":"section","seq":75,"chapter":"كتاب الصلاة","title":"51- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((لقد كان رسول الله - صلى الله عليه وسلم - يصلي الفجر , فيشهد معه نساء من المؤمنات , متلفعات بمروطهن","bab":"باب المواقيت"},{"id":"umdat-ahkam:76","bookId":"umdat-ahkam","type":"section","seq":76,"chapter":"كتاب الصلاة","title":"ص: 54","page":"ص0","text":"ثم يرجعن إلى بيوتهن ما يعرفهن أحد , من الغلس)) .\nالمروط: أكسية معلمة تكون من خز، وتكون من صوف. أه\nمتلفعات: متلحفات.\nوالغلس: اختلاط ضياء الصبح بظلمة الليل.","bab":"باب المواقيت"},{"id":"umdat-ahkam:77","bookId":"umdat-ahkam","type":"section","seq":77,"chapter":"كتاب الصلاة","title":"52- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((كان - صلى الله عليه وسلم - يصلي الظهر بالهاجرة , والعصر والشمس نقية والمغرب إذا وجبت , والعشاء أحيانا وأحيانا إذا رآهم اجتمعوا عجل. وإذا رآهم أبطئوا أخر , والصبح كان النبي - صلى الله عليه وسلم - يصليها بغلس)) .\nالهاجرة: شدة الحر بعد الزوال.\nنقية: صافية.\nوجبت: غابت.","bab":"باب المواقيت"},{"id":"umdat-ahkam:78","bookId":"umdat-ahkam","type":"section","seq":78,"chapter":"كتاب الصلاة","title":"53- عن أبي المنهال سيار بن سلامة قال","page":"ص0","text":"عن أبي المنهال سيار بن سلامة قال: ((دخلت أنا وأبي على أبي برزة الأسلمي , فقال له أبي: كيف كان النبي - صلى الله عليه وسلم - يصلي المكتوبة؟ فقال: كان يصلي الهجير - التي تدعونها","bab":"باب المواقيت"},{"id":"umdat-ahkam:79","bookId":"umdat-ahkam","type":"section","seq":79,"chapter":"كتاب الصلاة","title":"ص: 55","page":"ص0","text":"الأولى - حين تدحض الشمس , ويصلي العصر , ثم يرجع أحدنا إلى رحله في أقصى المدينة والشمس حية. ونسيت ما قال في المغرب. وكان يستحب أن يؤخر من العشاء التي تدعونها العتمة. وكان يكره النوم قبلها , والحديث بعدها. وكان ينفتل من صلاة الغداة حين يعرف الرجل جليسه. وكان يقرأ بالستين إلى المائة)) .\nالمكتوبة: المفروضة، وهي الصلوات الخمس.\nالأولى: هي الظهر، لأنها أول صلاة صلاها جبريل بالنبي - صلى الله عليه وسلم -.\nتدحض الشمس: تميل عن وسط السماء إلى ناحية الغروب.\nالعتمة: ظلمة الليل، والمقصود بها صلاة العشاء.\nينفتل من صلاة الغداة: ينصرف من صلاة الصبح.","bab":"باب المواقيت"},{"id":"umdat-ahkam:80","bookId":"umdat-ahkam","type":"section","seq":80,"chapter":"كتاب الصلاة","title":"54- عن علي - رضي الله عنه -","page":"ص0","text":"عن علي - رضي الله عنه -: أن النبي - صلى الله عليه وسلم - قال يوم الخندق: ((ملأ الله قبورهم وبيوتهم نارا , كما شغلونا عن الصلاة الوسطى حتى غابت الشمس)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:81","bookId":"umdat-ahkam","type":"section","seq":81,"chapter":"كتاب الصلاة","title":"ص: 56","page":"ص0","text":"وفي لفظ لمسلم ((شغلونا عن الصلاة الوسطى - صلاة العصر - ثم صلاها بين المغرب والعشاء)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:82","bookId":"umdat-ahkam","type":"section","seq":82,"chapter":"كتاب الصلاة","title":"55- وله عن عبد الله بن مسعود قال","page":"ص0","text":"وله عن عبد الله بن مسعود قال: ((حبس المشركون رسول الله - صلى الله عليه وسلم - عن العصر , حتى احمرت الشمس أو اصفرت , فقال رسول الله - صلى الله عليه وسلم -: شغلونا عن الصلاة الوسطى - صلاة العصر - ملأ الله أجوافهم وقبورهم نارا , أو حشا الله أجوافهم وقبورهم نارا)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:83","bookId":"umdat-ahkam","type":"section","seq":83,"chapter":"كتاب الصلاة","title":"56- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((أعتم النبي - صلى الله عليه وسلم - بالعشاء. فخرج عمر , فقال: الصلاة , يا رسول الله. رقد النساء والصبيان. فخرج ورأسه يقطر يقول: لولا أن أشق على أمتي - أو على الناس - لأمرتهم بهذه الصلاة هذه الساعة)) .\nأعتم: دخل في العتمة وهي ظلمة الليل، والمقصود أنه أخر صلاة العشاء بعد ذهاب الشفق.","bab":"باب المواقيت"},{"id":"umdat-ahkam:84","bookId":"umdat-ahkam","type":"section","seq":84,"chapter":"كتاب الصلاة","title":"57- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: أن النبي - صلى الله عليه وسلم - قال: ((إذا أقيمت","bab":"باب المواقيت"},{"id":"umdat-ahkam:85","bookId":"umdat-ahkam","type":"section","seq":85,"chapter":"كتاب الصلاة","title":"ص: 57","page":"ص0","text":"الصلاة , وحضر العشاء , فابدءوا بالعشاء)) .\nوعن ابن عمر نحوه.","bab":"باب المواقيت"},{"id":"umdat-ahkam:86","bookId":"umdat-ahkam","type":"section","seq":86,"chapter":"كتاب الصلاة","title":"58- ولمسلم عن عائشة رضي الله عنها قالت","page":"ج1 ص57","text":"ولمسلم عن عائشة رضي الله عنها قالت: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((لا صلاة بحضرة طعام , ولا وهو يدافعه الأخبثان)) .\nالأخبثان: البول والغائط.","bab":"باب المواقيت"},{"id":"umdat-ahkam:87","bookId":"umdat-ahkam","type":"section","seq":87,"chapter":"كتاب الصلاة","title":"59- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((شهد عندي رجال مرضيون - وأرضاهم عندي عمر - أن النبي - صلى الله عليه وسلم - نهى عن الصلاة بعد الصبح حتى تطلع الشمس , وبعد العصر حتى تغرب)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:88","bookId":"umdat-ahkam","type":"section","seq":88,"chapter":"كتاب الصلاة","title":"60- عن أبي سعيد الخدري - رضي الله عنه - عن رسول الله - صلى الله عليه وسلم - أنه قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - عن رسول الله - صلى الله عليه وسلم - أنه قال: ((لا صلاة بعد الصبح حتى ترتفع الشمس , ولا صلاة بعد العصر حتى تغيب الشمس)) .\nوفي الباب عن علي بن أبي طالب، وعبد الله بن مسعود، وعبد الله بن عمر بن الخطاب، وعبد الله بن عمرو بن العاص، وأبي هريرة، وسمرة بن جندب، وسلمة بن الأكوع، وزيد بن ثابت ومعاذ بن جبل، ومعاذ بن عفراء، وكعب بن مرة، وأبي أمامة الباهلي، وعمرو بن عبسة السلمي، وعائشة رضي الله عنهم، والصنابحي، ولم يسمع من النبي - صلى الله عليه وسلم -.","bab":"باب المواقيت"},{"id":"umdat-ahkam:89","bookId":"umdat-ahkam","type":"section","seq":89,"chapter":"كتاب الصلاة","title":"61- عن جابر بن عبد الله رضي الله عنهما","page":"ج1 ص58","text":"عن جابر بن عبد الله رضي الله عنهما ((أن عمر بن الخطاب رضي الله عنه جاء يوم الخندق بعد ما غربت الشمس فجعل يسب كفار قريش , وقال: يا رسول الله , ما كدت أصلي العصر حتى كادت الشمس تغرب. فقال النبي - صلى الله عليه وسلم -: والله ما صليتها. قال: فقمنا إلى بطحان , فتوضأ للصلاة , وتوضأنا لها , فصلى العصر بعد ما غربت الشمس. ثم صلى بعدها المغرب)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:90","bookId":"umdat-ahkam","type":"section","seq":90,"chapter":"كتاب الصلاة","title":"ص: 59","page":"ج1 ص58","text":"بطحان: اسم مكان بالمدينة.","bab":"باب المواقيت"},{"id":"umdat-ahkam:91","bookId":"umdat-ahkam","type":"section","seq":91,"chapter":"كتاب الصلاة","title":"62- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص59","text":"عن عبد الله بن عمر رضي الله عنهما: أن رسول الله - صلى الله عليه وسلم - قال: ((صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة)) .\nالفذ: المنفرد.","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:92","bookId":"umdat-ahkam","type":"section","seq":92,"chapter":"كتاب الصلاة","title":"63- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((صلاة الرجل في جماعة تضعف على صلاته في بيته وفي سوقه خمسا وعشرين ضعفا , وذلك: أنه إذا توضأ , فأحسن الوضوء. ثم خرج إلى المسجد لا يخرجه إلا الصلاة لم يخط خطوة إلا رفعت له بها درجة , وحط عنه خطيئة. فإذا صلى لم تزل الملائكة تصلي عليه , ما دام في مصلاه: اللهم صل عليه , اللهم اغفر له , اللهم ارحمه , ولا يزال في صلاة ما انتظر الصلاة)) .","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:93","bookId":"umdat-ahkam","type":"section","seq":93,"chapter":"كتاب الصلاة","title":"64- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((أثقل الصلاة على المنافقين: صلاة العشاء , وصلاة الفجر. ولو يعلمون ما فيها لأتوهما ولو حبوا. ولقد هممت أن آمر بالصلاة فتقام , ثم آمر رجلا فيصلي بالناس , ثم أنطلق معي برجال معهم حزم من حطب إلى قوم لا يشهدون الصلاة , فأحرق عليهم بيوتهم بالنار)) .\nحبوا: الحبو: الزحف على اليدين والركبتين.","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:94","bookId":"umdat-ahkam","type":"section","seq":94,"chapter":"كتاب الصلاة","title":"65- عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال: ((إذا استأذنت أحدكم امرأته إلى المسجد فلا يمنعها. قال: فقال بلال بن عبد الله: والله لنمنعهن. قال: فأقبل عليه عبد الله , فسبه","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:95","bookId":"umdat-ahkam","type":"section","seq":95,"chapter":"كتاب الصلاة","title":"ص: 61","page":"ص0","text":"سبا سيئا , ما سمعته سبه مثله قط , وقال: أخبرك عن رسول الله - صلى الله عليه وسلم - وتقول: والله لنمنعهن؟)) وفي لفظ ((لا تمنعوا إماء الله مساجد الله)) .","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:96","bookId":"umdat-ahkam","type":"section","seq":96,"chapter":"كتاب الصلاة","title":"63- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((صليت مع رسول الله - صلى الله عليه وسلم - ركعتين قبل الظهر , وركعتين بعدها , وركعتين بعد الجمعة , وركعتين بعد المغرب , وركعتين بعد العشاء)) .\nوفي لفظ: ((فأما المغرب والعشاء والجمعة: ففي بيته)) .","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:97","bookId":"umdat-ahkam","type":"section","seq":97,"chapter":"كتاب الصلاة","title":"ص: 62","page":"ص0","text":"وفي لفظ: أن ابن عمر قال: حدثتني حفصة: أن النبي - صلى الله عليه وسلم -: ((كان يصلي سجدتين خفيفتين بعدما يطلع الفجر. وكانت ساعة لا أدخل على النبي - صلى الله عليه وسلم - فيها)) .","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:98","bookId":"umdat-ahkam","type":"section","seq":98,"chapter":"كتاب الصلاة","title":"67- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((لم يكن النبي - صلى الله عليه وسلم - على شيء من النوافل تعاهدا منه على ركعتي الفجر)) .\nوفي لفظ لمسلم: ((ركعتا الفجر خير من الدنيا وما فيها)) .","bab":"باب فضل الجماعة ووجوبها"},{"id":"umdat-ahkam:99","bookId":"umdat-ahkam","type":"section","seq":99,"chapter":"كتاب الصلاة","title":"68- عن أنس بن مالك رضي الله عنه قال","page":"ج1 ص62","text":"عن أنس بن مالك رضي الله عنه قال: ((أمر بلال أن يشفع الأذان , ويوتر الإقامة)) .","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:100","bookId":"umdat-ahkam","type":"section","seq":100,"chapter":"كتاب الصلاة","title":"ص: 63","page":"ج1 ص62","text":"الأذان لغة: الإعلام.\nالأذان شرعا: الإعلام بدخول وقت الصلاة بألفاظ مخصوصة.\nيشفع الأذان: يأتي بألفاظه شفعا.\nيوتر الإقامة: يأتي بألفاظها وترا.","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:101","bookId":"umdat-ahkam","type":"section","seq":101,"chapter":"كتاب الصلاة","title":"69- عن أبي جحيفة وهب بن عبد الله السوائي قال","page":"ص0","text":"عن أبي جحيفة وهب بن عبد الله السوائي قال: ((أتيت النبي - صلى الله عليه وسلم - وهو في قبة له حمراء من أدم - قال: فخرج بلال بوضوء , فمن ناضح ونائل , قال: فخرج النبي - صلى الله عليه وسلم - عليه حلة حمراء , كأني أنظر إلى بياض ساقيه , قال: فتوضأ وأذن بلال , قال: فجعلت أتتبع فاه ههنا وههنا , يقول يمينا وشمالا: حي على الصلاة ; حي على الفلاح ثم ركزت له عنزة , فتقدم وصلى الظهر ركعتين , ثم نزل يصلي ركعتين حتى رجع إلى المدينة)) .\nقبة: خيمة.\nناضح: النضح: الرش، والمراد هنا الأخذ من الماء الذي توضأ به النبي - صلى الله عليه وسلم - للتبرك.\nنائل: النائل: الآخذ ممن أخذ من وضوء النبي - صلى الله عليه وسلم -.\nعنزة: عصا صغيرة في آخرها حربة.","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:102","bookId":"umdat-ahkam","type":"section","seq":102,"chapter":"كتاب الصلاة","title":"70- عن عبد الله بن عمر رضي الله عنهما عن رسول الله - صلى الله عليه وسلم","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما عن رسول الله - صلى الله عليه وسلم","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:103","bookId":"umdat-ahkam","type":"section","seq":103,"chapter":"كتاب الصلاة","title":"ص: 64","page":"ص0","text":"أنه قال: ((إن بلالا يؤذن بليل , فكلوا واشربوا حتى تسمعوا أذان ابن أم مكتوم)) .","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:104","bookId":"umdat-ahkam","type":"section","seq":104,"chapter":"كتاب الصلاة","title":"71- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إذا سمعتم المؤذن فقولوا مثل ما يقول))","bab":"باب الأذان والإقامة"},{"id":"umdat-ahkam:105","bookId":"umdat-ahkam","type":"section","seq":105,"chapter":"كتاب الصلاة","title":"72- عن ابن عمر رضي الله عنهما","page":"ج1 ص65","text":"عن ابن عمر رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - كان يسبح على ظهر راحلته , حيث كان وجهه , يومئ برأسه , وكان ابن عمر يفعله)) .\nوفي رواية: ((كان يوتر على بعيره)) .\nولمسلم: ((غير أنه لا يصلي عليها المكتوبة)) .\nوللبخاري: ((إلا الفرائض)) .\nيسبح: يصلي.\nيومىء برأسه: يشير برأسه.","bab":"باب استقبال القبلة"},{"id":"umdat-ahkam:106","bookId":"umdat-ahkam","type":"section","seq":106,"chapter":"كتاب الصلاة","title":"73- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((بينما الناس بقباء في صلاة الصبح إذ جاءهم آت , فقال: إن النبي - صلى الله عليه وسلم - قد أنزل عليه الليلة قرآن , وقد أمر أن يستقبل القبلة , فاستقبلوها. وكانت وجوههم إلى الشام , فاستداروا إلى الكعبة)) .","bab":"باب استقبال القبلة"},{"id":"umdat-ahkam:107","bookId":"umdat-ahkam","type":"section","seq":107,"chapter":"كتاب الصلاة","title":"ص: 66","page":"ص0","text":"قباء: مسجد بالمدينة قريب من المسجد النبوي.","bab":"باب استقبال القبلة"},{"id":"umdat-ahkam:108","bookId":"umdat-ahkam","type":"section","seq":108,"chapter":"كتاب الصلاة","title":"74- عن أنس بن سيرين قال","page":"ص0","text":"عن أنس بن سيرين قال: ((استقبلنا أنسا حين قدم من الشام , فلقيناه بعين التمر , فرأيته يصلي على حمار , ووجهه من ذا الجانب - يعني عن يسار القبلة - فقلت: رأيتك تصلي لغير القبلة؟ فقال: لولا أني رأيت رسول الله - صلى الله عليه وسلم - يفعله ما فعلته)) .","bab":"باب استقبال القبلة"},{"id":"umdat-ahkam:109","bookId":"umdat-ahkam","type":"section","seq":109,"chapter":"كتاب الصلاة","title":"75- عن أنس بن مالك - رضي الله عنه - قال","page":"ج1 ص66","text":"عن أنس بن مالك - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((سووا صفوفكم , فإن تسوية الصفوف من تمام الصلاة)) .","bab":"باب الصفوف"},{"id":"umdat-ahkam:110","bookId":"umdat-ahkam","type":"section","seq":110,"chapter":"كتاب الصلاة","title":"76- عن النعمان بن بشير رضي الله عنهما","page":"ص0","text":"عن النعمان بن بشير رضي الله عنهما , قال: سمعت","bab":"باب الصفوف"},{"id":"umdat-ahkam:111","bookId":"umdat-ahkam","type":"section","seq":111,"chapter":"كتاب الصلاة","title":"ص: 67","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - يقول: ((لتسون صفوفكم أو ليخالفن الله بين وجوهكم)) .\nولمسلم: ((كان رسول الله - صلى الله عليه وسلم - يسوي صفوفنا , حتى كأنما يسوي بها القداح , حتى إذا رأى أن قد عقلنا عنه , ثم خرج يوما فقام , حتى إذا كاد أن يكبر , فرأى رجلا باديا صدره , فقال: عباد الله , لتسون صفوفكم أو ليخالفن الله بين وجوهكم)) .\nالقداح: خشب السهام حين تنحت وتبرى.\nعقلنا عنه: فهمنا ماأمرنا به من التسوية.\nباديا صدره: ظاهرا صدره من الصف.","bab":"باب الصفوف"},{"id":"umdat-ahkam:112","bookId":"umdat-ahkam","type":"section","seq":112,"chapter":"كتاب الصلاة","title":"77- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه -: ((أن جدته مليكة دعت رسول الله - صلى الله عليه وسلم - لطعام صنعته , فأكل منه , ثم قال: قوموا فلأصلي لكم؟ قال أنس: فقمت إلى حصير لنا قد اسود من طول ما لبس , فنضحته بماء , فقام عليه رسول الله - صلى الله عليه وسلم - وصففت أنا واليتيم وراءه , والعجوز من ورائنا. فصلى لنا ركعتين , ثم انصرف)) .","bab":"باب الصفوف"},{"id":"umdat-ahkam:113","bookId":"umdat-ahkam","type":"section","seq":113,"chapter":"كتاب الصلاة","title":"ص: 68","page":"ص0","text":"ولمسلم ((أن رسول الله - صلى الله عليه وسلم - صلى به وبأمه فأقامني عن يمينه , وأقام المرأة خلفنا)) .\nاليتيم: ضميرة جد حسين بن عبد الله بن ضميرة.\nفنضحته بماء: النضح هو الرش، وقد يراد به الغسل.","bab":"باب الصفوف"},{"id":"umdat-ahkam:114","bookId":"umdat-ahkam","type":"section","seq":114,"chapter":"كتاب الصلاة","title":"78- عن عبد الله بن عباس رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما: قال: ((بت عند خالتي ميمونة. فقام النبي - صلى الله عليه وسلم - يصلي من الليل. فقمت عن يساره. فأخذ برأسي فأقامني عن يمينه)) .","bab":"باب الصفوف"},{"id":"umdat-ahkam:115","bookId":"umdat-ahkam","type":"section","seq":115,"chapter":"كتاب الصلاة","title":"79- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ج1 ص68","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((أما يخشى الذي يرفع رأسه قبل الإمام أن يحول الله رأسه رأس حمار , أو يجعل صورته صورة حمار؟)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:116","bookId":"umdat-ahkam","type":"section","seq":116,"chapter":"كتاب الصلاة","title":"80- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ج1 ص68","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((إنما جعل الإمام ليؤتم به. فلا تختلفوا عليه. فإذا كبر فكبروا , وإذا ركع فاركعوا. وإذا قال: سمع الله لمن حمده , فقولوا: ربنا ولك الحمد. وإذا سجد فاسجدوا. وإذا صلى جالسا فصلوا جلوسا أجمعون)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:117","bookId":"umdat-ahkam","type":"section","seq":117,"chapter":"كتاب الصلاة","title":"81- وما في معناه من حديث عائشة رضي الله عنها قالت","page":"ص0","text":"وما في معناه من حديث عائشة رضي الله عنها قالت: ((صلى رسول الله - صلى الله عليه وسلم - في بيته وهو شاك , صلى جالسا , وصلى وراءه قوم قياما , فأشار إليهم: أن اجلسوا لما انصرف قال إنما جعل الإمام ليؤتم به , فإذا ركع فاركعوا , وإذا رفع فارفعوا , وإذا قال: سمع الله لمن حمده فقولوا:","bab":"باب الإمامة"},{"id":"umdat-ahkam:118","bookId":"umdat-ahkam","type":"section","seq":118,"chapter":"كتاب الصلاة","title":"ص: 70","page":"ص0","text":"ربنا لك الحمد , وإذا صلى جالسا فصلوا جلوسا أجمعون)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:119","bookId":"umdat-ahkam","type":"section","seq":119,"chapter":"كتاب الصلاة","title":"82- عن عبد الله بن يزيد الخطمي الأنصاري - رضي الله عنه - قال","page":"ص0","text":"عن عبد الله بن يزيد الخطمي الأنصاري - رضي الله عنه - قال: حدثني البراء - وهو غير كذوب - قال:\n((كان رسول الله - صلى الله عليه وسلم - إذا قال: سمع الله لمن حمده: لم يحن أحد منا ظهره حتى يقع رسول الله - صلى الله عليه وسلم - ساجدا , ثم نقع سجودا بعده)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:120","bookId":"umdat-ahkam","type":"section","seq":120,"chapter":"كتاب الصلاة","title":"83- عن أبي هريرة - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((إذا أمن الإمام فأمنوا , فإنه من وافق تأمينه تأمين الملائكة: غفر له ما تقدم من ذنبه)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:121","bookId":"umdat-ahkam","type":"section","seq":121,"chapter":"كتاب الصلاة","title":"84- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((إذا صلى أحدكم للناس فليخفف فإن فيهم الضعيف والسقيم وذا","bab":"باب الإمامة"},{"id":"umdat-ahkam:122","bookId":"umdat-ahkam","type":"section","seq":122,"chapter":"كتاب الصلاة","title":"ص: 71","page":"ص0","text":"الحاجة , وإذا صلى أحدكم لنفسه فليطول ما شاء)) .\nالسقيم: المريض.","bab":"باب الإمامة"},{"id":"umdat-ahkam:123","bookId":"umdat-ahkam","type":"section","seq":123,"chapter":"كتاب الصلاة","title":"85- وما في معناه من حديث أبي مسعود الأنصاري - رضي الله عنه - قال","page":"ص0","text":"وما في معناه من حديث أبي مسعود الأنصاري - رضي الله عنه - قال: ((جاء رجل إلى رسول الله - صلى الله عليه وسلم - فقال: إني لأتأخر عن صلاة الصبح من أجل فلان , مما يطيل بنا , قال: فما رأيت النبي - صلى الله عليه وسلم - غضب في موعظة قط أشد مما غضب يومئذ , فقال: يا أيها الناس , إن منكم منفرين , فأيكم أم الناس فليوجز , فإن من ورائه الكبير والضعيف وذا الحاجة)) .","bab":"باب الإمامة"},{"id":"umdat-ahkam:124","bookId":"umdat-ahkam","type":"section","seq":124,"chapter":"كتاب الصلاة","title":"86- عن أبي هريرة - رضي الله عنه - قال","page":"ج1 ص72","text":"عن أبي هريرة - رضي الله عنه - قال: ((كان رسول الله - صلى الله عليه وسلم - إذا كبر في الصلاة سكت هنيهة قبل أن يقرأ , فقلت: يا رسول الله , بأبي أنت وأمي , أرأيت سكوتك بين التكبير والقراءة: ما تقول؟ قال: أقول: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب. اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس. اللهم اغسلني من خطاياي بالماء والثلج والبرد)) .\nهنيهة: زمنا يسيرا.\nأرأيت: أخبرني.\nالدنس: الوسخ.","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:125","bookId":"umdat-ahkam","type":"section","seq":125,"chapter":"كتاب الصلاة","title":"87- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان رسول الله - صلى الله عليه وسلم - يستفتح الصلاة بالتكبير , والقراءة ب «الحمد لله رب العالمين» وكان إذا ركع لم يشخص رأسه ولم يصوبه ولكن بين ذلك , وكان إذا رفع رأسه من الركوع لم يسجد حتى يستوي قائما , وكان إذا رفع رأسه من السجدة لم يسجد , حتى يستوي قاعدا , وكان يقول في كل ركعتين التحية , وكان يفرش رجله اليسرى وينصب رجله اليمنى , وكان ينهى عن عقبة الشيطان، وينهى أن يفترش الرجل ذراعيه افتراش السبع , وكان يختم الصلاة بالتسليم)) .\nيشخص بصره: لم يرفعه.\nلم يصوبه: لم يخفضه خفضا بليغا.\nعقبة الشيطان: هو الإقعاء في الجلوس، وصفته أن يلصق الرجل إليته بالأرض، وينصب ساقيه ويضع يديه على الأرض.","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:126","bookId":"umdat-ahkam","type":"section","seq":126,"chapter":"كتاب الصلاة","title":"88- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن النبي - صلى الله عليه وسلم - كان","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:127","bookId":"umdat-ahkam","type":"section","seq":127,"chapter":"كتاب الصلاة","title":"ص: 73","page":"ص0","text":"يرفع يديه حذو منكبيه إذا افتتح الصلاة , وإذا كبر للركوع , وإذا رفع رأسه من الركوع رفعهما كذلك , وقال: سمع الله لمن حمده , ربنا ولك الحمد. وكان لا يفعل ذلك في السجود)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:128","bookId":"umdat-ahkam","type":"section","seq":128,"chapter":"كتاب الصلاة","title":"89- عن ابن عباس رضي الله عنهما قال","page":"ص0","text":"عن ابن عباس رضي الله عنهما قال: قال رسول الله - صلى الله عليه وسلم -: ((أمرت أن أسجد على سبعة أعظم: على الجبهة - وأشار بيده إلى أنفه - واليدين , والركبتين , وأطراف القدمين)) .\nأطراف القدمين: أصابع القدمين.","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:129","bookId":"umdat-ahkam","type":"section","seq":129,"chapter":"كتاب الصلاة","title":"90- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((كان رسول الله - صلى الله عليه وسلم - إذا قام إلى الصلاة يكبر حين يقوم , ثم يكبر حين يركع , ثم يقول: سمع الله لمن حمده , حين يرفع صلبه من الركعة , ثم يقول وهو","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:130","bookId":"umdat-ahkam","type":"section","seq":130,"chapter":"كتاب الصلاة","title":"ص: 74","page":"ص0","text":"قائم: ربنا ولك الحمد , ثم يكبر حين يهوي , ثم يكبر حين يرفع رأسه , ثم يكبر حين يسجد , ثم يكبر حين يرفع رأسه , ثم يفعل ذلك في صلاته كلها , حتى يقضيها , ويكبر حين يقوم من الثنتين بعد الجلوس)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:131","bookId":"umdat-ahkam","type":"section","seq":131,"chapter":"كتاب الصلاة","title":"91- عن مطرف بن عبد الله قال","page":"ص0","text":"عن مطرف بن عبد الله قال: ((صليت أنا وعمران بن حصين خلف علي بن أبي طالب. فكان إذا سجد كبر , وإذا رفع رأسه كبر , وإذا نهض من الركعتين كبر , فلما قضى الصلاة أخذ بيدي عمران بن حصين , وقال: قد ذكرني هذا صلاة محمد - صلى الله عليه وسلم - أو قال: صلى بنا صلاة محمد - صلى الله عليه وسلم -)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:132","bookId":"umdat-ahkam","type":"section","seq":132,"chapter":"كتاب الصلاة","title":"92- عن البراء بن عازب رضي الله عنهما قال","page":"ص0","text":"عن البراء بن عازب رضي الله عنهما قال: ((رمقت الصلاة مع محمد - صلى الله عليه وسلم - فوجدت قيامه , فركعته فاعتداله بعد ركوعه , فسجدته , فجلسته بين السجدتين , فسجدته فجلسته ما بين التسليم والانصراف: قريبا من السواء)) . وفي رواية البخاري ((ما خلا القيام والقعود قريبا من السواء)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:133","bookId":"umdat-ahkam","type":"section","seq":133,"chapter":"كتاب الصلاة","title":"93- عن ثابت البناني عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن ثابت البناني عن أنس بن مالك - رضي الله عنه - قال: ((إني لا آلو أن أصلي بكم كما كان رسول الله - صلى الله عليه وسلم - يصلي بنا قال ثابت فكان أنس يصنع شيئا لا أراكم تصنعونه. كان إذا رفع رأسه من الركوع: انتصب قائما , حتى يقول القائل: قد نسي , وإذا رفع رأسه من السجدة: مكث , حتى يقول القائل: قد نسي)) .\nلاآلو: لاأقصر.","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:134","bookId":"umdat-ahkam","type":"section","seq":134,"chapter":"كتاب الصلاة","title":"94- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: ((ما صليت خلف إمام","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:135","bookId":"umdat-ahkam","type":"section","seq":135,"chapter":"كتاب الصلاة","title":"ص: 76","page":"ص0","text":"قط أخف صلاة. ولا أتم صلاة من النبي - صلى الله عليه وسلم -)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:136","bookId":"umdat-ahkam","type":"section","seq":136,"chapter":"كتاب الصلاة","title":"95- عن أبي قلابة عبد الله بن زيد الجرمي البصري - قال","page":"ص0","text":"عن أبي قلابة عبد الله بن زيد الجرمي البصري - قال: ((جاءنا مالك بن الحويرث في مسجدنا هذا , فقال: إني لأصلي بكم , وما أريد الصلاة , أصلي كيف رأيت رسول الله - صلى الله عليه وسلم - يصلي , فقلت لأبي قلابة: كيف كان يصلي؟ فقال: مثل صلاة شيخنا هذا , وكان يجلس إذا رفع رأسه من السجود قبل أن ينهض)) . أراد بشيخهم، أبا يزيد، عمرو بن سلمة الجرمي.","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:137","bookId":"umdat-ahkam","type":"section","seq":137,"chapter":"كتاب الصلاة","title":"96- عن عبد الله بن مالك بن بحينة - رضي الله عنه -","page":"ص0","text":"عن عبد الله بن مالك بن بحينة - رضي الله عنه -: ((أن النبي - صلى الله عليه وسلم - كان إذا صلى فرج بين يديه , حتى يبدو بياض إبطيه)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:138","bookId":"umdat-ahkam","type":"section","seq":138,"chapter":"كتاب الصلاة","title":"97- عن أبي مسلمة سعيد بن يزيد قال","page":"ص0","text":"عن أبي مسلمة سعيد بن يزيد قال: ((سألت أنس بن مالك: أكان النبي - صلى الله عليه وسلم - يصلي في نعليه؟ قال: نعم)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:139","bookId":"umdat-ahkam","type":"section","seq":139,"chapter":"كتاب الصلاة","title":"98- عن أبي قتادة الأنصاري - رضي الله عنه -","page":"ص0","text":"عن أبي قتادة الأنصاري - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - كان يصلي وهو حامل أمامة بنت زينب بنت رسول الله - صلى الله عليه وسلم -","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:140","bookId":"umdat-ahkam","type":"section","seq":140,"chapter":"كتاب الصلاة","title":"99- ولأبي العاص بن الربيع بن عبد شمس","page":"ص0","text":"ولأبي العاص بن الربيع بن عبد شمس , فإذا سجد","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:141","bookId":"umdat-ahkam","type":"section","seq":141,"chapter":"كتاب الصلاة","title":"ص: 78","page":"ص0","text":"وضعها , وإذا قام حملها))","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:142","bookId":"umdat-ahkam","type":"section","seq":142,"chapter":"كتاب الصلاة","title":"100- عن أنس بن مالك - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((اعتدلوا في السجود ولا يبسط أحدكم ذراعيه انبساط الكلب)) .","bab":"باب صفة صلاة النبي - صلى الله عليه وسلم -"},{"id":"umdat-ahkam:143","bookId":"umdat-ahkam","type":"section","seq":143,"chapter":"كتاب الصلاة","title":"101- عن أبي هريرة - رضي الله عنه -","page":"ج1 ص78","text":"عن أبي هريرة - رضي الله عنه -: ((أن النبي - صلى الله عليه وسلم - دخل المسجد , فدخل رجل فصلى , ثم جاء فسلم على النبي - صلى الله عليه وسلم - فقال: ارجع فصل , فإنك لم تصل. فرجع فصلى كما صلى , ثم جاء فسلم على النبي - صلى الله عليه وسلم - فقال: ارجع فصل , فإنك","bab":"باب وجوب الطمأنينة في الركوع والسجود"},{"id":"umdat-ahkam:144","bookId":"umdat-ahkam","type":"section","seq":144,"chapter":"كتاب الصلاة","title":"ص: 79","page":"ج1 ص78","text":"لم تصل - ثلاثا - فقال: والذي بعثك بالحق لا أحسن غيره , فعلمني , فقال: إذا قمت إلى الصلاة فكبر , ثم اقرأ ما تيسر من القرآن , ثم اركع حتى تطمئن راكعا , ثم ارفع حتى تعتدل قائما , ثم اسجد حتى تطمئن ساجدا, ثم ارفع حتى تطمئن جالسا. وافعل ذلك في صلاتك كلها))","bab":"باب وجوب الطمأنينة في الركوع والسجود"},{"id":"umdat-ahkam:145","bookId":"umdat-ahkam","type":"section","seq":145,"chapter":"كتاب الصلاة","title":"102- عن عبادة بن الصامت - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ج1 ص79","text":"عن عبادة بن الصامت - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((لا صلاة لمن لم يقرأ بفاتحة الكتاب)) .","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:146","bookId":"umdat-ahkam","type":"section","seq":146,"chapter":"كتاب الصلاة","title":"103- عن أبي قتادة الأنصاري - رضي الله عنه - قال","page":"ص0","text":"عن أبي قتادة الأنصاري - رضي الله عنه - قال: ((كان رسول الله - صلى الله عليه وسلم - يقرأ في الركعتين الأوليين من صلاة الظهر بفاتحة الكتاب وسورتين , يطول في الأولى , ويقصر في الثانية , ويسمع الآية أحيانا، وكان يقرأ في العصر بفاتحة الكتاب وسورتين يطول في الأولى , ويقصر في الثانية وفي الركعتين","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:147","bookId":"umdat-ahkam","type":"section","seq":147,"chapter":"كتاب الصلاة","title":"ص: 80","page":"ص0","text":"الأخريين بأم الكتاب. وكان يطول في الركعة الأولى من صلاة الصبح , ويقصر في الثانية)) .","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:148","bookId":"umdat-ahkam","type":"section","seq":148,"chapter":"كتاب الصلاة","title":"104- عن جبير بن مطعم - رضي الله عنه - قال","page":"ص0","text":"عن جبير بن مطعم - رضي الله عنه - قال: ((سمعت النبي - صلى الله عليه وسلم - يقرأ في المغرب بالطور)) .","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:149","bookId":"umdat-ahkam","type":"section","seq":149,"chapter":"كتاب الصلاة","title":"105- عن البراء بن عازب رضي الله عنهما","page":"ص0","text":"عن البراء بن عازب رضي الله عنهما: ((أن النبي - صلى الله عليه وسلم - كان","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:150","bookId":"umdat-ahkam","type":"section","seq":150,"chapter":"كتاب الصلاة","title":"ص: 81","page":"ص0","text":"في سفر , فصلى العشاء الآخرة , فقرأ في إحدى الركعتين بالتين والزيتون فما سمعت أحدا أحسن صوتا أو قراءة منه)) .","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:151","bookId":"umdat-ahkam","type":"section","seq":151,"chapter":"كتاب الصلاة","title":"106- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: ((أن رسول الله - صلى الله عليه وسلم - بعث رجلا على سرية فكان يقرأ لأصحابه في صلاتهم , فيختم ب «قل هو الله أحد» فلما رجعوا ذكروا ذلك لرسول الله - صلى الله عليه وسلم - فقال: سلوه لأي شيء صنع ذلك؟ فسألوه. فقال: لأنها صفة الرحمن عز وجل , فأنا أحب أن أقرأ بها. فقال رسول الله - صلى الله عليه وسلم -: أخبروه: أن الله تعالى يحبه)) .","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:152","bookId":"umdat-ahkam","type":"section","seq":152,"chapter":"كتاب الصلاة","title":"107- عن جابر بن عبد الله رضي الله عنهما","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما: أن النبي - صلى الله عليه وسلم - قال لمعاذ: ((فلولا","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:153","bookId":"umdat-ahkam","type":"section","seq":153,"chapter":"كتاب الصلاة","title":"ص: 82","page":"ص0","text":"صليت بسبح اسم ربك الأعلى , والشمس وضحاها , والليل إذا يغشى؟ فإنه يصلي وراءك الكبير والضعيف وذو الحاجة))","bab":"باب القراءة في الصلاة"},{"id":"umdat-ahkam:154","bookId":"umdat-ahkam","type":"section","seq":154,"chapter":"كتاب الصلاة","title":"108- عن أنس بن مالك - رضي الله عنه -","page":"ج1 ص82","text":"عن أنس بن مالك - رضي الله عنه -: ((أن النبي - صلى الله عليه وسلم - وأبا بكر وعمر رضي الله عنهما: كانوا يستفتحون الصلاة ب «الحمد لله رب العالمين» )) .\nوفي رواية: ((صليت مع أبي بكر وعمر وعثمان , فلم أسمع أحدا منهم يقرأ بسم الله الرحمن الرحيم))","bab":"باب ترك الجهر ببسم الله الرحمن الرحيم"},{"id":"umdat-ahkam:155","bookId":"umdat-ahkam","type":"section","seq":155,"chapter":"كتاب الصلاة","title":"109- ولمسلم","page":"ج1 ص82","text":"ولمسلم: ((صليت خلف النبي - صلى الله عليه وسلم - وأبي بكر وعمر وعثمان فكانوا يستفتحون ب «الحمد لله رب العالمين» , لا يذكرون بسم الله الرحمن الرحيم في أول قراءة ولا في آخرها)) .","bab":"باب ترك الجهر ببسم الله الرحمن الرحيم"},{"id":"umdat-ahkam:156","bookId":"umdat-ahkam","type":"section","seq":156,"chapter":"كتاب الصلاة","title":"110- عن محمد بن سيرين","page":"ج1 ص83","text":"عن محمد بن سيرين، عن أبي هريرة - رضي الله عنه - قال: ((صلى بنا رسول الله- صلى الله عليه وسلم - إحدى صلاتي العشي - قال ابن سيرين: وسماها أبو هريرة. ولكن نسيت أنا - قال: فصلى بنا ركعتين , ثم سلم. فقام إلى خشبة معروضة في المسجد , فاتكأ عليها كأنه غضبان ووضع يده اليمنى على اليسرى , وشبك بين أصابعه. وخرجت السرعان من أبواب المسجد فقالوا: قصرت الصلاة - وفي القوم أبو بكر وعمر - فهابا","bab":"باب سجود السهو"},{"id":"umdat-ahkam:157","bookId":"umdat-ahkam","type":"section","seq":157,"chapter":"كتاب الصلاة","title":"ص: 84","page":"ج1 ص83","text":"أن يكلماه. وفي القوم رجل في يديه طول , يقال له: ذو اليدين فقال: يا رسول الله , أنسيت , أم قصرت الصلاة؟ قال: لم أنس ولم تقصر. فقال: أكما يقول ذو اليدين؟ فقالوا: نعم. فتقدم فصلى ما ترك. ثم سلم , ثم كبر وسجد مثل سجوده أو أطول. ثم رفع رأسه فكبر , ثم كبر وسجد مثل سجوده أو أطول. ثم رفع رأسه وكبر. فربما سألوه: ثم سلم؟ قال: فنبئت أن عمران بن حصين قال: ثم سلم)) .","bab":"باب سجود السهو"},{"id":"umdat-ahkam:158","bookId":"umdat-ahkam","type":"section","seq":158,"chapter":"كتاب الصلاة","title":"ص: 85","page":"ج1 ص83","text":"العشي: الوقت مابين زوال الشمس وغروبها.\nالسرعان: المسرعون إلى الخروج.","bab":"باب سجود السهو"},{"id":"umdat-ahkam:159","bookId":"umdat-ahkam","type":"section","seq":159,"chapter":"كتاب الصلاة","title":"111- عن عبد الله بن بحينة - وكان من أصحاب النبي - صلى الله عليه وسلم -","page":"ج1 ص83","text":"عن عبد الله بن بحينة - وكان من أصحاب النبي - صلى الله عليه وسلم - ((أن النبي - صلى الله عليه وسلم - صلى بهم الظهر فقام في الركعتين الأوليين , ولم يجلس. فقام الناس معه , حتى إذا قضى الصلاة , وانتظر الناس تسليمه: كبر وهو جالس. فسجد سجدتين قبل أن يسلم ثم سلم)) .","bab":"باب سجود السهو"},{"id":"umdat-ahkam:160","bookId":"umdat-ahkam","type":"section","seq":160,"chapter":"كتاب الصلاة","title":"112- عن أبي جهيم بن الحارث بن الصمة الأنصاري - رضي الله عنه - قال","page":"ج1 ص85","text":"عن أبي جهيم بن الحارث بن الصمة الأنصاري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لو يعلم المار بين","bab":"باب المرور بين يدي المصلي"},{"id":"umdat-ahkam:161","bookId":"umdat-ahkam","type":"section","seq":161,"chapter":"كتاب الصلاة","title":"ص: 86","page":"ج1 ص85","text":"يدي المصلي ماذا عليه من الإثم؟ لكان أن يقف أربعين خيرا له من أن يمر بين يديه)) . قال أبو النضر: لا أدري: قال أربعين يوما أو شهرا أو سنة.","bab":"باب المرور بين يدي المصلي"},{"id":"umdat-ahkam:162","bookId":"umdat-ahkam","type":"section","seq":162,"chapter":"كتاب الصلاة","title":"113- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ج1 ص85","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((إذا صلى أحدكم إلى شيء يستره من الناس , فأراد أحد أن يجتاز بين يديه فليدفعه. فإن أبى فليقاتله. فإنما هو شيطان)) .","bab":"باب المرور بين يدي المصلي"},{"id":"umdat-ahkam:163","bookId":"umdat-ahkam","type":"section","seq":163,"chapter":"كتاب الصلاة","title":"114- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((أقبلت راكبا على حمار أتان , وأنا يومئذ قد ناهزت الاحتلام , ورسول الله - صلى الله عليه وسلم - يصلي بالناس بمنى إلى غير جدار. مررت بين يدي بعض الصف فنزلت , فأرسلت الأتان ترتع. ودخلت في الصف , فلم ينكر ذلك علي أحد)) .\nالأتان: أنثى الحمار.\nناهزت الاحتلام: قاربت البلوغ.\nترتع: ترعى.","bab":"باب المرور بين يدي المصلي"},{"id":"umdat-ahkam:164","bookId":"umdat-ahkam","type":"section","seq":164,"chapter":"كتاب الصلاة","title":"115- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كنت أنام بين يدي رسول الله - صلى الله عليه وسلم - ورجلاي في قبلته - فإذا سجد غمزني , فقبضت رجلي. فإذا قام بسطتهما. والبيوت يومئذ ليس فيها مصابيح)) .","bab":"باب المرور بين يدي المصلي"},{"id":"umdat-ahkam:165","bookId":"umdat-ahkam","type":"section","seq":165,"chapter":"كتاب الصلاة","title":"116- عن أبي قتادة بن ربعي الأنصاري - رضي الله عنه - قال","page":"ج1 ص88","text":"عن أبي قتادة بن ربعي الأنصاري - رضي الله عنه - قال: قال رسول - صلى الله عليه وسلم -: ((إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين)) .","bab":"باب جامع"},{"id":"umdat-ahkam:166","bookId":"umdat-ahkam","type":"section","seq":166,"chapter":"كتاب الصلاة","title":"117- عن زيد بن أرقم قال","page":"ص0","text":"عن زيد بن أرقم قال: ((كنا نتكلم في الصلاة، يكلم الرجل صاحبه , وهو إلى جنبه في الصلاة , حتى نزلت «وقوموا لله قانتين» فأمرنا بالسكوت ونهينا عن الكلام)) .","bab":"باب جامع"},{"id":"umdat-ahkam:167","bookId":"umdat-ahkam","type":"section","seq":167,"chapter":"كتاب الصلاة","title":"118- عن عبد الله بن عمر وأبي هريرة رضي الله عنهم عن رسول الله - صلى الله عليه وسلم - أنه قال","page":"ص0","text":"عن عبد الله بن عمر وأبي هريرة رضي الله عنهم عن رسول الله - صلى الله عليه وسلم - أنه قال: ((إذا اشتد الحر فأبردوا بالصلاة. فإن","bab":"باب جامع"},{"id":"umdat-ahkam:168","bookId":"umdat-ahkam","type":"section","seq":168,"chapter":"كتاب الصلاة","title":"ص: 89","page":"ص0","text":"شدة الحر من فيح جهنم)) .\nأبردوا بالصلاة: أخروها إلى الوقت الذي تخف فيه شدة الحر.\nفيح جهنم: شدة حرها وغليانها.","bab":"باب جامع"},{"id":"umdat-ahkam:169","bookId":"umdat-ahkam","type":"section","seq":169,"chapter":"كتاب الصلاة","title":"119- عن أنس بن مالك قال","page":"ص0","text":"عن أنس بن مالك قال: قال رسول الله - صلى الله عليه وسلم -: ((من نسي صلاة فليصلها إذا ذكرها , ولا كفارة لها إلا ذلك \" أقم الصلاة لذكري)) .\nولمسلم ((من نسي صلاة , أو نام عنها. فكفارتها: أن يصليها إذا ذكرها)) .","bab":"باب جامع"},{"id":"umdat-ahkam:170","bookId":"umdat-ahkam","type":"section","seq":170,"chapter":"كتاب الصلاة","title":"120- عن جابر بن عبد الله","page":"ص0","text":"عن جابر بن عبد الله ((أن معاذ بن جبل: كان يصلي مع رسول الله - صلى الله عليه وسلم - عشاء الآخرة. ثم يرجع إلى قومه , فيصلي بهم تلك الصلاة)) .","bab":"باب جامع"},{"id":"umdat-ahkam:171","bookId":"umdat-ahkam","type":"section","seq":171,"chapter":"كتاب الصلاة","title":"ص: 90","page":"ص0","text":"عشاء الآخرة: صلاة العشاء.","bab":"باب جامع"},{"id":"umdat-ahkam:172","bookId":"umdat-ahkam","type":"section","seq":172,"chapter":"كتاب الصلاة","title":"121- عن أنس بن مالك قال","page":"ص0","text":"عن أنس بن مالك قال: ((كنا نصلي مع رسول الله - صلى الله عليه وسلم - في شدة الحر. فإذا لم يستطع أحدنا أن يمكن جبهته من الأرض: بسط ثوبه فسجد عليه)) .","bab":"باب جامع"},{"id":"umdat-ahkam:173","bookId":"umdat-ahkam","type":"section","seq":173,"chapter":"كتاب الصلاة","title":"122- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا يصلي أحدكم في الثوب الواحد , ليس على عاتقه منه شيء)) .","bab":"باب جامع"},{"id":"umdat-ahkam:174","bookId":"umdat-ahkam","type":"section","seq":174,"chapter":"كتاب الصلاة","title":"123- عن جابر بن عبد الله رضي الله عنهما عن النبي - صلى الله عليه وسلم - أنه قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما عن النبي - صلى الله عليه وسلم - أنه قال: ((من أكل ثوما أو بصلا. فليعتزلنا أو ليعتزل مسجدنا، وليقعد في بيته. وأتي بقدر فيه خضرات من بقول. فوجد لها ريحا , فسأل؟ فأخبر بما فيها من البقول. فقال: قربوها إلى بعض أصحابي. فلما رآه كره أكلها. قال: كل. فإني أناجي من لا تناجي)) .","bab":"باب جامع"},{"id":"umdat-ahkam:175","bookId":"umdat-ahkam","type":"section","seq":175,"chapter":"كتاب الصلاة","title":"124- عن جابر بن عبد الله رضي الله عنهما أن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما أن النبي - صلى الله عليه وسلم - قال: ((من أكل الثوم والبصل والكراث فلا يقربن مسجدنا، فإن الملائكة تتأذى مما يتأذى منه الإنسان)) . وفي رواية ((بني آدم)) .","bab":"باب جامع"},{"id":"umdat-ahkam:176","bookId":"umdat-ahkam","type":"section","seq":176,"chapter":"كتاب الصلاة","title":"125- عن عبد الله بن مسعود - رضي الله عنه - قال","page":"ج1 ص91","text":"عن عبد الله بن مسعود - رضي الله عنه - قال: ((علمني رسول الله - صلى الله عليه وسلم - التشهد - كفي بين كفيه - كما يعلمني السورة من القرآن: التحيات لله , والصلوات والطيبات , السلام عليك أيها النبي ورحمة الله وبركاته. السلام علينا وعلى عباد الله الصالحين. أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله))","bab":"باب التشهد"},{"id":"umdat-ahkam:177","bookId":"umdat-ahkam","type":"section","seq":177,"chapter":"كتاب الصلاة","title":"126- وفي لفظ","page":"ج1 ص91","text":"وفي لفظ: ((إذا قعد أحدكم في الصلاة فليقل: التحيات لله - وذكره - وفيه: فإنكم إذا فعلتم ذلك فقد سلمتم على كل عبد صالح في السماء والأرض - وفيه - فليتخير من المسألة ما شاء))","bab":"باب التشهد"},{"id":"umdat-ahkam:178","bookId":"umdat-ahkam","type":"section","seq":178,"chapter":"كتاب الصلاة","title":"ص: 92","page":"ج1 ص91","text":"التحيات: جمع تحية وتشمل كل أنواع التعظيم.\nالطيبات: الطيب من الأقوال والأعمال والأوصاف.","bab":"باب التشهد"},{"id":"umdat-ahkam:179","bookId":"umdat-ahkam","type":"section","seq":179,"chapter":"كتاب الصلاة","title":"127- عن عبد الرحمن بن أبي ليلى قال","page":"ص0","text":"عن عبد الرحمن بن أبي ليلى قال: ((لقيني كعب بن عجرة فقال ألا أهدي لك هدية؟ أن النبي صلى الله عليه وسلم خرج علينا , فقلنا: يا رسول الله , قد علمنا الله كيف نسلم عليك: فكيف نصلي عليك؟ فقال: قولوا: اللهم صل على محمد وعلى آل محمد , كما صليت على إبراهيم إنك حميد مجيد , وبارك على محمد وعلى آل محمد , كما باركت على إبراهيم إنك حميد مجيد)) .\nحميد: محمود الأفعال مستحق لجميع المحامد.\nمجيد: المتصف بالمجد، وهو كمال الشرف والكرم والصفات المحمودة.","bab":"باب التشهد"},{"id":"umdat-ahkam:180","bookId":"umdat-ahkam","type":"section","seq":180,"chapter":"كتاب الصلاة","title":"128- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((كان رسول الله - صلى الله عليه وسلم - يدعو: اللهم إني أعوذ بك من عذاب القبر , وعذاب النار , ومن فتنة المحيا والممات , ومن فتنة المسيح الدجال)) .","bab":"باب التشهد"},{"id":"umdat-ahkam:181","bookId":"umdat-ahkam","type":"section","seq":181,"chapter":"كتاب الصلاة","title":"ص: 93","page":"ص0","text":"وفي لفظ لمسلم: ((إذا تشهد أحدكم فليستعذ بالله من أربع , يقول: اللهم إني أعوذ بك من عذاب جهنم)) .\nفتنة المحيا والممات: ما يعرض للإنسان مدة حياته من الافتتان بالدنيا وعند الموت، وبعد الموت.","bab":"باب التشهد"},{"id":"umdat-ahkam:182","bookId":"umdat-ahkam","type":"section","seq":182,"chapter":"كتاب الصلاة","title":"129- عن عبد الله بن عمرو بن العاص عن أبي بكر الصديق رضي الله عنهم أنه قال لرسول الله - صلى الله","page":"ص0","text":"عن عبد الله بن عمرو بن العاص عن أبي بكر الصديق رضي الله عنهم أنه قال لرسول الله - صلى الله عليه وسلم -:\n((علمني دعاء أدعو به في صلاتي. قال: قل: اللهم إني ظلمت نفسي ظلما كثيرا. ولا يغفر الذنوب إلا أنت. فاغفر لي مغفرة من عندك. وارحمني , إنك أنت الغفور الرحيم)) .","bab":"باب التشهد"},{"id":"umdat-ahkam:183","bookId":"umdat-ahkam","type":"section","seq":183,"chapter":"كتاب الصلاة","title":"130- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((ما صلى رسول الله - صلى الله عليه وسلم - بعد أن نزلت عليه «إذا جاء نصر الله والفتح» - إلا يقول فيها: سبحانك ربنا وبحمدك , اللهم اغفر لي)) .","bab":"باب التشهد"},{"id":"umdat-ahkam:184","bookId":"umdat-ahkam","type":"section","seq":184,"chapter":"كتاب الصلاة","title":"ص: 94","page":"ص0","text":"وفي لفظ: ((كان رسول الله - صلى الله عليه وسلم - يكثر أن يقول في ركوعه وسجوده: سبحانك اللهم ربنا وبحمدك , اللهم اغفر لي)) .","bab":"باب التشهد"},{"id":"umdat-ahkam:185","bookId":"umdat-ahkam","type":"section","seq":185,"chapter":"كتاب الصلاة","title":"131- عن عبد الله بن عمر رضي الله عنهما قال","page":"ج1 ص94","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((سأل رجل النبي - صلى الله عليه وسلم - وهو على المنبر - ما ترى في صلاة الليل؟ قال: مثنى , مثنى. فإذا خشي أحدكم الصبح صلى واحدة. فأوترت له ما صلى. وإنه كان يقول: اجعلوا آخر صلاتكم بالليل وترا)) .\nمثنى مثنى: أي ركعتين ركعتين.","bab":"باب الوتر"},{"id":"umdat-ahkam:186","bookId":"umdat-ahkam","type":"section","seq":186,"chapter":"كتاب الصلاة","title":"132- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((من كل الليل أوتر رسول الله - صلى الله عليه وسلم -: من أول الليل , وأوسطه , وآخره. وانتهى وتره إلى السحر)) .","bab":"باب الوتر"},{"id":"umdat-ahkam:187","bookId":"umdat-ahkam","type":"section","seq":187,"chapter":"كتاب الصلاة","title":"133- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان رسول الله - صلى الله عليه وسلم - يصلي من الليل ثلاث عشرة ركعة يوتر من ذلك بخمس , لايجلس في شيء إلا في آخرها)) .","bab":"باب الوتر"},{"id":"umdat-ahkam:188","bookId":"umdat-ahkam","type":"section","seq":188,"chapter":"كتاب الصلاة","title":"134- عن عبد الله بن عباس رضي الله عنهما","page":"ج1 ص95","text":"عن عبد الله بن عباس رضي الله عنهما: ((أن رفع الصوت بالذكر , حين ينصرف الناس من المكتوبة كان على عهد رسول الله - صلى الله عليه وسلم -)) .\nقال ابن عباس: «كنت أعلم إذا انصرفوا بذلك إذا سمعته» .\nوفي لفظ «ما كنا نعرف انقضاء صلاة رسول الله - صلى الله عليه وسلم - بالتكبير» .","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:189","bookId":"umdat-ahkam","type":"section","seq":189,"chapter":"كتاب الصلاة","title":"135- عن وراد مولى المغيرة بن شعبة قال","page":"ص0","text":"عن وراد مولى المغيرة بن شعبة قال: أملى علي المغيرة بن شعبة من كتاب إلى معاوية: ((إن النبي - صلى الله عليه وسلم - كان يقول في دبر كل صلاة مكتوبة: \" لا إله إلا الله وحده لا شريك له، له الملك وله الحمد , وهو على كل شيء قدير. اللهم لا مانع لما أعطيت ولا معطي لما منعت , ولا ينفع ذا الجد منك الجد)) . ثم وفدت بعد ذلك على معاوية فسمعته يأمر الناس بذلك.\nوفي لفظ: ((كان ينهى عن قيل وقال , وإضاعة المال ,","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:190","bookId":"umdat-ahkam","type":"section","seq":190,"chapter":"كتاب الصلاة","title":"ص: 97","page":"ص0","text":"وكثرة السؤال وكان ينهى عن عقوق الأمهات , ووأد البنات , ومنع وهات)) .\nدبر كل صلاة: أي آخرها، والمراد بعد التسليم.\nالجد: الغنى والحظ.\nلاينفع ذا الجد منك الجد: لاينفع صاحب الحظ والغنى منك غناه وحظه.\nوأد البنات: دفنهن وهن حيات.\nومنع وهات: أي البخل بالمال عن الإنفاق في وجوهه المشروعة، وحرص شديد على جمعه.","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:191","bookId":"umdat-ahkam","type":"section","seq":191,"chapter":"كتاب الصلاة","title":"136- عن سمي مولى أبي بكر بن عبد الرحمن بن الحارث بن هشام عن أبي صالح السمان عن أبي هريرة - رضي","page":"ص0","text":"عن سمي مولى أبي بكر بن عبد الرحمن بن الحارث بن هشام عن أبي صالح السمان عن أبي هريرة - رضي الله عنه -: ((أن فقراء المسلمين أتوا رسول الله - صلى الله عليه وسلم - فقالوا: يا رسول الله , قد ذهب أهل الدثور بالدرجات العلى والنعيم المقيم. قال: وما ذاك؟ قالوا: يصلون كما نصلي , ويصومون كما نصوم , ويتصدقون ولا نتصدق. ويعتقون ولا نعتق. فقال رسول الله - صلى الله عليه وسلم -: أفلا أعلمكم شيئا تدركون به من سبقكم , وتسبقون من بعدكم. ولا يكون أحد أفضل منكم , إلا من صنع مثل ما صنعتم؟ قالوا: بلى , يا رسول الله. قال: تسبحون وتكبرون وتحمدون دبر كل صلاة: ثلاثا وثلاثين مرة. قال أبو صالح: فرجع فقراء المهاجرين , فقالوا: سمع إخواننا أهل الأموال بما فعلنا , ففعلوا مثله. فقال رسول الله - صلى الله عليه وسلم -:","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:192","bookId":"umdat-ahkam","type":"section","seq":192,"chapter":"كتاب الصلاة","title":"ص: 98","page":"ص0","text":"ذلك فضل الله يؤتيه من يشاء)) .\nالدثور: المال الكثير.","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:193","bookId":"umdat-ahkam","type":"section","seq":193,"chapter":"كتاب الصلاة","title":"137- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: ((أن النبي - صلى الله عليه وسلم - صلى في خميصة لها أعلام. فنظر إلى أعلامها نظرة. فلما انصرف قال: اذهبوا بخميصتي هذه إلى أبي جهم , وأتوني بأنبجانية أبي جهم. فإنها","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:194","bookId":"umdat-ahkam","type":"section","seq":194,"chapter":"كتاب الصلاة","title":"ص: 99","page":"ص0","text":"ألهتني آنفا عن صلاتي)) .\nخميصة لها أعلام: كساء مربع مخطط بألوان مختلفة.\nالأنبجانية: كساء غليظ ليس له أعلام، منسوبة إلى بلد تسمى أنبجان.","bab":"باب الذكر عقب الصلاة"},{"id":"umdat-ahkam:195","bookId":"umdat-ahkam","type":"section","seq":195,"chapter":"كتاب الصلاة","title":"138- عن عبد الله بن عباس رضي الله عنهما قال","page":"ج1 ص99","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((كان رسول الله- صلى الله عليه وسلم - يجمع في السفر بين صلاة الظهر والعصر , إذا كان على ظهر سير , ويجمع بين المغرب والعشاء)) .","bab":"باب الجمع بين الصلاتين في السفر"},{"id":"umdat-ahkam:196","bookId":"umdat-ahkam","type":"section","seq":196,"chapter":"كتاب الصلاة","title":"139- عن عبد الله بن عمر رضي الله عنهما قال","page":"ج1 ص100","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((صحبت رسول الله - صلى الله عليه وسلم - فكان لا يزيد في السفر على ركعتين , وأبا بكر وعمر وعثمان كذلك)) .","bab":"باب قصر الصلاة في السفر"},{"id":"umdat-ahkam:197","bookId":"umdat-ahkam","type":"section","seq":197,"chapter":"كتاب الصلاة","title":"140- عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال","page":"ج1 ص101","text":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال: ((من جاء منكم الجمعة فليغتسل))","bab":"باب الجمعة"},{"id":"umdat-ahkam:198","bookId":"umdat-ahkam","type":"section","seq":198,"chapter":"كتاب الصلاة","title":"141- عن جابر- رضي الله عنه - قال","page":"ص0","text":"عن جابر- رضي الله عنه - قال: ((كان رسول الله - صلى الله عليه وسلم - يخطب خطبتين وهو قائم , يفصل بينهما بجلوس)) .","bab":"باب الجمعة"},{"id":"umdat-ahkam:199","bookId":"umdat-ahkam","type":"section","seq":199,"chapter":"كتاب الصلاة","title":"142- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((جاء رجل والنبي - صلى الله عليه وسلم - يخطب الناس يوم الجمعة. فقال: صليت يا فلان؟ قال: لا. قال: قم فاركع ركعتين. وفي رواية فصل ركعتين)) .","bab":"باب الجمعة"},{"id":"umdat-ahkam:200","bookId":"umdat-ahkam","type":"section","seq":200,"chapter":"كتاب الصلاة","title":"143- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((إذا قلت لصاحبك: أنصت يوم الجمعة والإمام يخطب - فقد لغوت)) .","bab":"باب الجمعة"},{"id":"umdat-ahkam:201","bookId":"umdat-ahkam","type":"section","seq":201,"chapter":"كتاب الصلاة","title":"ص: 103","page":"ص0","text":"لغوت: تكلمت بكلام ساقط ليس فيه فائدة.","bab":"باب الجمعة"},{"id":"umdat-ahkam:202","bookId":"umdat-ahkam","type":"section","seq":202,"chapter":"كتاب الصلاة","title":"144- عن سهل بن سعد الساعدي قال","page":"ص0","text":"عن سهل بن سعد الساعدي قال: ((رأيت رسول الله قام - صلى الله عليه وسلم - فكبر وكبر الناس وراءه , وهو على المنبر. ثم رفع فنزل القهقرى , حتى سجد في أصل المنبر , ثم عاد حتى فرغ من آخر صلاته. ثم أقبل على الناس , فقال: أيها الناس , إنما صنعت هذا لتأتموا بي , ولتعلموا صلاتي - وفي لفظ - صلى عليها. ثم كبر عليها. ثم ركع وهو عليها , فنزل القهقرى)) .\nتماروا: تجادلوا.\nطرفاء الغابة: شجر يشبه الأثل\nالغابة: الشجر الملتف.\nالقهقرى: أي رجع إلى الخلف.","bab":"باب الجمعة"},{"id":"umdat-ahkam:203","bookId":"umdat-ahkam","type":"section","seq":203,"chapter":"كتاب الصلاة","title":"145- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((من اغتسل يوم الجمعة , ثم راح في الساعة","bab":"باب الجمعة"},{"id":"umdat-ahkam:204","bookId":"umdat-ahkam","type":"section","seq":204,"chapter":"كتاب الصلاة","title":"ص: 104","page":"ص0","text":"الأولى فكأنما قرب بدنة. ومن راح في الساعة الثانية فكأنما قرب بقرة. ومن راح في الساعة الثالثة فكأنما قرب كبشا أقرن. ومن راح في الساعة الرابعة فكأنما قرب دجاجة. ومن راح في الساعة الخامسة فكأنما قرب بيضة. فإذا خرج الإمام حضرت الملائكة يسمعون الذكر)) .\nراح: سار أول النهار.\nالبدنة: البعير، ذكرا كان أو أنثى، ولاتكون إلامن الإبل.","bab":"باب الجمعة"},{"id":"umdat-ahkam:205","bookId":"umdat-ahkam","type":"section","seq":205,"chapter":"كتاب الصلاة","title":"146- عن سلمة بن الأكوع - وكان من أصحاب","page":"ص0","text":"عن سلمة بن الأكوع - وكان من أصحاب","bab":"باب الجمعة"},{"id":"umdat-ahkam:206","bookId":"umdat-ahkam","type":"section","seq":206,"chapter":"كتاب الصلاة","title":"ص: 105","page":"ص0","text":"الشجرة - رضي الله عنه - قال: ((كنا نصلي مع رسول الله - صلى الله عليه وسلم - الجمعة , ثم ننصرف. وليس للحيطان ظل نستظل به)) .\nوفي لفظ: ((كنا نجمع مع رسول الله - صلى الله عليه وسلم - إذا زالت الشمس , ثم نرجع فنتتبع الفيء)) .\nنجمع: نقيم الجمعة.","bab":"باب الجمعة"},{"id":"umdat-ahkam:207","bookId":"umdat-ahkam","type":"section","seq":207,"chapter":"كتاب الصلاة","title":"147- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((كان النبي - صلى الله عليه وسلم - يقرأ في","bab":"باب الجمعة"},{"id":"umdat-ahkam:208","bookId":"umdat-ahkam","type":"section","seq":208,"chapter":"كتاب الصلاة","title":"ص: 106","page":"ص0","text":"صلاة الفجر يوم الجمعة: الم تنزيل السجدة و: هل أتى على الإنسان)) .","bab":"باب الجمعة"},{"id":"umdat-ahkam:209","bookId":"umdat-ahkam","type":"section","seq":209,"chapter":"كتاب الصلاة","title":"148- عن عبد الله بن عمر رضي الله عنهما قال","page":"ج1 ص106","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((كان النبي - صلى الله عليه وسلم - وأبو بكر وعمر يصلون العيدين قبل الخطبة)) .","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:210","bookId":"umdat-ahkam","type":"section","seq":210,"chapter":"كتاب الصلاة","title":"149- عن البراء بن عازب رضي الله عنه قال","page":"ص0","text":"عن البراء بن عازب رضي الله عنه قال: ((خطبنا النبي - صلى الله عليه وسلم - يوم الأضحى بعد الصلاة , فقال: من صلى صلاتنا ونسك","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:211","bookId":"umdat-ahkam","type":"section","seq":211,"chapter":"كتاب الصلاة","title":"ص: 107","page":"ص0","text":"نسكنا فقد أصاب النسك , ومن نسك قبل الصلاة فلا نسك له. فقال أبو بردة بن نيار - خال البراء بن عازب - يا رسول الله , إني نسكت شاتي قبل الصلاة. وعرفت أن اليوم يوم أكل وشرب. وأحببت أن تكون شاتي أول ما يذبح في بيتي. فذبحت شاتي , وتغذيت قبل أن آتي الصلاة. فقال: شاتك شاة لحم. قال: يا رسول الله , فإن عندنا عناقا هي أحب إلي من شاتين أفتجزي عني؟ قال: نعم , ولن تجزي عن أحد بعدك)) .","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:212","bookId":"umdat-ahkam","type":"section","seq":212,"chapter":"كتاب الصلاة","title":"ص: 108","page":"ص0","text":"النسك: الذبح. والنسيكة: الذبيحة.\nعناقا: العناق: الأنثى من ولد المعز، لم تتم الحول.","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:213","bookId":"umdat-ahkam","type":"section","seq":213,"chapter":"كتاب الصلاة","title":"150- عن جندب بن عبد الله البجلي - رضي الله عنه - قال","page":"ص0","text":"عن جندب بن عبد الله البجلي - رضي الله عنه - قال: ((صلى النبي - صلى الله عليه وسلم - يوم النحر. ثم خطب. ثم ذبح وقال: من ذبح قبل أن يصلي فليذبح أخرى مكانها , ومن لم يذبح فليذبح باسم الله)) .","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:214","bookId":"umdat-ahkam","type":"section","seq":214,"chapter":"كتاب الصلاة","title":"151- عن جابر - رضي الله عنه - قال","page":"ص0","text":"عن جابر - رضي الله عنه - قال: ((شهدت مع النبي - صلى الله عليه وسلم - يوم العيد. فبدأ بالصلاة قبل الخطبة , بلا أذان ولا إقامة. ثم قام متوكئا على بلال , فأمر بتقوى الله تعالى , وحث على طاعته , ووعظ الناس وذكرهم , ثم مضى حتى أتى النساء فوعظهن وذكرهن , وقال: يا معشر النساء , تصدقن. فإنكن أكثر حطب جهنم , فقامت امرأة من سطة النساء , سفعاء الخدين فقالت: لم","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:215","bookId":"umdat-ahkam","type":"section","seq":215,"chapter":"كتاب الصلاة","title":"ص: 109","page":"ص0","text":"يا رسول الله فقال: لأنكن تكثرن الشكاة , وتكفرن العشير. قال: فجعلن يتصدقن من حليهن يلقين في ثوب بلال من أقراطهن وخواتيمهن)) .\nسطة النساء: أي جالسة وسطهن.\nسفعاء الخدين: السفع: السواد والشحوب.\nالشكاة: الشكوى.\nتكفرن العشير: تجحدن إحسان الزوج.\nأقراطهن: هو جمع «قرط» : وهو الحلق الذي يعلق بشحمة الأذن.","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:216","bookId":"umdat-ahkam","type":"section","seq":216,"chapter":"كتاب الصلاة","title":"152- عن أم عطية - نسيبة الأنصارية - قالت","page":"ص0","text":"عن أم عطية - نسيبة الأنصارية - قالت: ((أمرنا رسول الله - صلى الله عليه وسلم - أن نخرج في العيدين العواتق وذوات","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:217","bookId":"umdat-ahkam","type":"section","seq":217,"chapter":"كتاب الصلاة","title":"ص: 110","page":"ص0","text":"الخدور , وأمر الحيض أن يعتزلن مصلى المسلمين)) .\nوفي لفظ: ((كنا نؤمر أن نخرج يوم العيد , حتى نخرج البكر من خدرها , حتى تخرج الحيض , فيكبرن بتكبيرهم ويدعون بدعائهم , يرجون بركة ذلك اليوم وطهرته)) .\nالعواتق: جمع «عاتق» المرأة الشابة أول ماتبلغ.\nذوات الخدور: جمع «خدر» وهو جانب من البيت، يجعل يرخى عليه سترة، يكون للجارية البكر.\nالحيض: جمع «حائض» ، وهي المرأة في زمن الحيض.","bab":"باب صلاة العيدين"},{"id":"umdat-ahkam:218","bookId":"umdat-ahkam","type":"section","seq":218,"chapter":"كتاب الصلاة","title":"153- عن عائشة رضي الله عنها","page":"ج1 ص110","text":"عن عائشة رضي الله عنها: ((أن الشمس خسفت على عهد رسول الله - صلى الله عليه وسلم - فبعث مناديا ينادي: الصلاة جامعة. فاجتمعوا. وتقدم , فكبر وصلى أربع ركعات في ركعتين , وأربع سجدات)) .","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:219","bookId":"umdat-ahkam","type":"section","seq":219,"chapter":"كتاب الصلاة","title":"154- عن أبي مسعود - عقبة بن عمرو الأنصاري البدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي مسعود - عقبة بن عمرو الأنصاري البدري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إن الشمس والقمر آيتان من آيات الله , يخوف الله بهما عباده , وإنهما لا ينخسفان لموت أحد من الناس. فإذا رأيتم منها شيئا فصلوا , وادعوا حتى ينكشف ما بكم)) .","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:220","bookId":"umdat-ahkam","type":"section","seq":220,"chapter":"كتاب الصلاة","title":"155- عن عائشة رضي الله عنها أنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها أنها قالت: ((خسفت الشمس على عهد رسول الله - صلى الله عليه وسلم - فصلى رسول الله - صلى الله عليه وسلم - بالناس. فأطال القيام , ثم ركع , فأطال الركوع , ثم قام , فأطال القيام - وهو دون القيام الأول - ثم ركع , فأطال الركوع - وهو دون الركوع الأول - ثم سجد , فأطال السجود , ثم فعل في الركعة الأخرى مثل ما فعل في الركعة الأولى , ثم انصرف , وقد تجلت الشمس , فخطب الناس , فحمد الله وأثنى عليه , ثم قال: إن الشمس والقمر آيتان من آيات الله , لا يخسفان لموت أحد ولا لحياته , فإذا رأيتم ذلك فادعوا الله وكبروا , وصلوا وتصدقوا , ثم قال: يا أمة محمد , والله ما من أحد أغير من الله أن يزني عبده , أو تزني أمته , يا أمة محمد , والله لو تعلمون ما أعلم لضحكتم قليلا ولبكيتم كثيرا)) .","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:221","bookId":"umdat-ahkam","type":"section","seq":221,"chapter":"كتاب الصلاة","title":"ص: 112","page":"ص0","text":"وفي لفظ: ((فاستكمل أربع ركعات وأربع سجدات)) .\nأغير: أفعل تفضيل، وهي صفة ثابتة لله تليق بجلاله وعظمته.","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:222","bookId":"umdat-ahkam","type":"section","seq":222,"chapter":"كتاب الصلاة","title":"156- عن أبي موسى الأشعري - رضي الله عنه - قال","page":"ص0","text":"عن أبي موسى الأشعري - رضي الله عنه - قال: ((خسفت الشمس على زمان رسول الله - صلى الله عليه وسلم -. فقام فزعا , ويخشى أن تكون الساعة , حتى أتى المسجد. فقام , فصلى بأطول قيام وسجود , ما رأيته يفعله في صلاته قط , ثم قال: إن هذه الآيات التي يرسلها الله عز وجل: لا تكون لموت أحد ولا لحياته. ولكن الله يرسلها يخوف","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:223","bookId":"umdat-ahkam","type":"section","seq":223,"chapter":"كتاب الصلاة","title":"ص: 113","page":"ص0","text":"بها عباده , فإذا رأيتم منها شيئا فافزعوا إلى ذكر الله ودعائه واستغفاره)) .","bab":"باب صلاة الكسوف"},{"id":"umdat-ahkam:224","bookId":"umdat-ahkam","type":"section","seq":224,"chapter":"كتاب الصلاة","title":"157- عن عبد الله بن زيد بن عاصم المازني - رضي الله عنه - قال","page":"ج1 ص113","text":"عن عبد الله بن زيد بن عاصم المازني - رضي الله عنه - قال: ((خرج النبي - صلى الله عليه وسلم - يستسقي , فتوجه إلى القبلة يدعو , وحول رداءه , ثم صلى ركعتين , جهر فيهما بالقراءة)) . وفي لفظ «إلى المصلى» .","bab":"باب الاستسقاء"},{"id":"umdat-ahkam:225","bookId":"umdat-ahkam","type":"section","seq":225,"chapter":"كتاب الصلاة","title":"158- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - ((أن رجلا دخل المسجد يوم الجمعة من باب كان نحو دار القضاء , ورسول الله - صلى الله عليه وسلم - قائم يخطب , فاستقبل رسول الله - صلى الله عليه وسلم - قائما , ثم قال: يا رسول الله , هلكت الأموال , وانقطعت السبل فادع الله تعالى يغيثنا , قال: فرفع","bab":"باب الاستسقاء"},{"id":"umdat-ahkam:226","bookId":"umdat-ahkam","type":"section","seq":226,"chapter":"كتاب الصلاة","title":"ص: 114","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - يديه ثم قال: اللهم أغثنا , اللهم أغثنا , اللهم أغثنا. قال أنس: فلا والله ما نرى في السماء من سحاب ولا قزعة , وما بيننا وبين سلع من بيت ولا دار قال: فطلعت من ورائه سحابة مثل الترس. فلما توسطت السماء انتشرت ثم أمطرت , قال: فلا والله ما رأينا الشمس سبتا , قال: ثم دخل رجل من ذلك الباب في الجمعة المقبلة , ورسول الله - صلى الله عليه وسلم - قائم يخطب الناس , فاستقبله قائما , فقال: يا رسول الله , هلكت الأموال , وانقطعت السبل , فادع الله أن يمسكها عنا , قال: فرفع رسول الله - صلى الله عليه وسلم - يديه ثم قال: اللهم حوالينا ولا علينا , اللهم على الآكام والظراب وبطون الأودية ومنابت الشجر , قال: فأقلعت , وخرجنا نمشي في الشمس. قال شريك: فسألت أنس بن مالك: أهو الرجل الأول قال: لا أدري)) .","bab":"باب الاستسقاء"},{"id":"umdat-ahkam:227","bookId":"umdat-ahkam","type":"section","seq":227,"chapter":"كتاب الصلاة","title":"ص: 115","page":"ص0","text":"دار القضاء: دار لعمر بن الخطاب بيعت لقضاء دينه بعد وفاته.\nقزعة: قطعة رقيقة من السحاب.\nسلع: جبل قرب المدينة في جانبها الغربي.\nالترس: صفيحة مستديرة من حديد تستخدم في الحرب.\nالآكام: التلول.\nالظراب: الروابي الصغار.\nأقلعت: أمسكت عن المطر.\nمارأينا الشمس سبتا: أي أسبوعا.","bab":"باب الاستسقاء"},{"id":"umdat-ahkam:228","bookId":"umdat-ahkam","type":"section","seq":228,"chapter":"كتاب الصلاة","title":"159- عن عبد الله بن عمر بن الخطاب رضي الله عنهما قال","page":"ج1 ص115","text":"عن عبد الله بن عمر بن الخطاب رضي الله عنهما قال: ((صلى بنا رسول الله - صلى الله عليه وسلم - صلاة الخوف في بعض أيامه , فقامت طائفة معه , وطائفة بإزاء العدو , فصلى بالذين معه ركعة , ثم ذهبوا , وجاء الآخرون , فصلى بهم ركعة , وقضت الطائفتان ركعة , ركعة)) .","bab":"باب صلاة الخوف"},{"id":"umdat-ahkam:229","bookId":"umdat-ahkam","type":"section","seq":229,"chapter":"كتاب الصلاة","title":"160- عن يزيد بن رومان عن صالح بن خوات بن جبير عمن صلى مع رسول الله - صلى الله عليه وسلم - صلاة","page":"ص0","text":"عن يزيد بن رومان عن صالح بن خوات بن جبير عمن صلى مع رسول الله - صلى الله عليه وسلم - صلاة ذات الرقاع , صلاة الخوف: أن","bab":"باب صلاة الخوف"},{"id":"umdat-ahkam:230","bookId":"umdat-ahkam","type":"section","seq":230,"chapter":"كتاب الصلاة","title":"ص: 116","page":"ص0","text":"طائفة صفت معه , وطائفة وجاه العدو , فصلى بالذين معه ركعة , ثم ثبت قائما , وأتموا لأنفسهم , ثم انصرفوا , فصفوا وجاه العدو , وجاءت الطائفة الأخرى , فصلى بهم الركعة التي بقيت , ثم ثبت جالسا , وأتموا لأنفسهم , ثم سلم بهم)) .","bab":"باب صلاة الخوف"},{"id":"umdat-ahkam:231","bookId":"umdat-ahkam","type":"section","seq":231,"chapter":"كتاب الصلاة","title":"161- عن جابر بن عبد الله الأنصاري رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله الأنصاري رضي الله عنهما قال: ((شهدت مع رسول الله - صلى الله عليه وسلم - صلاة الخوف فصففنا صفين خلف رسول الله - صلى الله عليه وسلم - والعدو بيننا وبين القبلة , وكبر النبي - صلى الله عليه وسلم - وكبرنا جميعا , ثم ركع وركعنا جميعا , ثم رفع رأسه من الركوع ورفعنا جميعا , ثم انحدر بالسجود والصف الذي يليه , وقام الصف المؤخر في نحر العدو , فلما قضى النبي - صلى الله عليه وسلم - السجود , وقام الصف الذي يليه: انحدر الصف المؤخر بالسجود , وقاموا , ثم تقدم الصف المؤخر , وتأخر الصف المقدم , ثم ركع النبي - صلى الله عليه وسلم - وركعنا جميعا , ثم رفع رأسه من الركوع ورفعنا جميعا , ثم انحدر بالسجود , والصف الذي يليه - الذي كان مؤخرا في الركعة الأولى - فقام الصف المؤخر في نحر","bab":"باب صلاة الخوف"},{"id":"umdat-ahkam:232","bookId":"umdat-ahkam","type":"section","seq":232,"chapter":"كتاب الصلاة","title":"ص: 117","page":"ص0","text":"العدو , فلما قضى النبي - صلى الله عليه وسلم - السجود والصف الذي يليه: انحدر الصف المؤخر بالسجود , فسجدوا ثم سلم - صلى الله عليه وسلم - وسلمنا جميعا , قال جابر: كما يصنع حرسكم هؤلاء بأمرائهم)) .\nوذكره مسلم بتمامه. وذكر البخاري طرفا منه: ((وأنه صلى صلاة الخوف مع النبي - صلى الله عليه وسلم - في الغزوة السابعة , غزوة ذات الرقاع)) .\nنحر العدو: مقابلة العدو.","bab":"باب صلاة الخوف"},{"id":"umdat-ahkam:233","bookId":"umdat-ahkam","type":"section","seq":233,"chapter":"كتاب الجنائز","title":"كتاب الجنائز","page":"ص0","text":"يقال: جنازة بفتح الجيم وكسرها، وقيل: بالفتح اسم للميت، وبالكسر اسم للنعش."},{"id":"umdat-ahkam:234","bookId":"umdat-ahkam","type":"section","seq":234,"chapter":"كتاب الجنائز","title":"162- عن أبي هريرة - رضي الله عنه - قال","page":"ج1 ص117","text":"عن أبي هريرة - رضي الله عنه - قال: ((نعى النبي - صلى الله عليه وسلم - النجاشي في اليوم الذي مات فيه , خرج بهم إلى المصلى , فصف بهم , وكبر أربعا)) ."},{"id":"umdat-ahkam:235","bookId":"umdat-ahkam","type":"section","seq":235,"chapter":"كتاب الجنائز","title":"ص: 118","page":"ج1 ص117","text":"النجاشي: ملك الحبشة، واسمه أصحمة، توفي في رجب، سنة تسع- رضي الله عنه -."},{"id":"umdat-ahkam:236","bookId":"umdat-ahkam","type":"section","seq":236,"chapter":"كتاب الجنائز","title":"163- عن جابر - رضي الله عنه -","page":"ص0","text":"عن جابر - رضي الله عنه -: ((أن النبي - صلى الله عليه وسلم - صلى على النجاشي , فكنت في الصف الثاني , أو الثالث)) ."},{"id":"umdat-ahkam:237","bookId":"umdat-ahkam","type":"section","seq":237,"chapter":"كتاب الجنائز","title":"164- عن عبد الله بن عباس رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما: ((أن النبي - صلى الله عليه وسلم - صلى على قبر , بعد ما دفن , فكبر عليه أربعا)) ."},{"id":"umdat-ahkam:238","bookId":"umdat-ahkam","type":"section","seq":238,"chapter":"كتاب الجنائز","title":"165- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: ((أن رسول الله - صلى الله عليه وسلم - كفن في أثواب بيض يمانية , ليس فيها قميص ولا عمامة)) ."},{"id":"umdat-ahkam:239","bookId":"umdat-ahkam","type":"section","seq":239,"chapter":"كتاب الجنائز","title":"ص: 119","page":"ص0","text":"أثواب يمانية: نسجت في اليمن، فنسبت إليه.\nسحولية: بيض نقية، ولاتكون إلا من القطن."},{"id":"umdat-ahkam:240","bookId":"umdat-ahkam","type":"section","seq":240,"chapter":"كتاب الجنائز","title":"166- عن أم عطية الأنصارية قالت","page":"ص0","text":"عن أم عطية الأنصارية قالت: ((دخل علينا رسول الله - صلى الله عليه وسلم - حين توفيت ابنته , فقال: اغسلنها ثلاثا , أو خمسا , أو أكثر من ذلك - إن رأيتن ذلك - بماء وسدر , واجعلن في الأخيرة كافورا - أو شيئا من كافور - فإذا فرغتن فآذنني)) .\nفلما فرغنا آذناه. فأعطانا حقوه. وقال: أشعرنها به - تعني إزاره.\nوفي رواية «أو سبعا» , وقال: ((ابدأن بميامنها ومواضع الوضوء منها)) وإن أم عطية قالت: وجعلنا رأسها ثلاثة قرون)) .\nرأيتن ذلك: بكسر الكاف، لأن المخاطبة أنثى.\nسدر: هو شجر النبق المعروف.\nكافور: نوع من الطيب.\nآذنني: أعلمنني.\nحقوه: الحقو بفتح الحاء وكسرها: الإزار.\nأشعرنها إياه: الشعار، مايلي الجسد من الثياب، ومعناه: اجعلن إزاري مما يلي جسدها.\nبميامنها: الميامن: جمع «ميمنة» بمعنى اليمين."},{"id":"umdat-ahkam:241","bookId":"umdat-ahkam","type":"section","seq":241,"chapter":"كتاب الجنائز","title":"167- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((بينما رجل واقف بعرفة , إذ وقع عن راحلته , فوقصته - أو قال: فأوقصته - فقال"},{"id":"umdat-ahkam:242","bookId":"umdat-ahkam","type":"section","seq":242,"chapter":"كتاب الجنائز","title":"ص: 120","page":"ص0","text":"رسول الله - صلى الله عليه وسلم -: اغسلوه بماء وسدر , وكفنوه في ثوبيه. ولا تحنطوه , ولا تخمروا رأسه. فإنه يبعث يوم القيامة ملبيا)) . وفي رواية: ((ولا تخمروا وجهه ولا رأسه)) .\nالوقص: كسر العنق.\nلاتحنطوه: لاتضعوا الطيب عليه.\nلاتخمروا رأسه: لاتغطوه."},{"id":"umdat-ahkam:243","bookId":"umdat-ahkam","type":"section","seq":243,"chapter":"كتاب الجنائز","title":"168- عن أم عطية الأنصارية رضي الله عنها قالت","page":"ص0","text":"عن أم عطية الأنصارية رضي الله عنها قالت: ((نهينا عن اتباع الجنائز ولم يعزم علينا)) ."},{"id":"umdat-ahkam:244","bookId":"umdat-ahkam","type":"section","seq":244,"chapter":"كتاب الجنائز","title":"169- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((أسرعوا بالجنازة فإنها إن تك صالحة: فخير تقدمونها إليه. وإن تك سوى ذلك: فشر: تضعونه عن رقابكم)) ."},{"id":"umdat-ahkam:245","bookId":"umdat-ahkam","type":"section","seq":245,"chapter":"كتاب الجنائز","title":"170- عن سمرة بن جندب- رضي الله عنه - قال","page":"ص0","text":"عن سمرة بن جندب- رضي الله عنه - قال: ((صليت وراء النبي - صلى الله عليه وسلم - على امرأة ماتت في نفاسها فقام في وسطها)) ."},{"id":"umdat-ahkam:246","bookId":"umdat-ahkam","type":"section","seq":246,"chapter":"كتاب الجنائز","title":"171- عن أبي موسى عبد الله بن قيس- رضي الله عنه -","page":"ص0","text":"عن أبي موسى عبد الله بن قيس- رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - بريء من الصالقة والحالقة والشاقة)) ."},{"id":"umdat-ahkam:247","bookId":"umdat-ahkam","type":"section","seq":247,"chapter":"كتاب الجنائز","title":"ص: 122","page":"ص0","text":"قال المصنف: الصالقة، التي ترفع صوتها عند المصيبة. أه\nالحالقة: التي تحلق شعرها، أوتنتفه من شدة الجزع والهلع.\nالشاقة: التي تشق جيبها أوثوبها تسخطا على قضاء الله.\nدعوى الجاهلية: هي النياحة، وكل قول بنبىء عن التسخط والجزع من قدر الله."},{"id":"umdat-ahkam:248","bookId":"umdat-ahkam","type":"section","seq":248,"chapter":"كتاب الجنائز","title":"172- عن عائشة رضي الله عنها قال","page":"ص0","text":"عن عائشة رضي الله عنها قال: ((لما اشتكى النبي - صلى الله عليه وسلم - ذكر بعض نسائه كنيسة رأينها بأرض الحبشة , يقال لها: مارية - وكانت أم سلمة وأم حبيبة أتتا أرض الحبشة - فذكرتا من حسنها وتصاوير فيها , فرفع رأسه - صلى الله عليه وسلم - وقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدا , ثم صوروا فيه تلك الصور أولئك شرار الخلق عند الله)) ."},{"id":"umdat-ahkam:249","bookId":"umdat-ahkam","type":"section","seq":249,"chapter":"كتاب الجنائز","title":"173- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: قال رسول الله - صلى الله عليه وسلم - في مرضه الذي لم يقم منه: ((لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد)) .\nقالت: ولولا ذلك أبرز قبره غير أنه خشي أن يتخذ مسجدا."},{"id":"umdat-ahkam:250","bookId":"umdat-ahkam","type":"section","seq":250,"chapter":"كتاب الجنائز","title":"174- عن عبد الله بن مسعود - رضي الله عنه - عن النبي - صلى الله عليه وسلم - أنه قال","page":"ص0","text":"عن عبد الله بن مسعود - رضي الله عنه - عن النبي - صلى الله عليه وسلم - أنه قال: ((ليس منا من ضرب الخدود , وشق الجيوب , ودعا بدعوى الجاهلية)) ."},{"id":"umdat-ahkam:251","bookId":"umdat-ahkam","type":"section","seq":251,"chapter":"كتاب الجنائز","title":"175- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((من شهد الجنازة حتى يصلي عليها فله قيراط. ومن شهدها حتى"},{"id":"umdat-ahkam:252","bookId":"umdat-ahkam","type":"section","seq":252,"chapter":"كتاب الجنائز","title":"ص: 124","page":"ص0","text":"تدفن فله قيراطان. قيل: وما القيراطان؟ قال: مثل الجبلين العظيمين)) .\nولمسلم: ((أصغرهما مثل أحد)) ."},{"id":"umdat-ahkam:253","bookId":"umdat-ahkam","type":"section","seq":253,"chapter":"كتاب الزكاة","title":"176- عن عبد الله بن عباس رضي الله عنهما قال","page":"ج1 ص125","text":"عن عبد الله بن عباس رضي الله عنهما قال: قال رسول الله - صلى الله عليه وسلم - لمعاذ بن جبل - حين بعثه إلى اليمن -: ((إنك ستأتي قوما أهل كتاب. فإذا جئتهم: فادعهم إلى أن يشهدوا أن لا إله إلا الله , وأن محمدا رسول الله. فإن هم أطاعوا لك بذلك فأخبرهم: أن الله قد فرض عليهم خمس صلوات في كل يوم وليلة. فإن هم أطاعوا لك بذلك , فأخبرهم: أن الله قد فرض عليهم صدقة , تؤخذ من أغنيائهم فترد على فقرائهم. فإن هم أطاعوا لك بذلك , فإياك وكرائم أموالهم. واتق دعوة المظلوم. فإنه ليس بينها وبين الله حجاب)) .\nصدقة: زكاة، وسميت الزكاة صدقة لأنها دليل على الصدق في الإيمان.\nكرائم: جمع «كريمة» أي نفيسة"},{"id":"umdat-ahkam:254","bookId":"umdat-ahkam","type":"section","seq":254,"chapter":"كتاب الزكاة","title":"177- عن أبي سعيد الخدري رضي الله عنه - قال","page":"ج1 ص125","text":"عن أبي سعيد الخدري رضي الله عنه - قال: قال"},{"id":"umdat-ahkam:255","bookId":"umdat-ahkam","type":"section","seq":255,"chapter":"كتاب الزكاة","title":"ص: 126","page":"ج1 ص125","text":"رسول الله - صلى الله عليه وسلم -: ((ليس فيما دون خمس أواق صدقة. ولا فيما دون خمس ذود صدقة. ولا فيما دون خمسة أوسق صدقة)) .\nأواق: جمع «أوقية» وهي تعادل أربعين درهما.\nذود: الذود يطلق على الثلاث من الإبل إلى العشر.\nأوسق: جمع «وسق» وهو ستون صاعا بالصاع النبوي."},{"id":"umdat-ahkam:256","bookId":"umdat-ahkam","type":"section","seq":256,"chapter":"كتاب الزكاة","title":"178- عن أبي هريرة رضي الله عنه أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة رضي الله عنه أن رسول الله - صلى الله عليه وسلم - قال: ((ليس على المسلم في عبده ولا فرسه صدقة)) ."},{"id":"umdat-ahkam:257","bookId":"umdat-ahkam","type":"section","seq":257,"chapter":"كتاب الزكاة","title":"ص: 127","page":"ص0","text":"وفي لفظ: ((إلا زكاة الفطر في الرقيق)) ."},{"id":"umdat-ahkam:258","bookId":"umdat-ahkam","type":"section","seq":258,"chapter":"كتاب الزكاة","title":"179- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((العجماء جبار. والبئر جبار. والمعدن جبار. وفي الركاز الخمس)) ."},{"id":"umdat-ahkam:259","bookId":"umdat-ahkam","type":"section","seq":259,"chapter":"كتاب الزكاة","title":"ص: 128","page":"ص0","text":"قال المصنف: الجبار: الهدر الذي لاشيء فيه. والعجماء: الدابة البهيم. أه\nالعجماء: البهيمة، وسميت عجماء لأنها لاتتكلم.\nجبار: أي هدر، لاضمان فيه.\nالركاز: هو دفن الجاهلية."},{"id":"umdat-ahkam:260","bookId":"umdat-ahkam","type":"section","seq":260,"chapter":"كتاب الزكاة","title":"180- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((بعث رسول الله - صلى الله عليه وسلم - عمر - رضي الله عنه - على الصدقة. فقيل: منع ابن جميل وخالد بن الوليد , والعباس عم رسول الله - صلى الله عليه وسلم -. فقال رسول الله - صلى الله عليه وسلم - ما ينقم ابن جميل , إلا أن كان فقيرا: فأغناه الله؟ وأما خالد: فإنكم تظلمون خالدا. وقد احتبس أدراعه وأعتاده في سبيل الله. وأما العباس: فهي علي ومثلها. ثم قال: يا عمر , أما شعرت أن عم الرجل صنو أبيه؟)) .\nأدراعه وأعتاده: هي آلات الحرب من السلاح والدواب.\nصنو أبيه: مثل أبيه وشبيه به."},{"id":"umdat-ahkam:261","bookId":"umdat-ahkam","type":"section","seq":261,"chapter":"كتاب الزكاة","title":"181- عن عبد الله بن زيد بن عاصم قال","page":"ص0","text":"عن عبد الله بن زيد بن عاصم قال: ((لما أفاء الله على رسوله يوم حنين: قسم في الناس , وفي"},{"id":"umdat-ahkam:262","bookId":"umdat-ahkam","type":"section","seq":262,"chapter":"كتاب الزكاة","title":"ص: 129","page":"ص0","text":"المؤلفة قلوبهم ولم يعط الأنصار شيئا. فكأنهم وجدوا في أنفسهم , إذ لم يصبهم ما أصاب الناس. فخطبهم , فقال: يا معشر الأنصار , ألم أجدكم ضلالا فهداكم الله بي؟ وكنتم متفرقين فألفكم الله بي؟ وعالة فأغناكم الله بي؟ . كلما قال شيئا، قالوا: الله ورسوله أمن. قال: ما يمنعكم أن تجيبوا رسول الله؟ قالوا: الله ورسوله أمن. قال: لو شئتم لقلتم: جئتنا كذا وكذا. ألا ترضون أن يذهب الناس بالشاة والبعير , وتذهبون برسول الله إلى رحالكم؟ لولا الهجرة لكنت امرأ من الأنصار، ولو سلك الناس واديا أو شعبا لسلكت وادي الأنصار وشعبها. الأنصار شعار , والناس دثار. إنكم ستلقون بعدي أثرة، فاصبروا حتى تلقوني على الحوض)) .\nحنين: واد بين مكة والطائف.\nأفاء: أعطى.\nالمؤلفة قلوبهم: هم قوم يتألفون على الإسلام، بإعطائهم من الغنائم أو الصدقات.\nوجدوا: غضبوا في أنفسهم.\nعالة: فقراء.\nأمن: أفعل تفضيل، معناه، أكثر منة علينا وأعظم.\nشعار: هو الثوب الذي يلي الجسد.\nدثار: هو الثوب الذي فوق الشعار.\nأثرة: الاستئثار بالشي المشترك."},{"id":"umdat-ahkam:263","bookId":"umdat-ahkam","type":"section","seq":263,"chapter":"كتاب الزكاة","title":"182- عن عبد الله بن عمر رضي الله عنهما قال","page":"ج1 ص129","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((فرض رسول الله - صلى الله عليه وسلم - صدقة الفطر - أو قال رمضان - على الذكر والأنثى","bab":"باب صدقة الفطر"},{"id":"umdat-ahkam:264","bookId":"umdat-ahkam","type":"section","seq":264,"chapter":"كتاب الزكاة","title":"ص: 130","page":"ج1 ص129","text":"والحر والمملوك: صاعا من تمر , أو صاعا من شعير. قال: فعدل الناس به نصف صاع من بر , على الصغير والكبير)) .\nوفي لفظ: ((أن تؤدى قبل خروج الناس إلى الصلاة)) .\nبر: قمح.","bab":"باب صدقة الفطر"},{"id":"umdat-ahkam:265","bookId":"umdat-ahkam","type":"section","seq":265,"chapter":"كتاب الزكاة","title":"183- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: ((كنا نعطيها في زمن - صلى الله عليه وسلم - صاعا من طعام , أو صاعا من شعير , أو صاعا من أقط , أو صاعا من زبيب. فلما جاء معاوية , وجاءت السمراء , قال: أرى مدا من هذه يعدل مدين. قال أبو سعيد: أما أنا: فلا أزال أخرجه كما كنت أخرجه على عهد رسول الله - صلى الله عليه وسلم -)) .","bab":"باب صدقة الفطر"},{"id":"umdat-ahkam:266","bookId":"umdat-ahkam","type":"section","seq":266,"chapter":"كتاب الزكاة","title":"ص: 131","page":"ص0","text":"أقط: لبن مجفف لم تنزع زبدته.\nالسمراء: القمح الشامي.\nالمد: حفنة بملء كفي الرجل المعتدل الكفين.","bab":"باب صدقة الفطر"},{"id":"umdat-ahkam:267","bookId":"umdat-ahkam","type":"section","seq":267,"chapter":"كتاب الصيام","title":"184- عن أبي هريرة - رضي الله عنه - قال","page":"ج1 ص131","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا تقدموا رمضان بصوم يوم , أو يومين إلا رجلا كان يصوم صوما فليصمه)) .\nلاتقدموا: أصله لاتتقدموا."},{"id":"umdat-ahkam:268","bookId":"umdat-ahkam","type":"section","seq":268,"chapter":"كتاب الصيام","title":"185- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((إذا رأيتموه فصوموا، وإذا رأيتموه فأفطروا، فإن غم عليكم فاقدروا له)) ."},{"id":"umdat-ahkam:269","bookId":"umdat-ahkam","type":"section","seq":269,"chapter":"كتاب الصيام","title":"ص: 132","page":"ص0","text":"غم: حال بينكم وبين رؤيته شيء كغيم وقتر. فاقدروا له: أي أكملوا عدة شعبان ثلاثين يوما."},{"id":"umdat-ahkam:270","bookId":"umdat-ahkam","type":"section","seq":270,"chapter":"كتاب الصيام","title":"186- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم - ((تسحروا فإن في السحور بركة)) .\nالسحور: بفتح السين، مايتسحر به. وبضمها، الفعل. والبركة تشمل الوقت ومايتسحر به من مأكول ومشروب."},{"id":"umdat-ahkam:271","bookId":"umdat-ahkam","type":"section","seq":271,"chapter":"كتاب الصيام","title":"187- عن أنس بن مالك عن زيد بن ثابت رضي الله عنهما قال","page":"ص0","text":"عن أنس بن مالك عن زيد بن ثابت رضي الله عنهما قال: ((تسحرنا مع رسول الله - صلى الله عليه وسلم -. ثم قام إلى الصلاة. قال أنس: قلت لزيد: كم كان بين الأذان والسحور؟ قال: قدر خمسين آية)) ."},{"id":"umdat-ahkam:272","bookId":"umdat-ahkam","type":"section","seq":272,"chapter":"كتاب الصيام","title":"188- عن عائشة وأم سلمة رضي الله عنهما","page":"ص0","text":"عن عائشة وأم سلمة رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - كان يدركه الفجر وهو جنب من أهله ثم يغتسل ويصوم)) ."},{"id":"umdat-ahkam:273","bookId":"umdat-ahkam","type":"section","seq":273,"chapter":"كتاب الصيام","title":"189- عن أبي هريرة رضي الله عنه عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة رضي الله عنه عن النبي - صلى الله عليه وسلم - قال: ((من نسي وهو صائم. فأكل أو شرب , فليتم صومه. فإنما أطعمه الله وسقاه)) ."},{"id":"umdat-ahkam:274","bookId":"umdat-ahkam","type":"section","seq":274,"chapter":"كتاب الصيام","title":"190- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((بينما نحن جلوس عند النبي - صلى الله عليه وسلم - إذ جاءه رجل. فقال: يا رسول الله , هلكت. قال: ما أهلكك؟ قال: وقعت على امرأتي , وأنا صائم - وفي رواية: أصبت أهلي في رمضان - فقال رسول الله - صلى الله عليه وسلم -: هل تجد رقبة تعتقها؟ قال: لا. قال: فهل تستطيع أن تصوم شهرين متتابعين؟ قال: لا. قال: فهل تجد إطعام ستين مسكينا؟ قال: لا. قال: فمكث النبي - صلى الله عليه وسلم - فبينا نحن على ذلك أتي النبي - صلى الله عليه وسلم - بعرق فيه تمر - والعرق: المكتل - قال: أين السائل؟ قال: أنا. قال: خذ هذا , فتصدق به. فقال الرجل: على أفقر مني: يا رسول الله؟ فوالله ما بين لابتيها - يريد الحرتين - أهل بيت أفقر من أهل بيتي. فضحك رسول الله - صلى الله عليه وسلم"},{"id":"umdat-ahkam:275","bookId":"umdat-ahkam","type":"section","seq":275,"chapter":"كتاب الصيام","title":"ص: 134","page":"ص0","text":"حتى بدت أنيابه. ثم قال: أطعمه أهلك)) .\nوقعت على امرأتي: أي جامعتها.\nعرق: هو المكتل، ويصنع من سعف النخيل، ويسع (15) خمسة عشر صاعا.\nلابتيها: تثنية «لابة» وهي الأرض التي تعلوها حجارة سود، والحرتان هما الجبلان، يريد أن المدينة تقع بين حرتين شرقية وغربية."},{"id":"umdat-ahkam:276","bookId":"umdat-ahkam","type":"section","seq":276,"chapter":"كتاب الصيام","title":"191- عن عائشة رضي الله عنها","page":"ج1 ص134","text":"عن عائشة رضي الله عنها: ((أن حمزة بن عمرو الأسلمي قال للنبي - صلى الله عليه وسلم -: أأصوم في السفر؟ - وكان كثير الصيام - فقال: إن شئت فصم وإن شئت فأفطر)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:277","bookId":"umdat-ahkam","type":"section","seq":277,"chapter":"كتاب الصيام","title":"192- عن أنس بن مالك - رضي الله عنه - قال","page":"ج1 ص134","text":"عن أنس بن مالك - رضي الله عنه - قال: ((كنا نسافر مع النبي - صلى الله عليه وسلم - فلم يعب الصائم على المفطر. ولا المفطر على الصائم)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:278","bookId":"umdat-ahkam","type":"section","seq":278,"chapter":"كتاب الصيام","title":"193- عن أبي الدرداء - رضي الله عنه - قال","page":"ص0","text":"عن أبي الدرداء - رضي الله عنه - قال: ((خرجنا مع رسول الله - صلى الله عليه وسلم - في شهر رمضان. في حر شديد , حتى إن كان أحدنا ليضع يده على رأسه من شدة الحر. وما فينا صائم إلا رسول الله - صلى الله عليه وسلم - وعبد الله بن رواحة)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:279","bookId":"umdat-ahkam","type":"section","seq":279,"chapter":"كتاب الصيام","title":"194- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((كان رسول الله - صلى الله عليه وسلم - في سفر. فرأى زحاما ورجلا قد ظلل عليه , فقال: ما هذا؟ قالوا: صائم. قال: ليس من البر الصيام في السفر)) .\nوفي لفظ لمسلم: ((عليكم برخصة الله التي رخص لكم)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:280","bookId":"umdat-ahkam","type":"section","seq":280,"chapter":"كتاب الصيام","title":"195- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: ((كنا مع النبي - صلى الله عليه وسلم - في السفر فمنا الصائم , ومنا المفطر قال: فنزلنا منزلا في يوم حار , وأكثرنا ظلا: صاحب الكساء. ومنا من يتقي الشمس بيده. قال: فسقط الصوام , وقام المفطرون فضربوا الأبنية. وسقوا الركاب، فقال رسول الله - صلى الله عليه وسلم -: ذهب المفطرون اليوم بالأجر)) .\nالركاب: الإبل.","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:281","bookId":"umdat-ahkam","type":"section","seq":281,"chapter":"كتاب الصيام","title":"196- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كان يكون علي الصوم","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:282","bookId":"umdat-ahkam","type":"section","seq":282,"chapter":"كتاب الصيام","title":"ص: 137","page":"ص0","text":"من رمضان , فما أستطيع أن أقضي إلا في شعبان)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:283","bookId":"umdat-ahkam","type":"section","seq":283,"chapter":"كتاب الصيام","title":"197- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: أن رسول الله - صلى الله عليه وسلم - قال: ((من مات وعليه صيام صام عنه وليه)) . وأخرجه أبو داود وقال «هذا في النذر , وهو قول أحمد بن حنبل» .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:284","bookId":"umdat-ahkam","type":"section","seq":284,"chapter":"كتاب الصيام","title":"198- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((جاء رجل إلى النبي - صلى الله عليه وسلم - فقال: يا رسول الله , إن أمي ماتت وعليها صوم شهر. أفأقضيه عنها؟ فقال: لو كان على أمك دين أكنت قاضيه عنها؟ قال: نعم. قال: فدين الله أحق أن يقضى)) .\nوفي رواية: ((جاءت امرأة إلى رسول الله صلى الله عليه وسلم فقالت: يا رسول الله , إن أمي ماتت وعليها صوم نذر. أفأصوم عنها؟ فقال: أرأيت لو كان على أمك دين فقضيتيه , أكان ذلك يؤدي عنها؟ فقالت: نعم. قال: فصومي عن أمك)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:285","bookId":"umdat-ahkam","type":"section","seq":285,"chapter":"كتاب الصيام","title":"199- عن سهل بن سعد الساعدي - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن سهل بن سعد الساعدي - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((لا يزال الناس بخير ما عجلوا الفطر)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:286","bookId":"umdat-ahkam","type":"section","seq":286,"chapter":"كتاب الصيام","title":"200- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إذا أقبل الليل من ههنا. وأدبر النهار من ههنا: فقد أفطر الصائم)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:287","bookId":"umdat-ahkam","type":"section","seq":287,"chapter":"كتاب الصيام","title":"201- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((نهى رسول الله - صلى الله عليه وسلم - عن الوصال. قالوا: إنك تواصل. قال: إني لست كهيئتكم , إني أطعم وأسقى)) . ورواه أبو هريرة وعائشة وأنس بن مالك.\nالوصال: هو وصل الصوم متابعة بعضه بعضا دون فطر أوسحور.","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:288","bookId":"umdat-ahkam","type":"section","seq":288,"chapter":"كتاب الصيام","title":"202- ولمسلم عن أبي سعيد الخدري - رضي الله عنه -","page":"ص0","text":"ولمسلم عن أبي سعيد الخدري - رضي الله عنه -: ((فأيكم أراد أن يواصل فليواصل إلى السحر)) .","bab":"باب الصوم في السفر وغيره"},{"id":"umdat-ahkam:289","bookId":"umdat-ahkam","type":"section","seq":289,"chapter":"كتاب الصيام","title":"203- عن عبد الله بن عمرو بن العاص رضي الله عنهما قال","page":"ج1 ص139","text":"عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: ((أخبر رسول الله - صلى الله عليه وسلم - أني أقول: والله لأصومن النهار , ولأقومن الليل ما عشت. فقال رسول الله - صلى الله عليه وسلم -: أنت الذي قلت ذلك؟ فقلت له: قد قلته ,","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:290","bookId":"umdat-ahkam","type":"section","seq":290,"chapter":"كتاب الصيام","title":"ص: 140","page":"ج1 ص139","text":"بأبي أنت وأمي. فقال: فإنك لا تستطيع ذلك. فصم وأفطر , وقم ونم. وصم من الشهر ثلاثة أيام فإن الحسنة بعشر أمثالها. وذلك مثل صيام الدهر. قلت: فإني أطيق أفضل من ذلك. قال: فصم يوما وأفطر يومين. قلت: أطيق أفضل من ذلك. قال: فصم يوما وأفطر يوما. فذلك مثل صيام داود. وهو أفضل الصيام. فقلت: إني أطيق أفضل من ذلك. قال: لا أفضل من ذلك)) .\nوفي رواية: ((لا صوم فوق صوم أخي داود - شطر الدهر - صم يوما وأفطر يوما)) .\nشطر الدهر: نصف الدهر.","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:291","bookId":"umdat-ahkam","type":"section","seq":291,"chapter":"كتاب الصيام","title":"204- عن عبد الله بن عمرو بن العاص رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: قال رسول الله - صلى الله عليه وسلم -: ((إن أحب الصيام إلى الله صيام داود. وأحب الصلاة إلى الله صلاة داود. كان ينام نصف الليل , ويقوم ثلثه. وينام سدسه. وكان يصوم يوما ويفطر يوما)) .","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:292","bookId":"umdat-ahkam","type":"section","seq":292,"chapter":"كتاب الصيام","title":"205- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((أوصاني خليلي - صلى الله عليه وسلم - بثلاث صيام ثلاثة أيام من كل شهر , وركعتي الضحى , وأن أوتر قبل أن أنام)) .","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:293","bookId":"umdat-ahkam","type":"section","seq":293,"chapter":"كتاب الصيام","title":"206- عن محمد بن عباد بن جعفر قال","page":"ص0","text":"عن محمد بن عباد بن جعفر قال: ((سألت جابر بن عبد الله أنهى النبي - صلى الله عليه وسلم - عن صوم يوم الجمعة؟ قال: نعم)) وزاد مسلم ((ورب الكعبة)) .","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:294","bookId":"umdat-ahkam","type":"section","seq":294,"chapter":"كتاب الصيام","title":"207- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((لا يصومن أحدكم يوم الجمعة , إلا أن يصوم يوما قبله , أو يوما بعده)) .","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:295","bookId":"umdat-ahkam","type":"section","seq":295,"chapter":"كتاب الصيام","title":"208- عن أبي عبيد مولى ابن أزهر واسمه سعد بن عبيد - قال","page":"ص0","text":"عن أبي عبيد مولى ابن أزهر واسمه سعد بن عبيد - قال: ((شهدت العيد مع عمر بن الخطاب - رضي الله عنه - فقال: هذان يومان نهى رسول الله - صلى الله عليه وسلم - عن صيامهما: يوم فطركم من صيامكم , واليوم الآخر: تأكلون فيه من نسككم)) .\nنسككم: أضاحيكم.","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:296","bookId":"umdat-ahkam","type":"section","seq":296,"chapter":"كتاب الصيام","title":"209- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: ((نهى رسول الله - صلى الله عليه وسلم - عن صوم يومين: الفطر والنحر. وعن الصماء , وأن يحتبي الرجل في الثوب الواحد , وعن الصلاة بعد الصبح والعصر)) . أخرجه مسلم بتمامه. وأخرج البخاري الصوم فقط","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:297","bookId":"umdat-ahkam","type":"section","seq":297,"chapter":"كتاب الصيام","title":"ص: 143","page":"ص0","text":"اشتمال الصماء: هي عند العرب أن يلف جسده كله بالثوب ولايجعل منه جانبا لإخراج يديه.\nيحتبي الرجل في الثوب الواحد: يجلس على أليتيه ويضم فخذيه وساقيه إلى بطنه ليستند.","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:298","bookId":"umdat-ahkam","type":"section","seq":298,"chapter":"كتاب الصيام","title":"210- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((من صام يوما في سبيل الله بعد الله وجهه عن النار سبعين خريفا)) .","bab":"باب أفضل الصيام وغيره"},{"id":"umdat-ahkam:299","bookId":"umdat-ahkam","type":"section","seq":299,"chapter":"كتاب الصيام","title":"211- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص143","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن رجالا من أصحاب النبي - صلى الله عليه وسلم - أروا ليلة القدر في المنام في السبع الأواخر. فقال النبي - صلى الله عليه وسلم -: أرى رؤياكم قد تواطأت في السبع الأواخر. فمن كان متحريها فليتحرها في السبع الأواخر)) .","bab":"باب ليلة القدر"},{"id":"umdat-ahkam:300","bookId":"umdat-ahkam","type":"section","seq":300,"chapter":"كتاب الصيام","title":"ص: 144","page":"ج1 ص143","text":"تواطأت: توافقت.","bab":"باب ليلة القدر"},{"id":"umdat-ahkam:301","bookId":"umdat-ahkam","type":"section","seq":301,"chapter":"كتاب الصيام","title":"212- عن عائشة رضي الله عنها أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عائشة رضي الله عنها أن رسول الله - صلى الله عليه وسلم - قال: ((تحروا ليلة القدر في الوتر من العشر الأواخر)) .","bab":"باب ليلة القدر"},{"id":"umdat-ahkam:302","bookId":"umdat-ahkam","type":"section","seq":302,"chapter":"كتاب الصيام","title":"213- عن أبي سعيد الخدري - رضي الله عنه -","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - كان يعتكف في العشر الأوسط من رمضان. فاعتكف عاما , حتى إذا كانت ليلة إحدى وعشرين - وهي الليلة التي يخرج من صبيحتها من اعتكافه - قال: من اعتكف معي فليعتكف العشر الأواخر فقد أريت هذه الليلة. ثم أنسيتها , وقد رأيتني أسجد في ماء وطين من صبيحتها. فالتمسوها في العشر الأواخر. والتمسوها في كل وتر. فمطرت السماء تلك الليلة. وكان المسجد على عريش. فوكف المسجد , فأبصرت عيناي رسول الله - صلى الله عليه وسلم - وعلى جبهته أثر الماء والطين من صبح إحدى وعشرين)) .\nوكف المسجد: أي قطر من سقفه الماء.","bab":"باب ليلة القدر"},{"id":"umdat-ahkam:303","bookId":"umdat-ahkam","type":"section","seq":303,"chapter":"كتاب الصيام","title":"214- عن عائشة رضي الله عنها","page":"ج1 ص144","text":"عن عائشة رضي الله عنها: ((أن رسول الله - صلى الله عليه وسلم - كان يعتكف في العشر الأواخر من رمضان , حتى توفاه الله عز وجل. ثم اعتكف أزواجه بعده)) .","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:304","bookId":"umdat-ahkam","type":"section","seq":304,"chapter":"كتاب الصيام","title":"ص: 145","page":"ج1 ص144","text":"وفي لفظ ((كان رسول الله - صلى الله عليه وسلم - يعتكف في كل رمضان. فإذا صلى الغداة جاء مكانه الذي اعتكف فيه)) .\nالغداة: الصبح.","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:305","bookId":"umdat-ahkam","type":"section","seq":305,"chapter":"كتاب الصيام","title":"215- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: ((أنها كانت ترجل النبي - صلى الله عليه وسلم - وهي حائض , وهو معتكف في المسجد. وهي في حجرتها: يناولها رأسه)) .\nوفي رواية: ((وكان لا يدخل البيت إلا لحاجة الإنسان)) .\nوفي رواية أن عائشة رضي الله عنها قالت «إن كنت لأدخل البيت للحاجة والمريض فيه. فما أسأل عنه إلا وأنا مارة» .","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:306","bookId":"umdat-ahkam","type":"section","seq":306,"chapter":"كتاب الصيام","title":"ص: 146","page":"ص0","text":"الترجيل: تسريح الشعر. أه\nحاجة الإنسان: البول والغائط.","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:307","bookId":"umdat-ahkam","type":"section","seq":307,"chapter":"كتاب الصيام","title":"216- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - قال: قلت: ((يا رسول الله , إني كنت نذرت في الجاهلية أن أعتكف ليلة)) - وفي رواية: ((يوما - في المسجد الحرام. قال فأوف بنذرك)) ولم يذكر بعض الرواة يوما ولا ليلة.","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:308","bookId":"umdat-ahkam","type":"section","seq":308,"chapter":"كتاب الصيام","title":"217- عن صفية بنت حيي رضي الله عنها قالت","page":"ص0","text":"عن صفية بنت حيي رضي الله عنها قالت: ((كان النبي - صلى الله عليه وسلم - معتكفا. فأتيته أزوره ليلا. فحدثته , ثم قمت لأنقلب , فقام معي ليقلبني - وكان مسكنها في دار أسامة بن زيد - فمر رجلان من الأنصار فلما رأيا رسول الله - صلى الله عليه وسلم - أسرعا. فقال النبي - صلى الله عليه وسلم -: على رسلكما. إنها صفية بنت حيي. فقالا: سبحان الله يا رسول الله. فقال: إن الشيطان يجري من ابن آدم مجرى الدم. وإني خشيت أن يقذف في قلوبكما شرا- أو قال شيئا)) .","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:309","bookId":"umdat-ahkam","type":"section","seq":309,"chapter":"كتاب الصيام","title":"ص: 147","page":"ص0","text":"وفي رواية ((أنها جاءت تزوره في اعتكافه في المسجد في العشر الأواخر من رمضان. فتحدثت عنده ساعة. ثم قامت تنقلب. فقام النبي - صلى الله عليه وسلم - معها يقلبها , حتى إذا بلغت باب المسجد عند باب أم سلمة)) . ثم ذكره بمعناه.","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:310","bookId":"umdat-ahkam","type":"section","seq":310,"chapter":"كتاب الصيام","title":"ص: 149","page":"ص0","text":"ليقلبني: ليردني ويرجعني إلى منزلي.\nرسلكما: على مهل وتؤدة.","bab":"باب الاعتكاف"},{"id":"umdat-ahkam:311","bookId":"umdat-ahkam","type":"section","seq":311,"chapter":"كتاب الحج","title":"218- عن عبد الله بن عباس رضي الله عنهما","page":"ج1 ص149","text":"عن عبد الله بن عباس رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - وقت لأهل المدينة: ذا الحليفة. ولأهل الشام: الجحفة. ولأهل نجد: قرن المنازل. ولأهل اليمن: يلملم.","bab":"باب المواقيت"},{"id":"umdat-ahkam:312","bookId":"umdat-ahkam","type":"section","seq":312,"chapter":"كتاب الحج","title":"ص: 150","page":"ج1 ص149","text":"هن لهم ولمن أتى عليهن من غير أهلهن , ممن أراد الحج أو العمرة. ومن كان دون ذلك: فمن حيث أنشأ , حتى أهل مكة من مكة)) .\nالمواقيت: جمع «ميقات» والمقصود بها المواقيت المكانية التي يحرم منها الحجيج.\nبيان المواقيت:\nأ: ذو الحليفة: ميقات أهل المدينة، ويسمى الآن أبيار على تبعد عن مكة (430كم2) .\nب: الجحفة ميقات أهل مصر والشام والمغرب، ويحرم الناس بجوارها من رابغ وتبعد عن مكة (201كم2) .\nت: يلملم ميقات أهل اليمن وأهل جاوة، وأهل الهند والصين، وتبعد عن مكة (80كم2) .\nث: قرن المنازل: ميقات أهل الطائف ونجد، ونجد اليمن، ونجد الحجاز، وتبعد عن مكة (80كم2) ويسمى الآن السيل الكبير.\nج: وهناك ميقات خامس يسمى (ذات عرق) ويسمى الآن الضريبة يحرم منه أهل العراق وإيران ومن جاء من جهة الشرق ويبعد عن مكة (80كم2) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:313","bookId":"umdat-ahkam","type":"section","seq":313,"chapter":"كتاب الحج","title":"219- عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال: ((يهل أهل المدينة من ذي الحليفة , وأهل الشام من الجحفة , وأهل نجد من قرن)) . قال: وبلغني أن رسول الله - صلى الله عليه وسلم - قال: ((ويهل أهل اليمن من يلملم)) .","bab":"باب المواقيت"},{"id":"umdat-ahkam:314","bookId":"umdat-ahkam","type":"section","seq":314,"chapter":"كتاب الحج","title":"220- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص150","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن رجلا قال يا رسول الله , ما يلبس المحرم من الثياب؟ قال رسول الله - صلى الله عليه وسلم -: لايلبس القميص , ولا العمائم , ولا السراويلات , ولا البرانس , ولا الخفاف , إلا أحد لا يجد نعلين فليلبس خفين وليقطعهما أسفل من الكعبين , ولا يلبس من الثياب شيئا مسه زعفران أو ورس)) .","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:315","bookId":"umdat-ahkam","type":"section","seq":315,"chapter":"كتاب الحج","title":"ص: 151","page":"ج1 ص150","text":"وللبخاري: ((ولا تنتقب المرأة. ولا تلبس القفازين)) .\nالقميص: نوع من الثياب معروف، وقد أمر النبي - صلى الله عليه وسلم - أن لايتجاوز الكعبين.\nالسراويلات: جمع «سروال» ثوب خاص بالنصف الأسفل من البدن.\nالبرانس: جمع «برنس» : كل ثوب رأسه منه ملتسق به.\nالخفاف: جمع «خف» وهو مايلبس في الرجل ويكون إلى نصف الساق.\nالورس: نبت أصفر طيب الرائحة تصبغ به الثياب.\nلاتنتقب المرأة: لاتلبس النقاب: وهو مايستر الوجه ويبقى منه خرقان تنظر منهما.\nالقفازين: هما ماتلبسه المرأة في يديها.","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:316","bookId":"umdat-ahkam","type":"section","seq":316,"chapter":"كتاب الحج","title":"221- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((سمعت رسول الله - صلى الله عليه وسلم - يخطب بعرفات: من لم يجد نعلين فليلبس الخفين , ومن لم يجد إزارا فليلبس السراويل للمحرم)) .","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:317","bookId":"umdat-ahkam","type":"section","seq":317,"chapter":"كتاب الحج","title":"222- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن تلبية رسول الله - صلى الله عليه وسلم -: لبيك اللهم لبيك , لبيك لا شريك لك لبيك , إن الحمد والنعمة لك والملك، لا شريك لك)) . قال: وكان عبد الله بن عمر يزيد فيها «لبيك لبيك , وسعديك , والخير بيديك , والرغباء إليك والعمل» .\nلبيك: منقاد لك وخاضع بين يديك، وملازم لعبادتك وطاعتك.\nسعديك: مساعدة في طاعتك بعد مساعدة\nالرغباء: الطلب والمسألة ممن بيده الخير.","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:318","bookId":"umdat-ahkam","type":"section","seq":318,"chapter":"كتاب الحج","title":"223- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا يحل لامرأة تؤمن بالله واليوم الآخر أن تسافر مسيرة يوم وليلة إلا ومعها حرمة)) .\nوفي لفظ البخاري: ((لا تسافر مسيرة يوم إلا مع ذي محرم)) .","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:319","bookId":"umdat-ahkam","type":"section","seq":319,"chapter":"كتاب الحج","title":"ص: 153","page":"ص0","text":"ذي محرم: محرم المرأة من حرم عليه نكاحها على التأبيد.","bab":"باب ما يلبس المحرم من الثياب"},{"id":"umdat-ahkam:320","bookId":"umdat-ahkam","type":"section","seq":320,"chapter":"كتاب الحج","title":"224- عن عبد الله بن معقل قال","page":"ج1 ص153","text":"عن عبد الله بن معقل قال: ((جلست إلى كعب بن عجرة. فسألته عن الفدية؟ فقال: نزلت في خاصة. وهي لكم عامة. حملت إلى رسول الله - صلى الله عليه وسلم - والقمل يتناثر على وجهي. فقال: ما كنت أرى الوجع بلغ بك ما أرى - أو ما كنت أرى الجهد بلغ بك ما أرى - أتجد شاة؟ فقلت: لا. فقال: صم ثلاثة أيام , أو أطعم ستة مساكين , لكل مسكين نصف صاع)) .\nوفي رواية: ((فأمره رسول الله - صلى الله عليه وسلم - أن يطعم فرقا بين ستة , أو يهدي شاة , أو يصوم ثلاثة أيام)) .\nماكنت أرى: ماكنت أظن.\nالجهد: المشقة.\nالفرق: مكيال يسع ثلاثة آصع نبوية.","bab":"باب الفدية"},{"id":"umdat-ahkam:321","bookId":"umdat-ahkam","type":"section","seq":321,"chapter":"كتاب الحج","title":"225- عن أبي شريح - خويلد بن عمرو - الخزاعي العدوي رضي الله عنه","page":"ج1 ص153","text":"عن أبي شريح - خويلد بن عمرو - الخزاعي العدوي رضي الله عنه: أنه قال لعمرو بن سعيد بن العاص - وهو يبعث البعوث إلى مكة - ائذن لي أيها الأمير أن أحدثك قولا قام به رسول الله - صلى الله عليه وسلم - الغد من يوم الفتح. فسمعته أذناي، ووعاه قلبي، وأبصرته عيناي , حين تكلم به: ((أنه حمد الله وأثنى عليه. ثم قال:","bab":"باب حرمة مكة"},{"id":"umdat-ahkam:322","bookId":"umdat-ahkam","type":"section","seq":322,"chapter":"كتاب الحج","title":"ص: 154","page":"ج1 ص153","text":"إن مكة حرمها الله تعالى , ولم يحرمها الناس. فلا يحل لامرئ يؤمن بالله واليوم الآخر: أن يسفك بها دما , ولا يعضد بها شجرة. فإن أحد ترخص بقتال رسول الله - صلى الله عليه وسلم - فقولوا: إن الله قد أذن لرسوله , ولم يأذن لكم. وإنما أذن لي ساعة من نهار. وقد عادت حرمتها اليوم كحرمتها بالأمس. فليبلغ الشاهد الغائب. فقيل لأبي شريح: ما قال لك؟ قال: أنا أعلم بذلك منك يا أبا شريح، إن الحرم لا يعيذ عاصيا , ولا فارا بدم ولا فارا بخربة)) .","bab":"باب حرمة مكة"},{"id":"umdat-ahkam:323","bookId":"umdat-ahkam","type":"section","seq":323,"chapter":"كتاب الحج","title":"ص: 155","page":"ج1 ص153","text":"الخربة: بالخاء المعجمة والراء المهملة. قيل: الخيانة، وقيل: البلية، وقيل: التهمة.","bab":"باب حرمة مكة"},{"id":"umdat-ahkam:324","bookId":"umdat-ahkam","type":"section","seq":324,"chapter":"كتاب الحج","title":"226- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: قال رسول الله - صلى الله عليه وسلم - يوم فتح مكة - ((لا هجرة بعد الفتح , ولكن جهاد ونية. وإذا استنفرتم فانفروا , وقال: يوم فتح مكة: إن هذا البلد حرمه الله يوم خلق الله السموات والأرض. فهو حرام بحرمة الله إلى يوم القيامة. وإنه لم يحل القتال فيه لأحد قبلي , ولم يحل لي إلا ساعة من نهار فهو حرام بحرمة الله إلى يوم القيامة. لا يعضد شوكه , ولا ينفر صيده , ولا يلتقط لقطته إلا من عرفها. ولا يختلى خلاه. فقال العباس: يا رسول الله , إلا","bab":"باب حرمة مكة"},{"id":"umdat-ahkam:325","bookId":"umdat-ahkam","type":"section","seq":325,"chapter":"كتاب الحج","title":"ص: 156","page":"ص0","text":"الإذخر. فإنه لقينهم وبيوتهم. فقال: إلا الإذخر)) . القين: الحداد.\nإذا استنفرتم فانفروا: «نفر» خرج بسرعة. يعني إذا طلب منكم الخروج بسرعة فاخرجوا كما طلب منكم\nلا يعضد شوكه: لايقطع شوكه.\nلا ينفر صيده: لايزعج من مكانه ويذعر.\nلا يختلى خلاه: «الخلا» هو الرطب من الكلأ، واختلاؤه قطعه.\nالإذخر: نبت طيب الرائحة.\nلقينهم: هو الحداد، وحاجته إليها ليوقد بها النار.","bab":"باب حرمة مكة"},{"id":"umdat-ahkam:326","bookId":"umdat-ahkam","type":"section","seq":326,"chapter":"كتاب الحج","title":"227- عن عائشة رضي الله عنها","page":"ج1 ص156","text":"عن عائشة رضي الله عنها: أن رسول الله - صلى الله عليه وسلم - قال: ((خمس من الدواب كلهن فاسق , يقتلن في الحرم: الغراب , والحدأة , والعقرب , والفأرة , والكلب العقور)) .","bab":"باب ما يجوز قتله"},{"id":"umdat-ahkam:327","bookId":"umdat-ahkam","type":"section","seq":327,"chapter":"كتاب الحج","title":"ص: 157","page":"ج1 ص156","text":"ولمسلم: ((يقتل خمس فواسق في الحل والحرم)) . الحدأة: بكسر الحاء وفتح الدال.\nفاسق: الفسق هو الخروج عن الشيء.\nالكلب العقور: العقور كل ماعقر الناس وأخافهم وعدا عليهم مثل الأسد والنمر والفهد والذئب.","bab":"باب ما يجوز قتله"},{"id":"umdat-ahkam:328","bookId":"umdat-ahkam","type":"section","seq":328,"chapter":"كتاب الحج","title":"228- عن أنس بن مالك - رضي الله عنه -","page":"ج1 ص157","text":"عن أنس بن مالك - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - دخل مكة عام الفتح , وعلى رأسه المغفر، فلما نزعه جاءه رجل فقال: ابن خطل متعلق بأستار الكعبة فقال: اقتلوه)) .\nالمغفر: هو لباس من حديد يلبسه المقاتل على رأسه وقاية له من السيف.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:329","bookId":"umdat-ahkam","type":"section","seq":329,"chapter":"كتاب الحج","title":"229- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:330","bookId":"umdat-ahkam","type":"section","seq":330,"chapter":"كتاب الحج","title":"ص: 158","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - دخل مكة من كداء , من الثنية العليا التي بالبطحاء , وخرج من الثنية السفلى)) .\nكداء: اسم مكان في أعلى مكة، يقال لها الآن ريع الحجون.\nالثنية السفلى: الثنية هي الطريق بين جبلين.\nوالمراد بها الطريق الذي يخرج من المحلة المسماة (حارة الباب) وتسمى الثنية الآن (ريع الرسام) .","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:331","bookId":"umdat-ahkam","type":"section","seq":331,"chapter":"كتاب الحج","title":"230- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((دخل رسول الله - صلى الله عليه وسلم - البيت , وأسامة بن زيد وبلال وعثمان بن طلحة , فأغلقوا عليهم الباب فلما فتحوا: كنت أول من ولج. فلقيت بلالا , فسألته: هل صلى فيه رسول الله - صلى الله عليه وسلم -؟ قال: نعم , بين العمودين اليمانيين)) .\nولج: دخل.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:332","bookId":"umdat-ahkam","type":"section","seq":332,"chapter":"كتاب الحج","title":"231- عن عمر - رضي الله عنه -","page":"ص0","text":"عن عمر - رضي الله عنه - ((أنه جاء إلى الحجر الأسود ,","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:333","bookId":"umdat-ahkam","type":"section","seq":333,"chapter":"كتاب الحج","title":"ص: 159","page":"ص0","text":"فقبله. وقال: إني لأعلم أنك حجر , لا تضر ولا تنفع , ولولا أني رأيت النبي - صلى الله عليه وسلم - يقبلك ما قبلتك)) .","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:334","bookId":"umdat-ahkam","type":"section","seq":334,"chapter":"كتاب الحج","title":"232- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((لما قدم رسول الله - صلى الله عليه وسلم - وأصحابه مكة. فقال المشركون: إنه يقدم عليكم قوم وهنتهم حمى يثرب. فأمرهم النبي - صلى الله عليه وسلم - أن يرملوا الأشواط الثلاثة , وأن يمشوا ما بين الركنين , ولم يمنعهم أن يرملوا الأشواط كلها: إلا الإبقاء عليهم)) .\nوهنتهم: أضعفتهم.\nيثرب: من أسماء المدينة في الجاهلية.\nأن يرملوا: الرمل: هو الإسراع في المشي مع تقارب الخطا.\nالركنين: الركنان هما الركن اليماني والركن الذي فيه الحجر الأسود.\nالإبقاء عليهم: الرفق بهم والشفقة عليهم.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:335","bookId":"umdat-ahkam","type":"section","seq":335,"chapter":"كتاب الحج","title":"233- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((رأيت رسول الله - صلى الله عليه وسلم - حين يقدم مكة إذا استلم الركن الأسود - أول ما يطوف - يخب ثلاثة أشواط)) .","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:336","bookId":"umdat-ahkam","type":"section","seq":336,"chapter":"كتاب الحج","title":"ص: 160","page":"ص0","text":"يخب: يرمل وهو الإسراع في المشي مع تقارب الخطا.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:337","bookId":"umdat-ahkam","type":"section","seq":337,"chapter":"كتاب الحج","title":"234- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((طاف النبي - صلى الله عليه وسلم - في حجة الوداع على بعير , يستلم الركن بمحجن)) .\nالمحجن: عصا محنية الرأس.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:338","bookId":"umdat-ahkam","type":"section","seq":338,"chapter":"كتاب الحج","title":"235- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((لم أر النبي - صلى الله عليه وسلم - يستلم من البيت إلا الركنين اليمانيين)) .\nالركنين اليمانيين: الركن اليماني، والركن الشرقي الذي فيه الحجر الأسود.","bab":"باب دخول مكة وغيره"},{"id":"umdat-ahkam:339","bookId":"umdat-ahkam","type":"section","seq":339,"chapter":"كتاب الحج","title":"باب التمتع","page":"ص0","text":"حج التمتع: هو الإحرام بالعمرة في أشهر الحج ثم الفراغ منها ثم الإحرام بالحج يوم التروية وهو يوم الثامن من ذي الحجة.","bab":"باب التمتع"},{"id":"umdat-ahkam:340","bookId":"umdat-ahkam","type":"section","seq":340,"chapter":"كتاب الحج","title":"236- عن أبي جمرة نصر بن عمران الضبعي","page":"ج1 ص160","text":"عن أبي جمرة نصر بن عمران الضبعي، قال: ((سألت ابن","bab":"باب التمتع"},{"id":"umdat-ahkam:341","bookId":"umdat-ahkam","type":"section","seq":341,"chapter":"كتاب الحج","title":"ص: 161","page":"ج1 ص160","text":"عباس عن المتعة؟ فأمرني بها , وسألته عن الهدي؟ فقال: فيه جزور , أو بقرة , أو شاة , أو شرك في دم قال: وكان ناس كرهوها , فنمت. فرأيت في المنام: كأن إنسانا ينادي: حج مبرور , ومتعة متقبلة. فأتيت ابن عباس فحدثته. فقال: الله أكبر سنة أبي القاسم - صلى الله عليه وسلم -)) .\nالهدي: هو مايهدى إلى الحرم من حيوان وغيره.\nالجزور: البعير ذكرا كان أوأنثى.\nشرك في دم: اشتراك سبعة أشخاص أوأقل في ذبيحة من البقر أوالإبل.","bab":"باب التمتع"},{"id":"umdat-ahkam:342","bookId":"umdat-ahkam","type":"section","seq":342,"chapter":"كتاب الحج","title":"237- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((تمتع رسول الله - صلى الله عليه وسلم - في حجة الوداع بالعمرة إلى الحج وأهدى. فساق معه الهدي من ذي الحليفة. وبدأ رسول الله - صلى الله عليه وسلم - وأهل بالعمرة , ثم أهل بالحج , فتمتع الناس مع رسول الله - صلى الله عليه وسلم - فأهل بالعمرة إلى الحج , فكان من الناس من أهدى , فساق الهدي من الحليفة. ومنهم من","bab":"باب التمتع"},{"id":"umdat-ahkam:343","bookId":"umdat-ahkam","type":"section","seq":343,"chapter":"كتاب الحج","title":"ص: 162","page":"ص0","text":"لم يهد فلما قدم رسول الله - صلى الله عليه وسلم - قال للناس: من كان منكم أهدى , فإنه لا يحل من شيء حرم منه حتى يقضي حجه. ومن لم يكن أهدى فليطف بالبيت وبالصفا والمروة , وليقصر وليحلل , ثم ليهل بالحج وليهد , فمن لم يجد هديا فليصم ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله فطاف رسول الله - صلى الله عليه وسلم - حين قدم مكة. واستلم الركن أول شيء , ثم خب ثلاثة أطواف من السبع , ومشى أربعة , وركع حين قضى طوافه بالبيت عند المقام ركعتين , ثم انصرف فأتى الصفا , وطاف بالصفا والمروة سبعة أطواف , ثم لم يحلل من شيء حرم منه حتى قضى حجه , ونحر هديه يوم النحر. وأفاض فطاف بالبيت , ثم حل من كل شيء حرم منه , وفعل مثل ما فعل رسول الله - صلى الله عليه وسلم -: من أهدى وساق الهدي من\nالناس)) .","bab":"باب التمتع"},{"id":"umdat-ahkam:344","bookId":"umdat-ahkam","type":"section","seq":344,"chapter":"كتاب الحج","title":"238- عن حفصة زوج النبي - صلى الله عليه وسلم - أنها قالت","page":"ص0","text":"عن حفصة زوج النبي - صلى الله عليه وسلم - أنها قالت: ((يا رسول الله , ما شأن الناس حلوا من العمرة ولم تحل أنت من عمرتك فقال: إني لبدت رأسي , وقلدت هديي , فلا أحل حتى أنحر)) .\nلبدت رأسي: التلبيد: هو وضع شيء من الأدهان على الشعر حتى يكون هابطا.","bab":"باب التمتع"},{"id":"umdat-ahkam:345","bookId":"umdat-ahkam","type":"section","seq":345,"chapter":"كتاب الحج","title":"239- عن عمران بن حصين قال","page":"ص0","text":"عن عمران بن حصين قال: ((أنزلت آية المتعة في كتاب الله تعالى. ففعلناها مع رسول الله - صلى الله عليه وسلم - ولم ينزل قرآن يحرمها , ولم ينه عنها حتى مات. قال رجل برأيه ما شاء)) قال البخاري \" يقال: «إنه عمر» .\nولمسلم ((نزلت آية المتعة - يعني متعة الحج - وأمرنا بها","bab":"باب التمتع"},{"id":"umdat-ahkam:346","bookId":"umdat-ahkam","type":"section","seq":346,"chapter":"كتاب الحج","title":"ص: 164","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - ثم لم تنزل آية تنسخ آية متعة الحج ولم ينه عنها رسول الله - صلى الله عليه وسلم - حتى مات)) ولهما بمعناه.","bab":"باب التمتع"},{"id":"umdat-ahkam:347","bookId":"umdat-ahkam","type":"section","seq":347,"chapter":"كتاب الحج","title":"باب الهدي","page":"ص0","text":"الهدي: ماأهدي إلى البيت الحرام من الإبل والبقر والغنم وغيرها.","bab":"باب الهدي"},{"id":"umdat-ahkam:348","bookId":"umdat-ahkam","type":"section","seq":348,"chapter":"كتاب الحج","title":"240- عن عائشة رضي الله عنها قالت","page":"ج1 ص164","text":"عن عائشة رضي الله عنها قالت: ((فتلت قلائد هدي رسول الله - صلى الله عليه وسلم - ثم أشعرتها وقلدها - أو قلدتها - ثم بعث بها إلى البيت. وأقام بالمدينة , فما حرم عليه شيء كان له حلا)) .\nقلائد: جمع «قلادة» وهي مايحاط به العنق من خيوط أوحديد أوغير ذلك لتعلم أنها هدي فتحترم.\nأشعرتها: الإشعار: هو أن يشق أحد جنبي سنام البدنة أوالبقرة حتي يسيل دمها ليعلم الناس أنها مهداة للحرم فلايعترضوها.","bab":"باب الهدي"},{"id":"umdat-ahkam:349","bookId":"umdat-ahkam","type":"section","seq":349,"chapter":"كتاب الحج","title":"241- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((أهدى رسول الله - صلى الله عليه وسلم - مرة غنما)) .","bab":"باب الهدي"},{"id":"umdat-ahkam:350","bookId":"umdat-ahkam","type":"section","seq":350,"chapter":"كتاب الحج","title":"242- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: ((أن نبي الله - صلى الله عليه وسلم - رأى رجلا يسوق بدنة , فقال: اركبها. قال: إنها بدنة. قال اركبها. فرأيته راكبها , يساير النبي - صلى الله عليه وسلم -)) .\nوفي لفظ قال في الثانية , أو الثالثة: ((اركبها. ويلك , أو ويحك)) .\nبدنة: تطلق على الإبل والبقر، لعظم أبدانها وضخامتها.","bab":"باب الهدي"},{"id":"umdat-ahkam:351","bookId":"umdat-ahkam","type":"section","seq":351,"chapter":"كتاب الحج","title":"243- عن علي بن أبي طالب - رضي الله عنه - قال","page":"ص0","text":"عن علي بن أبي طالب - رضي الله عنه - قال: ((أمرني رسول الله - صلى الله عليه وسلم - أن أقوم على بدنه , وأن أتصدق بلحمها وجلودها وأجلتها , وأن لا أعطي الجزار منها شيئا)) .\nوقال: نحن نعطيه من عندنا.\nأجلتها: جمع «جل» وهو مايطرح على ظهر البعير من كساء ونحوه.","bab":"باب الهدي"},{"id":"umdat-ahkam:352","bookId":"umdat-ahkam","type":"section","seq":352,"chapter":"كتاب الحج","title":"244- عن زياد بن جبير قال","page":"ص0","text":"عن زياد بن جبير قال: ((رأيت ابن عمر أتى على رجل","bab":"باب الهدي"},{"id":"umdat-ahkam:353","bookId":"umdat-ahkam","type":"section","seq":353,"chapter":"كتاب الحج","title":"ص: 166","page":"ص0","text":"قد أناخ بدنته , فنحرها. فقال ابعثها قياما مقيدة سنة محمد - صلى الله عليه وسلم -)) .\nنحرها: ذبحها في لبتها.\nقياما مقيدة: قائمة مقيدة الرجل.","bab":"باب الهدي"},{"id":"umdat-ahkam:354","bookId":"umdat-ahkam","type":"section","seq":354,"chapter":"كتاب الحج","title":"245- عن عبد الله بن حنين","page":"ج1 ص166","text":"عن عبد الله بن حنين: ((أن عبد الله بن عباس والمسور بن مخرمة اختلفا بالأبواء. فقال ابن عباس: يغسل المحرم رأسه. وقال المسور: لا يغسل رأسه. قال: فأرسلني ابن عباس إلى أبي أيوب الأنصاري - رضي الله عنه -. فوجدته يغتسل بين القرنين , وهو يستر بثوب. فسلمت عليه. فقال: من هذا؟ فقلت: أنا عبد الله بن حنين , أرسلني إليك ابن عباس , يسألك: كيف كان رسول الله - صلى الله عليه وسلم - يغسل رأسه وهو محرم؟ فوضع أبو أيوب يده على الثوب , فطأطأه , حتى بدا لي رأسه. ثم قال لإنسان يصب عليه الماء: اصبب , فصب على رأسه. ثم حرك رأسه بيديه , فأقبل بهما وأدبر. ثم قال: هكذا رأيته - صلى الله عليه وسلم - يغتسل)) .","bab":"باب الغسل للمحرم"},{"id":"umdat-ahkam:355","bookId":"umdat-ahkam","type":"section","seq":355,"chapter":"كتاب الحج","title":"ص: 167","page":"ج1 ص166","text":"وفي رواية \" فقال المسور لابن عباس: لا أماريك أبدا \".\nالقرنان: العمودان اللذان تشد فيهما الخشبة التي تعلق عليها بكرة البئر. أه\nالأبواء: موضع بين مكة والمدينة.\nطأطأه: أزاله عن رأسه.\nأماريك: أجادلك.","bab":"باب الغسل للمحرم"},{"id":"umdat-ahkam:356","bookId":"umdat-ahkam","type":"section","seq":356,"chapter":"كتاب الحج","title":"246- عن جابر بن عبد الله رضي الله عنهما قال","page":"ج1 ص167","text":"عن جابر بن عبد الله رضي الله عنهما قال ((أهل النبي - صلى الله عليه وسلم - وأصحابه بالحج وليس مع أحد منهم هدي غير النبي - صلى الله عليه وسلم - وطلحة , وقدم علي - رضي الله عنه - من اليمن. فقال: أهللت بما أهل به النبي - صلى الله عليه وسلم - فأمر النبي - صلى الله عليه وسلم - أصحابه: أن يجعلوها عمرة , فيطوفوا ثم يقصروا ويحلوا , إلا من كان معه الهدي فقالوا: ننطلق إلى «منى» وذكر أحدنا يقطر؟ فبلغ ذلك النبي - صلى الله عليه وسلم - فقال: لو استقبلت من أمري ما استدبرت ما أهديت , ولولا أن معي الهدي لأحللت. وحاضت عائشة. فنسكت المناسك كلها , غير أنها لم تطف","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:357","bookId":"umdat-ahkam","type":"section","seq":357,"chapter":"كتاب الحج","title":"ص: 168","page":"ج1 ص167","text":"بالبيت. فلما طهرت وطافت بالبيت قالت: يا رسول الله , ينطلقون بحج وعمرة , وأنطلق بحج فأمر عبد الرحمن بن أبي بكر: أن يخرج معها إلى التنعيم فاعتمرت بعد الحج)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:358","bookId":"umdat-ahkam","type":"section","seq":358,"chapter":"كتاب الحج","title":"247- عن جابر - رضي الله عنه - قال","page":"ص0","text":"عن جابر - رضي الله عنه - قال: ((قدمنا مع رسول الله - صلى الله عليه وسلم - ونحن نقول: لبيك بالحج. فأمرنا رسول الله - صلى الله عليه وسلم - فجعلناها عمرة)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:359","bookId":"umdat-ahkam","type":"section","seq":359,"chapter":"كتاب الحج","title":"248- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((قدم رسول الله - صلى الله عليه وسلم - وأصحابه صبيحة رابعة. فأمرهم أن يجعلوها عمرة. فقالوا: يا رسول الله , أي الحل؟ قال: الحل كله)) .\nصبيحة رابعة: صبيحة الرابع من ذي الحجة.","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:360","bookId":"umdat-ahkam","type":"section","seq":360,"chapter":"كتاب الحج","title":"249- عن عروة بن الزبير قال","page":"ص0","text":"عن عروة بن الزبير قال: ((سئل أسامة بن زيد - وأنا جالس - كيف كان رسول الله - صلى الله عليه وسلم - يسير حين دفع؟ قال: كان يسير العنق. فإذا وجد فجوة نص)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:361","bookId":"umdat-ahkam","type":"section","seq":361,"chapter":"كتاب الحج","title":"ص: 170","page":"ص0","text":"العنق: انبساط السير، و «النص» فوق ذلك. أه\nفجوة: مكان متسع.","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:362","bookId":"umdat-ahkam","type":"section","seq":362,"chapter":"كتاب الحج","title":"250- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - وقف في حجة الوداع. فجعلوا يسألونه. فقال: رجل لم أشعر , فحلقت قبل أن أذبح؟ قال. اذبح ولا حرج. وجاء آخر , فقال: لم أشعر , فنحرت قبل أن أرمي؟ قال: ارم ولا حرج. فما سئل يومئذ عن شيء قدم ولا أخر إلا قال: افعل ولا حرج)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:363","bookId":"umdat-ahkam","type":"section","seq":363,"chapter":"كتاب الحج","title":"251- عن عبد الرحمن بن يزيد النخعي","page":"ص0","text":"عن عبد الرحمن بن يزيد النخعي: ((أنه حج مع ابن مسعود. فرآه رمى الجمرة الكبرى بسبع حصيات فجعل البيت عن يساره , ومنى عن يمينه. ثم قال: هذا مقام الذي أنزلت عليه سورة البقرة - صلى الله عليه وسلم -)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:364","bookId":"umdat-ahkam","type":"section","seq":364,"chapter":"كتاب الحج","title":"252- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: أن رسول الله - صلى الله عليه وسلم - قال: ((اللهم ارحم المحلقين. قالوا: والمقصرين يا رسول الله. قال: اللهم ارحم المحلقين. قالوا والمقصرين يا رسول الله. قال: والمقصرين)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:365","bookId":"umdat-ahkam","type":"section","seq":365,"chapter":"كتاب الحج","title":"253- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((حججنا مع النبي - صلى الله عليه وسلم - فأفضنا يوم النحر. فحاضت صفية. فأراد النبي - صلى الله عليه وسلم - منها ما يريد الرجل من أهله. فقلت: يا رسول الله , إنها حائض. قال: أحابستنا هي؟ قالوا: يا رسول الله , إنها قد أفاضت يوم النحر قال: اخرجوا)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:366","bookId":"umdat-ahkam","type":"section","seq":366,"chapter":"كتاب الحج","title":"ص: 172","page":"ص0","text":"وفي لفظ: قال النبي - صلى الله عليه وسلم -: ((عقرى , حلقى. أطافت يوم النحر؟ قيل: نعم. قال: فانفري)) .\nأفاضت: طافت طواف الإفاضة.\nيوم النحر: يوم العيد العاشر من ذي الحجة.\nعقرى , حلقى: هو في الحقيقة دعاء بالإصابة بالوجع وحلق الشعر، ولكن ذلك غير مقصود فهو مما يجري على ألسنة العرب من غير قصد ونظيره: تربت يداه وثكلتك أمك.\nانفري: اخرجي.","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:367","bookId":"umdat-ahkam","type":"section","seq":367,"chapter":"كتاب الحج","title":"254- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((أمر الناس أن يكون آخر عهدهم بالبيت , إلا أنه خفف عن المرأة الحائض)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:368","bookId":"umdat-ahkam","type":"section","seq":368,"chapter":"كتاب الحج","title":"255- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((استأذن العباس بن عبد المطلب رسول الله - صلى الله عليه وسلم -: أن يبيت بمكة ليالي منى , من أجل سقايته فأذن له)) .\nسقايته: سقاية الحجيج بالماء.","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:369","bookId":"umdat-ahkam","type":"section","seq":369,"chapter":"كتاب الحج","title":"256- وعنه - أي عن ابن عمر - قال","page":"ص0","text":"وعنه - أي عن ابن عمر - قال: ((جمع النبي - صلى الله عليه وسلم - بين المغرب والعشاء «بجمع» , لكل واحدة منهما إقامة. ولم يسبح بينهما , ولا على إثر واحدة منهما)) .","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:370","bookId":"umdat-ahkam","type":"section","seq":370,"chapter":"كتاب الحج","title":"ص: 173","page":"ص0","text":"جمع: مزدلفة.\nولم يسبح بينهما: لم يصل صلاة النافلة.","bab":"باب فسخ الحج إلى العمرة"},{"id":"umdat-ahkam:371","bookId":"umdat-ahkam","type":"section","seq":371,"chapter":"كتاب الحج","title":"257- عن أبي قتادة الأنصاري","page":"ج1 ص173","text":"عن أبي قتادة الأنصاري: ((أن رسول الله - صلى الله عليه وسلم - خرج حاجا. فخرجوا معه. فصرف طائفة منهم - فيهم أبو قتادة - وقال: خذوا ساحل البحر , حتى نلتقي. فأخذوا ساحل البحر فلما انصرفوا أحرموا كلهم , إلا أبا قتادة , فلم يحرم. فبينما هم يسيرون إذ رأوا حمر وحش. فحمل أبو قتادة على الحمر. فعقر منها أتانا. فنزلنا فأكلنا من لحمها. ثم قلنا: أنأكل لحم صيد , ونحن محرمون؟ فحملنا ما بقي من لحمها فأدركنا رسول الله - صلى الله عليه وسلم -. فسألناه عن ذلك؟ فقال: منكم أحد أمره أن يحمل عليها , أو أشار إليها؟ قالوا: لا. قال: فكلوا ما بقي من لحمها)) .\nوفي رواية: ((قال: هل معكم منه شيء؟ فقلت: نعم. فناولته العضد , فأكل منها)) .\nخرج حاجا: معتمرا عمرة الحديبية.\nحمر وحش: الحمير الوحشية.\nالأتان: أنثى الحمار.","bab":"باب المحرم يأكل من صيد الحلال"},{"id":"umdat-ahkam:372","bookId":"umdat-ahkam","type":"section","seq":372,"chapter":"كتاب الحج","title":"258- عن الصعب بن جثامة الليثي - رضي الله عنه -","page":"ج1 ص173","text":"عن الصعب بن جثامة الليثي - رضي الله عنه - ((أنه أهدى إلى النبي - صلى الله عليه وسلم - حمارا وحشيا , وهو بالأبواء أو بودان - فرده عليه.","bab":"باب المحرم يأكل من صيد الحلال"},{"id":"umdat-ahkam:373","bookId":"umdat-ahkam","type":"section","seq":373,"chapter":"كتاب الحج","title":"ص: 174","page":"ج1 ص173","text":"فلما رأى ما في وجهي , قال: إنا لم نرده عليك إلا أنا حرم)) .\nوفي لفظ لمسلم «رجل حمار» وفي لفظ «شق حمار» وفي لفظ «عجز حمار» .","bab":"باب المحرم يأكل من صيد الحلال"},{"id":"umdat-ahkam:374","bookId":"umdat-ahkam","type":"section","seq":374,"chapter":"كتاب البيوع","title":"259- عن عبد الله بن عمر رضي الله عنهما عن رسول الله - صلى الله عليه وسلم - أنه قال","page":"ج1 ص175","text":"عن عبد الله بن عمر رضي الله عنهما عن رسول الله - صلى الله عليه وسلم - أنه قال: ((إذا تبايع الرجلان , فكل واحد منهما بالخيار ما لم يتفرقا وكانا جميعا , أو يخير أحدهما الآخر. فتبايعا على ذلك. فقد وجب البيع)) . وما في معناه من حديث"},{"id":"umdat-ahkam:375","bookId":"umdat-ahkam","type":"section","seq":375,"chapter":"كتاب البيوع","title":"260- حكيم بن حزام رضي الله عنه قال","page":"ص0","text":"حكيم بن حزام رضي الله عنه قال: قال رسول الله - صلى الله عليه وسلم -: ((البيعان بالخيار ما لم يتفرقا - أو قال: حتى يتفرقا - فإن صدقا وبينا بورك لهما في بيعهما. وإن كتما وكذبا محقت بركة بيعهما)) ."},{"id":"umdat-ahkam:376","bookId":"umdat-ahkam","type":"section","seq":376,"chapter":"كتاب البيوع","title":"ص: 176","page":"ص0","text":"الخيار: طلب خير الأمرين من إمضاء البيع أورده.\nالبيعان: البائع والمشتري.\nمحقت: ذهبت وزالت."},{"id":"umdat-ahkam:377","bookId":"umdat-ahkam","type":"section","seq":377,"chapter":"كتاب البيوع","title":"261- عن أبي سعيد الخدري - رضي الله عنه -","page":"ج1 ص176","text":"عن أبي سعيد الخدري - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - نهى عن المنابذة - وهي طرح الرجل ثوبه بالبيع إلى الرجل قبل أن يقلبه , أو ينظر إليه - ونهى عن الملامسة. والملامسة: لمس الثوب ولا ينظر إليه)) .","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:378","bookId":"umdat-ahkam","type":"section","seq":378,"chapter":"كتاب البيوع","title":"262- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((لا تلقوا الركبان , ولا يبع بعضكم على بيع بعض. ولا تناجشوا. ولا يبع حاضر لباد. ولا تصروا الغنم. ومن ابتاعها فهو بخير النظرين , بعد أن يحلبها. وإن رضيها أمسكها , وإن سخطها ردها وصاعا من تمر)) .","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:379","bookId":"umdat-ahkam","type":"section","seq":379,"chapter":"كتاب البيوع","title":"ص: 177","page":"ص0","text":"وفي لفظ: ((هو بالخيار ثلاثا)) .\nلا تلقوا الركبان: لاتستقبلوا القادمين بسلعهم قبل وصولها إلى السوق.\nولا تناجشوا: النجش: هو أن يزيد الإنسان في ثمن السلعة أويمدحها وليس له رغبة في شرائها، ولكن يريد خداع غيره.\nولا يبع حاضر لباد: الحاضر: هو البلدي المقيم، والبادي: نسبة إلى البادية، والمراد القادم لبيع سلعته\nولا تصروا الغنم: التصرية: هي حبس اللبن في ضروع البهائم حتى تظهر ممتلئة باللبن فيغتر بها المشتري","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:380","bookId":"umdat-ahkam","type":"section","seq":380,"chapter":"كتاب البيوع","title":"263- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما ((أن رسول الله - صلى الله عليه وسلم - نهى عن بيع حبل الحبلة. وكان بيعا يتبايعه أهل الجاهلية، وكان الرجل يبتاع الجزور إلى أن تنتج الناقة. ثم تنتج التي في بطنها. قيل: إنه كان يبيع الشارف - وهي الكبيرة المسنة - بنتاج الجنين الذي في بطن ناقته)) .\nحبل الحبلة: جنين الحيوان في بطن أمه.\nالجزور: البعير ذكرا كان أوأنثى.\nتنتج: تلد.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:381","bookId":"umdat-ahkam","type":"section","seq":381,"chapter":"كتاب البيوع","title":"264- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - نهى عن بيع","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:382","bookId":"umdat-ahkam","type":"section","seq":382,"chapter":"كتاب البيوع","title":"ص: 178","page":"ص0","text":"الثمرة حتى يبدو صلاحها. نهى البائع والمشتري)) .\nيبدو: يظهر.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:383","bookId":"umdat-ahkam","type":"section","seq":383,"chapter":"كتاب البيوع","title":"265- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - نهى عن بيع الثمار حتى تزهي قيل: وما تزهي؟ قال: حتى تحمر. قال: أرأيت إن منع الله الثمرة , بم يستحل أحدكم مال أخيه؟)) .","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:384","bookId":"umdat-ahkam","type":"section","seq":384,"chapter":"كتاب البيوع","title":"266- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((نهى رسول الله - صلى الله عليه وسلم - أن تتلقى الركبان , وأن يبيع حاضر لباد، قال: فقلت لابن عباس: ما قوله حاضر لباد؟ قال: لا يكون له سمسارا)) .","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:385","bookId":"umdat-ahkam","type":"section","seq":385,"chapter":"كتاب البيوع","title":"ص: 179","page":"ص0","text":"سمسارا: السمسار هو متولي البيع والشراء لغيره.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:386","bookId":"umdat-ahkam","type":"section","seq":386,"chapter":"كتاب البيوع","title":"267- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((نهى رسول الله - صلى الله عليه وسلم - عن المزابنة: أن يبيع ثمر حائطه , إن كان نخلا: بتمر كيلا. وإن كان كرما: أن يبيعه بزبيب كيلا , أو كان زرعا: أن يبيعه بكيل طعام. نهى عن ذلك كله)) .\nالمزابنة: هي بيع شيء لايعلم كيله أووزنه أوعدده بشيء من جنسه.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:387","bookId":"umdat-ahkam","type":"section","seq":387,"chapter":"كتاب البيوع","title":"268- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((نهى النبي - صلى الله عليه وسلم - عن المخابرة والمحاقلة , وعن المزابنة وعن بيع الثمرة حتى يبدو صلاحها , وأن لا تباع إلا بالدينار والدرهم , إلا العرايا))","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:388","bookId":"umdat-ahkam","type":"section","seq":388,"chapter":"كتاب البيوع","title":"ص: 180","page":"ص0","text":"المحاقلة: بيع الحنطة في سنبلها بحنطة. أه\nالمخابرة: قال النووي: هي المعاملة على الأرض ببعض مايخرج من الأرض من الزرع كالثلث أو الربع أوغير ذلك من الأجزاء المعلومة لكن يكون البذر من العامل بخلاف المزارعة التي يكون البذر فيها من صاحب الأرض\nالمحاقلة: بيع الحنطة في سنبلها بحنطة صافية من التبن.\nالعرايا: سيأتي تفسيرها في موضعها.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:389","bookId":"umdat-ahkam","type":"section","seq":389,"chapter":"كتاب البيوع","title":"269- عن أبي مسعود الأنصاري - رضي الله عنه -","page":"ص0","text":"عن أبي مسعود الأنصاري - رضي الله عنه - ((أن رسول الله - صلى الله عليه وسلم - نهى عن ثمن الكلب , ومهر البغي , وحلوان الكاهن)) .\nمهر البغي: هو ماتأخذه المرأة الزانية في مقابل الزنا.\nحلوان الكاهن: الكاهن: هو الذي يدعي علم الأشياء المغيبة المستقبلة، وحلوانه: مايعطاه من المال مقابل دجله وكذبه.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:390","bookId":"umdat-ahkam","type":"section","seq":390,"chapter":"كتاب البيوع","title":"270- عن رافع بن خديج - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن رافع بن خديج - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((ثمن الكلب خبيث. ومهر البغي خبيث , وكسب الحجام خبيث)) .","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:391","bookId":"umdat-ahkam","type":"section","seq":391,"chapter":"كتاب البيوع","title":"ص: 181","page":"ص0","text":"الحجام: هو من يمارس مهنة الحجامة، وهي امتصاص الدم من تحت الجلد.","bab":"باب مانهي عنه من البيوع"},{"id":"umdat-ahkam:392","bookId":"umdat-ahkam","type":"section","seq":392,"chapter":"كتاب البيوع","title":"271- عن زيد بن ثابت - رضي الله عنه -","page":"ج1 ص181","text":"عن زيد بن ثابت - رضي الله عنه - ((أن رسول الله - صلى الله عليه وسلم - رخص لصاحب العرية: أن يبيعها بخرصها))\nولمسلم: ((بخرصها تمرا , يأكلونها رطبا)) .\nالعرية: هي بيع الرطب على رؤوس النخل، بقدر كيله من التمر.\nبخرصها: الخرص: الظن والتخمين.","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:393","bookId":"umdat-ahkam","type":"section","seq":393,"chapter":"كتاب البيوع","title":"272- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - رخص في بيع العرايا في خمسة أوسق أو دون خمسة أوسق)) .\nأوسق: جمع «وسق» ومقداره ستون صاعا نبويا. والخمسة أوسق ثلاثمائة صاع.","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:394","bookId":"umdat-ahkam","type":"section","seq":394,"chapter":"كتاب البيوع","title":"273- عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:395","bookId":"umdat-ahkam","type":"section","seq":395,"chapter":"كتاب البيوع","title":"ص: 182","page":"ص0","text":"قال: ((من باع نخلا قد أبرت فثمرها للبائع , إلا أن يشترط المبتاع)) .\nولمسلم ((ومن ابتاع عبدا فماله للذي باعه إلا أن يشترط المبتاع)) .\nأبرت: لقحت.\nالمبتاع: المشتري.","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:396","bookId":"umdat-ahkam","type":"section","seq":396,"chapter":"كتاب البيوع","title":"274- عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال: ((من ابتاع طعاما فلا يبعه حتى يستوفيه)) وفي لفظ: ((حتى يقبضه)) .\nوعن ابن عباس مثله.","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:397","bookId":"umdat-ahkam","type":"section","seq":397,"chapter":"كتاب البيوع","title":"275- عن جابر بن عبد الله رضي الله عنهما أنه سمع","page":"ج1 ص182","text":"عن جابر بن عبد الله رضي الله عنهما أنه سمع","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:398","bookId":"umdat-ahkam","type":"section","seq":398,"chapter":"كتاب البيوع","title":"ص: 183","page":"ج1 ص182","text":"رسول الله - صلى الله عليه وسلم - يقول عام الفتح: ((إن الله ورسوله حرم بيع الخمر والميتة والخنزير والأصنام. فقيل: يا رسول الله , أرأيت شحوم الميتة؟ فإنه يطلى بها السفن , ويدهن بها الجلود. ويستصبح بها الناس. فقال: لا، هو حرام. ثم قال رسول الله - صلى الله عليه وسلم - عند ذلك: قاتل الله اليهود. إن الله لما حرم عليهم شحومها، جملوه ثم باعوه فأكلوا ثمنه)) .\nجملوه: أذابوه.\nيستصبح: يستضيء.","bab":"باب العرايا وغير ذلك"},{"id":"umdat-ahkam:399","bookId":"umdat-ahkam","type":"section","seq":399,"chapter":"كتاب البيوع","title":"باب السلم","page":"ص0","text":"السلم لغة: السلف.\nوشرعا: هو بيع موصوف في الذمة بثمن عاجل.","bab":"باب السلم"},{"id":"umdat-ahkam:400","bookId":"umdat-ahkam","type":"section","seq":400,"chapter":"كتاب البيوع","title":"276- عن عبد الله بن عباس رضي الله عنهما قال","page":"ج1 ص183","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((قدم رسول الله - صلى الله عليه وسلم - المدينة , وهم يسلفون في الثمار: السنة","bab":"باب السلم"},{"id":"umdat-ahkam:401","bookId":"umdat-ahkam","type":"section","seq":401,"chapter":"كتاب البيوع","title":"ص: 184","page":"ج1 ص183","text":"والسنتين والثلاث. فقال: من أسلف في شيء فليسلف في كيل معلوم , ووزن معلوم , إلى أجل معلوم)) .","bab":"باب السلم"},{"id":"umdat-ahkam:402","bookId":"umdat-ahkam","type":"section","seq":402,"chapter":"كتاب البيوع","title":"277- عن عائشة رضي الله عنها قالت","page":"ج1 ص184","text":"عن عائشة رضي الله عنها قالت: ((جاءتني بريرة: فقالت: كاتبت أهلي على تسع أواق , في كل عام أوقية. فأعينيني. فقلت: إن أحب أهلك أن أعدها لهم , وولاؤك لي فعلت. فذهبت بريرة إلى أهلها , فقالت: لهم. فأبوا عليها. فجاءت من عندهم ورسول الله - صلى الله عليه وسلم - جالس. فقالت: إني عرضت ذلك على أهلي , فأبوا إلا أن يكون لهم الولاء. فأخبرت عائشة النبي - صلى الله عليه وسلم -. فقال: خذيها واشترطي لهم الولاء. فإنما الولاء لمن أعتق. ففعلت عائشة. ثم قام رسول الله - صلى الله عليه وسلم - في الناس , فحمد الله وأثنى عليه. ثم قال: أما بعد. فما بال رجال يشترطون شروطا ليست في كتاب الله؟ كل شرط ليس في كتاب الله فهو باطل وإن","bab":"باب الشروط في البيع"},{"id":"umdat-ahkam:403","bookId":"umdat-ahkam","type":"section","seq":403,"chapter":"كتاب البيوع","title":"ص: 185","page":"ج1 ص184","text":"كان مائة شرط. قضاء الله أحق. وشرط الله أوثق. وإنما الولاء لمن أعتق)) .\nكاتبت أهلي: اشتريت نفسي من أسيادي.\nوولاؤك لي: الولاء هو النصرة لكن خص في الشرع بالعتق الذي هو تحرير الرقبة وتخليصها من الرق، ويحصل بالولاء التوارث والتناصر والتقارب.","bab":"باب الشروط في البيع"},{"id":"umdat-ahkam:404","bookId":"umdat-ahkam","type":"section","seq":404,"chapter":"كتاب البيوع","title":"278- عن جابر بن عبد الله رضي الله عنهما","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما ((أنه كان يسير على جمل فأعيا , فأراد أن يسيبه. فلحقني النبي - صلى الله عليه وسلم - فدعا لي , وضربه. فسار سيرا لم يسر مثله. ثم قال: بعنيه بوقية. قلت: لا. ثم قال: بعنيه. فبعته بأوقية. واستثنيت حملانه إلى أهلي. فلما بلغت: أتيته بالجمل. فنقدني ثمنه. ثم رجعت. فأرسل في إثري. فقال: أتراني ماكستك لآخذ جملك؟ خذ جملك ودراهمك. فهو لك))\nأعيا: تعب.\nيسيبه: يطلقه على وجهه.\nحملانه إلى أهلي: أي حملي إلى أهلي.\nأتراني: أتظنني.\nماكستك: المماكسة المكالمة لطلب النقص في الثمن.","bab":"باب الشروط في البيع"},{"id":"umdat-ahkam:405","bookId":"umdat-ahkam","type":"section","seq":405,"chapter":"كتاب البيوع","title":"279- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((نهى رسول الله - صلى الله عليه وسلم","bab":"باب الشروط في البيع"},{"id":"umdat-ahkam:406","bookId":"umdat-ahkam","type":"section","seq":406,"chapter":"كتاب البيوع","title":"ص: 186","page":"ص0","text":"أن يبيع حاضر لباد. ولا تناجشوا ولا يبع الرجل على بيع أخيه. ولا يخطب على خطبته. ولا تسأل المرأة طلاق أختها لتكفئ ما في صحفتها))","bab":"باب الشروط في البيع"},{"id":"umdat-ahkam:407","bookId":"umdat-ahkam","type":"section","seq":407,"chapter":"كتاب البيوع","title":"280- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ج1 ص186","text":"عن عمر بن الخطاب - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((الذهب بالورق ربا , إلا هاء وهاء، والبر بالبر ربا , إلا هاء وهاء. والشعير بالشعير ربا , إلا هاء وهاء)) .\nالورق: الفضة.\nإلا هاء وهاء: معناه التقابض.","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:408","bookId":"umdat-ahkam","type":"section","seq":408,"chapter":"كتاب البيوع","title":"281- عن أبي سعيد الخدري - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((لا تبيعوا الذهب بالذهب إلا مثلا بمثل. ولا تشفوا بعضها على بعض. ولا تبيعوا الورق بالورق إلا مثلا بمثل. ولا تشفوا بعضها على بعض. ولا تبيعوا منها غائبا بناجز)) .\nوفي لفظ ((إلا يدا بيد)) .\nوفي لفظ ((إلا وزنا بوزن , مثلا بمثل","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:409","bookId":"umdat-ahkam","type":"section","seq":409,"chapter":"كتاب البيوع","title":"ص: 187","page":"ص0","text":"سواء بسواء)) .\nلا تشفوا بعضها على بعض: لاتفضلوا بعضها على بعض.","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:410","bookId":"umdat-ahkam","type":"section","seq":410,"chapter":"كتاب البيوع","title":"282- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: ((جاء بلال إلى رسول الله - صلى الله عليه وسلم - بتمر برني فقال له النبي - صلى الله عليه وسلم -: من أين لك هذا؟ قال بلال: كان عندنا تمر رديء , فبعت منه صاعين بصاع ليطعم النبي - صلى الله عليه وسلم -. فقال النبي - صلى الله عليه وسلم - عند ذلك: أوه , أوه , عين الربا , عين الربا , لا تفعل. ولكن إذا أردت أن تشتري فبع التمر ببيع آخر. ثم اشتر به)) .\nبرني: نوع جيد من تمر المدينة.\nأوه , أوه: كلمة يؤتى بها للتوجع.","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:411","bookId":"umdat-ahkam","type":"section","seq":411,"chapter":"كتاب البيوع","title":"283- عن أبي المنهال قال","page":"ص0","text":"عن أبي المنهال قال: ((سألت البراء بن عازب وزيد بن أرقم , عن الصرف؟ فكل واحد يقول: هذا","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:412","bookId":"umdat-ahkam","type":"section","seq":412,"chapter":"كتاب البيوع","title":"ص: 188","page":"ص0","text":"خير مني. وكلاهما يقول: نهى رسول الله - صلى الله عليه وسلم - عن بيع الذهب بالورق دينا)) .","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:413","bookId":"umdat-ahkam","type":"section","seq":413,"chapter":"كتاب البيوع","title":"284- عن أبي بكرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي بكرة - رضي الله عنه - قال: ((نهى رسول الله - صلى الله عليه وسلم - عن الفضة بالفضة , والذهب بالذهب , إلا سواء بسواء , وأمرنا: أن نشتري الفضة بالذهب , كيف شئنا. ونشتري الذهب بالفضة كيف شئنا. قال: فسأله رجل فقال: يدا بيد؟ فقال: هكذا سمعت)) .","bab":"باب الربا والصرف"},{"id":"umdat-ahkam:414","bookId":"umdat-ahkam","type":"section","seq":414,"chapter":"كتاب البيوع","title":"285- عن عائشة رضي الله عنها","page":"ج1 ص188","text":"عن عائشة رضي الله عنها ((أن رسول الله - صلى الله عليه وسلم - اشترى من يهودي طعاما , ورهنه درعا من حديد)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:415","bookId":"umdat-ahkam","type":"section","seq":415,"chapter":"كتاب البيوع","title":"286- عن أبي هريرة - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((مطل الغني ظلم. فإذا أتبع أحدكم على مليء فليتبع)) .\nمطل الغني: المماطلة في آداء ماعليه من حق للغير.\nأتبع: أحيل.\nمليء: الغني المقتدر على الوفاء.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:416","bookId":"umdat-ahkam","type":"section","seq":416,"chapter":"كتاب البيوع","title":"287- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم - أو قال: سمعت النبي - صلى الله عليه وسلم - يقول -: ((من أدرك ماله بعينه عند رجل - أو إنسان - قد أفلس فهو أحق به من غيره)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:417","bookId":"umdat-ahkam","type":"section","seq":417,"chapter":"كتاب البيوع","title":"288- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال ((جعل - وفي لفظ: ((قضى النبي - صلى الله عليه وسلم - بالشفعة في كل ما لم يقسم. فإذا وقعت","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:418","bookId":"umdat-ahkam","type":"section","seq":418,"chapter":"كتاب البيوع","title":"ص: 190","page":"ص0","text":"الحدود , وصرفت الطرق: فلا شفعة)) .\nالشفعة: استحقاق الشريك انتزاع حصة شريكه ممن انتقلت إليه بعوض.\nوقعت الحدود: عينت وتميزت.\nوصرفت الطرق: بنيت مصارفها وشوارعها.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:419","bookId":"umdat-ahkam","type":"section","seq":419,"chapter":"كتاب البيوع","title":"289- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((قد أصاب عمر أرضا بخيبر. فأتى النبي - صلى الله عليه وسلم - يستأمره فيها. فقال: يا رسول الله , إني أصبت أرضا بخيبر , لم أصب مالا قط هو أنفس عندي منه , فما تأمرني به؟ فقال: إن شئت حبست أصلها , وتصدقت بها. قال: فتصدق بها. غير أنه لا يباع أصلها , ولا يوهب , ولا يورث. قال: فتصدق عمر في الفقراء , وفي القربى , وفي الرقاب , وفي سبيل الله , وابن السبيل , والضيف. لا جناح على من وليها:","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:420","bookId":"umdat-ahkam","type":"section","seq":420,"chapter":"كتاب البيوع","title":"ص: 191","page":"ص0","text":"أن يأكل منها بالمعروف , أو يطعم صديقا , غير متمول فيه)) .\nوفي لفظ: ((غير متأثل)) .\nيستأمره: يستشيره ويطلب أمره.\nأنفس: أجود.\nحبست أصلها: وقفت أصل الأرض.\nغير متمول: غير متخذ منها ملكا لنفسه.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:421","bookId":"umdat-ahkam","type":"section","seq":421,"chapter":"كتاب البيوع","title":"290- عن عمر- رضي الله عنه - قال","page":"ص0","text":"عن عمر- رضي الله عنه - قال: ((حملت على فرس في سبيل الله , فأضاعه الذي كان عنده , فأردت أن أشتريه , فظننت أنه يبيعه برخص. فسألت النبي - صلى الله عليه وسلم -؟ فقال: لا تشتره. ولا تعد في صدقتك , وإن أعطاكه بدرهم. فإن العائد في هبته كالعائد في قيئه)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:422","bookId":"umdat-ahkam","type":"section","seq":422,"chapter":"كتاب البيوع","title":"291- وعن ابن عباس رضي الله عنهما","page":"ص0","text":"وعن ابن عباس رضي الله عنهما: أن رسول الله صلي الله عليه وسلم قال: \"العائد في هبته، كالعائد فيى قيئه\" (4) .\nوفي لفظ: \"فإن الذى يعود في صدقته كالكلب [يقئ ثم] يعود في قيئه\" (5) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:423","bookId":"umdat-ahkam","type":"section","seq":423,"chapter":"كتاب البيوع","title":"292- عن النعمان بن بشير رضي الله عنهما قال","page":"ص0","text":"عن النعمان بن بشير رضي الله عنهما قال: ((تصدق علي أبي ببعض ماله. فقالت أمي عمرة بنت رواحة: لا أرضى حتى تشهد رسول الله - صلى الله عليه وسلم -. فانطلق أبي إلى رسول الله - صلى الله عليه وسلم - ليشهد على صدقتي فقال له رسول الله - صلى الله عليه وسلم -: أفعلت هذا بولدك كلهم؟ قال: لا. قال: اتقوا الله واعدلوا في أولادكم، فرجع أبي , فرد تلك الصدقة)) . وفي لفظ: ((فلا تشهدني إذا. فإني لا أشهد على جور))\nوفي لفظ: ((فأشهد على هذا غيري)) .\nجور: ظلم.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:424","bookId":"umdat-ahkam","type":"section","seq":424,"chapter":"كتاب البيوع","title":"293- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما ((أن النبي - صلى الله عليه وسلم - عامل أهل خيبر بشطر ما يخرج منها من تمر أو زرع)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:425","bookId":"umdat-ahkam","type":"section","seq":425,"chapter":"كتاب البيوع","title":"294- عن رافع بن خديج قال","page":"ص0","text":"عن رافع بن خديج قال: ((كنا أكثر الأنصار","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:426","bookId":"umdat-ahkam","type":"section","seq":426,"chapter":"كتاب البيوع","title":"ص: 193","page":"ص0","text":"حقلا. وكنا نكري الأرض , على أن لنا هذه , ولهم هذه فربما أخرجت هذه , ولم تخرج هذه فنهانا عن ذلك. فأما بالورق: فلم ينهنا)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:427","bookId":"umdat-ahkam","type":"section","seq":427,"chapter":"كتاب البيوع","title":"295- ولمسلم عن حنظلة بن قيس قال","page":"ص0","text":"ولمسلم عن حنظلة بن قيس قال: ((سألت رافع بن خديج عن كراء الأرض بالذهب والورق؟ فقال: لا بأس به. إنما كان الناس يؤاجرون على عهد رسول الله - صلى الله عليه وسلم - بما على الماذيانات , وأقبال الجداول , وأشياء من الزرع فيهلك هذا , ويسلم هذا ولم يكن للناس كراء إلا هذا. ولذلك زجر عنه. فأما شيء معلوم مضمون: فلا بأس به)) .\nالماذيانات: الأنهار الكبار والجدول النهر الصغير.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:428","bookId":"umdat-ahkam","type":"section","seq":428,"chapter":"كتاب البيوع","title":"296- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((قضى رسول الله - صلى الله عليه وسلم - بالعمرى لمن وهبت له)) .\nالعمرى: مشتقة من العمر وهو الحياة. سميت بذلك لأنهم كانوا في الجاهلية يعطي الرجل الرجل الدار أوغيرها ويقول: أعمرتك إياها، أي أبحتها لك مدة عمرك وحياتك.\nوفي لفظ: ((من أعمر عمرى له ولعقبه. فإنها للذي أعطيها. لا ترجع إلى الذي أعطاها ; لأنه أعطى عطاء وقعت فيه المواريث)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:429","bookId":"umdat-ahkam","type":"section","seq":429,"chapter":"كتاب البيوع","title":"ص: 194","page":"ص0","text":"وقال جابر: ((إنما العمرى التي أجازها رسول الله - صلى الله عليه وسلم - , أن يقول: هي لك ولعقبك , فأما إذا قال: هي لك ما عشت: فإنها ترجع إلى صاحبها)) .\nوفي لفظ لمسلم: ((أمسكوا عليكم أموالكم ولا تفسدوها، فإنه من أعمر عمرى فهي للذي أعمرها: حيا , وميتا , ولعقبه)) .\nلعقبه: لذريته.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:430","bookId":"umdat-ahkam","type":"section","seq":430,"chapter":"كتاب البيوع","title":"297- عن أبي هريرة رضي الله عنه أن رسول الله - صلى الله عليه وسلم - قال","page":"ج1 ص194","text":"عن أبي هريرة رضي الله عنه أن رسول الله - صلى الله عليه وسلم - قال: ((لا يمنعن جار جاره: أن يغرز خشبة في جداره ثم يقول أبو هريرة: ما لي أراكم عنها معرضين؟ والله لأرمين بها بين أكتافكم)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:431","bookId":"umdat-ahkam","type":"section","seq":431,"chapter":"كتاب البيوع","title":"298- عن عائشة رضي الله عنها","page":"ج1 ص194","text":"عن عائشة رضي الله عنها: أن رسول الله - صلى الله عليه وسلم - قال: ((من ظلم قيد شبر من الأرض: طوقه من سبع أرضين)) .","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:432","bookId":"umdat-ahkam","type":"section","seq":432,"chapter":"كتاب البيوع","title":"ص: 195","page":"ج1 ص194","text":"قيد شبر: أي قدر شبر.\nطوقه: جعل طوقا في عنقه.","bab":"باب الرهن وغيره"},{"id":"umdat-ahkam:433","bookId":"umdat-ahkam","type":"section","seq":433,"chapter":"كتاب البيوع","title":"299- عن زيد بن خالد الجهني - رضي الله عنه - قال","page":"ج1 ص195","text":"عن زيد بن خالد الجهني - رضي الله عنه - قال: ((سئل رسول الله - صلى الله عليه وسلم - عن لقطة الذهب , أو الورق؟ فقال: اعرف وكاءها وعفاصها , ثم عرفها سنة فإن لم تعرف فاستنفقها ولتكن وديعة عندك فإن جاء طالبها يوما من الدهر: فأدها إليه , وسأله عن ضالة الإبل؟ فقال: ما لك ولها؟ دعها فإن معها حذاءها وسقاءها , ترد الماء وتأكل الشجر , حتى يجدها ربها. وسأله عن الشاة؟ فقال: خذها فإنما هي لك , أو لأخيك , أو للذئب)) .","bab":"باب اللقطة"},{"id":"umdat-ahkam:434","bookId":"umdat-ahkam","type":"section","seq":434,"chapter":"كتاب البيوع","title":"ص: 197","page":"ج1 ص195","text":"اللقطة: المال الضائع من صاحبه يلتقطه غيره.\nوكاءها: الوكاء: مايربط به الشيء.\nعفاصها: وعاؤها.\nحذاءها: خفها.\nسقاءها: جوفها الذي حمل كثيرا من الماء والطعام.","bab":"باب اللقطة"},{"id":"umdat-ahkam:435","bookId":"umdat-ahkam","type":"section","seq":435,"chapter":"كتاب البيوع","title":"300- عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال","page":"ج1 ص197","text":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله - صلى الله عليه وسلم - قال: ((ما حق امرئ مسلم , له شيء يوصي فيه , يبيت ليلتين إلا ووصيته مكتوبة عنده)) .\nزاد مسلم: قال ابن عمر: ((ما مرت علي ليلة منذ سمعت رسول الله - صلى الله عليه وسلم - يقول ذلك , إلا وعندي وصيتي)) .\nالوصية: عهد خاص بالتصرف بالمال، أوالتبرع به بعد الموت.","bab":"باب الوصايا"},{"id":"umdat-ahkam:436","bookId":"umdat-ahkam","type":"section","seq":436,"chapter":"كتاب البيوع","title":"301- عن سعد بن أبي وقاص - رضي الله عنه - قال","page":"ص0","text":"عن سعد بن أبي وقاص - رضي الله عنه - قال: ((جاءني رسول الله - صلى الله عليه وسلم - يعودني عام حجة الوداع من وجع اشتد بي فقلت: يا","bab":"باب الوصايا"},{"id":"umdat-ahkam:437","bookId":"umdat-ahkam","type":"section","seq":437,"chapter":"كتاب البيوع","title":"ص: 198","page":"ص0","text":"رسول الله , قد بلغ بي من الوجع ما ترى، وأنا ذو مال , ولا يرثني إلا ابنة أفأتصدق بثلثي مالي؟ قال: لا، قلت: فالشطر يا رسول الله؟ قال: لا، قلت: فالثلث قال: الثلث , والثلث كثير، إنك أن تذر ورثتك أغنياء خير من أن تذرهم عالة يتكففون الناس، وإنك لن تنفق نفقة تبتغي بها وجه الله إلا أجرت بها , حتى ما تجعل في في امرأتك. قال: قلت: يا رسول الله أخلف بعد أصحابي؟ قال: إنك لن تخلف فتعمل عملا تبتغي به وجه الله إلا ازددت به درجة ورفعة , ولعلك أن تخلف حتى ينتفع بك أقوام , ويضر بك آخرون. اللهم أمض لأصحابي هجرتهم , ولا تردهم على أعقابهم، لكن البائس سعد بن خولة يرثي له رسول الله - صلى الله عليه وسلم - أن مات بمكة)) .","bab":"باب الوصايا"},{"id":"umdat-ahkam:438","bookId":"umdat-ahkam","type":"section","seq":438,"chapter":"كتاب البيوع","title":"ص: 199","page":"ص0","text":"يعودني: يزورني في مرضي.\nتذرهم: تتركهم.\nعالة: فقراء.\nيتكففون: يمدون أيديهم للسؤال.","bab":"باب الوصايا"},{"id":"umdat-ahkam:439","bookId":"umdat-ahkam","type":"section","seq":439,"chapter":"كتاب البيوع","title":"302- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((لو أن الناس غضوا من الثلث إلى الربع؟ فإن رسول الله - صلى الله عليه وسلم - قال: الثلث , والثلث كثير)) .","bab":"باب الوصايا"},{"id":"umdat-ahkam:440","bookId":"umdat-ahkam","type":"section","seq":440,"chapter":"كتاب البيوع","title":"ص: 201","page":"ص0","text":"غضوا: أنقصوا.","bab":"باب الوصايا"},{"id":"umdat-ahkam:441","bookId":"umdat-ahkam","type":"section","seq":441,"chapter":"كتاب البيوع","title":"303- عن عبد الله بن عباس رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال","page":"ج1 ص201","text":"عن عبد الله بن عباس رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال: ((ألحقوا الفرائض بأهلها، فما بقي فهو لأولى رجل ذكر)) .\nوفي رواية: ((اقسموا المال بين أهل الفرائض على كتاب الله فما تركت: فلأولى رجل ذكر)) .\nالفرائض: النصيب المقدر للوارث.\nلأولى رجل: لأقرب رجل في النسب.","bab":"باب الفرائض"},{"id":"umdat-ahkam:442","bookId":"umdat-ahkam","type":"section","seq":442,"chapter":"كتاب البيوع","title":"304- عن أسامة بن زيد رضي الله عنهما قال","page":"ص0","text":"عن أسامة بن زيد رضي الله عنهما قال: ((قلت يا رسول الله , أتنزل غدا في دارك بمكة؟ قال: وهل ترك لنا عقيل","bab":"باب الفرائض"},{"id":"umdat-ahkam:443","bookId":"umdat-ahkam","type":"section","seq":443,"chapter":"كتاب البيوع","title":"ص: 202","page":"ص0","text":"من رباع؟ ثم قال: لا يرث الكافر المسلم ولا المسلم الكافر)) .\nالرباع: محلات الإقامة، أي الدور.","bab":"باب الفرائض"},{"id":"umdat-ahkam:444","bookId":"umdat-ahkam","type":"section","seq":444,"chapter":"كتاب البيوع","title":"305- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما ((أن النبي - صلى الله عليه وسلم - نهى عن بيع الولاء وعن هبته)) .","bab":"باب الفرائض"},{"id":"umdat-ahkam:445","bookId":"umdat-ahkam","type":"section","seq":445,"chapter":"كتاب البيوع","title":"306- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((كانت في بريرة ثلاث سنن: خيرت على زوجها حين عتقت , وأهدي لها لحم , فدخل علي رسول الله - صلى الله عليه وسلم - والبرمة على النار , فدعا بطعام فأتي بخبز وأدم","bab":"باب الفرائض"},{"id":"umdat-ahkam:446","bookId":"umdat-ahkam","type":"section","seq":446,"chapter":"كتاب البيوع","title":"ص: 203","page":"ص0","text":"من أدم البيت فقال: ألم أر البرمة على النار فيها لحم؟ قالوا: بلى , يا رسول الله. ذلك لحم تصدق به على بريرة فكرهنا أن نطعمك منه فقال: هو عليها صدقة , وهو منها لنا هدية , وقال النبي - صلى الله عليه وسلم - فيها: إنما الولاء لمن أعتق)) .","bab":"باب الفرائض"},{"id":"umdat-ahkam:447","bookId":"umdat-ahkam","type":"section","seq":447,"chapter":"كتاب البيوع","title":"ص: 205","page":"ص0","text":"البرمة: قدر من حجارة.","bab":"باب الفرائض"},{"id":"umdat-ahkam:448","bookId":"umdat-ahkam","type":"section","seq":448,"chapter":"كتاب النكاح","title":"307- عن عبد الله بن مسعود قال","page":"ج1 ص205","text":"عن عبد الله بن مسعود قال: قال لنا رسول الله - صلى الله عليه وسلم -: ((يا معشر الشباب , من استطاع منكم الباءة فليتزوج فإنه أغض للبصر , وأحصن للفرج , ومن لم يستطع فعليه بالصوم فإنه له وجاء)) ."},{"id":"umdat-ahkam:449","bookId":"umdat-ahkam","type":"section","seq":449,"chapter":"كتاب النكاح","title":"ص: 206","page":"ج1 ص205","text":"معشر الشباب: المعشر: هم الطائفة الذين يشملهم وصف.\nالباءة: الجماع والقدرة على مؤنة النكاح.\nأغض للبصر: أشد غضا للبصر.\nوأحصن للفرج: أشد إحصانا للفرج.\nوجاء: الوجاء: الخصاء، وذلك نظرا لأن الصوم يضعف الشهوة فشبه بالخصاء."},{"id":"umdat-ahkam:450","bookId":"umdat-ahkam","type":"section","seq":450,"chapter":"كتاب النكاح","title":"308- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه -: ((أن نفرا من أصحاب النبي - صلى الله عليه وسلم - سألوا أزواج النبي - صلى الله عليه وسلم - عن عمله في السر؟ فقال بعضهم: لا أتزوج النساء. وقال بعضهم: لا آكل اللحم. وقال بعضهم: لا أنام على فراش. فبلغ ذلك النبي - صلى الله عليه وسلم - فحمد الله وأثنى عليه وقال: ما بال أقوام قالوا كذا؟ لكني أصلي وأنام وأصوم وأفطر , وأتزوج النساء فمن رغب عن سنتي فليس مني)) ."},{"id":"umdat-ahkam:451","bookId":"umdat-ahkam","type":"section","seq":451,"chapter":"كتاب النكاح","title":"309- عن سعد بن أبي وقاص - رضي الله عنه - قال","page":"ص0","text":"عن سعد بن أبي وقاص - رضي الله عنه - قال: ((رد"},{"id":"umdat-ahkam:452","bookId":"umdat-ahkam","type":"section","seq":452,"chapter":"كتاب النكاح","title":"ص: 207","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - على عثمان بن مظعون التبتل ولو أذن له لاختصينا)) .\nالتبتل: ترك النكاح اشتغالا بعبادة الله تعالى."},{"id":"umdat-ahkam:453","bookId":"umdat-ahkam","type":"section","seq":453,"chapter":"كتاب النكاح","title":"310- عن أم حبيبة بنت أبي سفيان رضي الله عنها أنها قالت","page":"ص0","text":"عن أم حبيبة بنت أبي سفيان رضي الله عنها أنها قالت: ((يا رسول الله , انكح أختي ابنة أبي سفيان قال: أوتحبين ذلك؟ فقلت: نعم , لست لك بمخلية , وأحب من شاركني في خير أختي: فقال رسول الله - صلى الله عليه وسلم -: إن ذلك لا يحل لي. قالت: إنا نحدث أنك تريد أن تنكح بنت أبي سلمة قال: بنت أم سلمة؟ قالت: قلت: نعم , قال: إنها لو لم تكن ربيبتي في حجري , ما حلت لي إنها لابنة أخي من الرضاعة , أرضعتني وأبا سلمة ثويبة فلا"},{"id":"umdat-ahkam:454","bookId":"umdat-ahkam","type":"section","seq":454,"chapter":"كتاب النكاح","title":"ص: 208","page":"ص0","text":"تعرضن علي بناتكن ولا أخواتكن. قال عروة وثويبة: مولاة لأبي لهب أعتقها , فأرضعت النبي - صلى الله عليه وسلم - فلما مات أبو لهب رآه بعض أهله بشر حيبة فقال له: ماذا لقيت؟ قال أبو لهب: لم ألق بعدكم خيرا , غير أني سقيت في هذه بعتاقتي ثويبة)) .\nالحيبة: بكسر الحاء: الحالة. أه\nلست لك بمخلية: لست بمنفردة بك.\nربيبتي في حجري: الربيبة: بنت الزوجة."},{"id":"umdat-ahkam:455","bookId":"umdat-ahkam","type":"section","seq":455,"chapter":"كتاب النكاح","title":"311- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا يجمع بين المرأة وعمتها , ولا بين المرأة وخالتها)) ."},{"id":"umdat-ahkam:456","bookId":"umdat-ahkam","type":"section","seq":456,"chapter":"كتاب النكاح","title":"312- عن عقبة بن عامر - رضي الله عنه - قال","page":"ص0","text":"عن عقبة بن عامر - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -:"},{"id":"umdat-ahkam:457","bookId":"umdat-ahkam","type":"section","seq":457,"chapter":"كتاب النكاح","title":"ص: 209","page":"ص0","text":"((إن أحق الشروط أن توفوا به: ما استحللتم به الفروج)) ."},{"id":"umdat-ahkam:458","bookId":"umdat-ahkam","type":"section","seq":458,"chapter":"كتاب النكاح","title":"313- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما: ((أن رسول الله - صلى الله عليه وسلم - نهى عن الشغار)) . والشغار: أن يزوج الرجل ابنته على أن يزوجه ابنته , وليس بينهما الصداق."},{"id":"umdat-ahkam:459","bookId":"umdat-ahkam","type":"section","seq":459,"chapter":"كتاب النكاح","title":"314- عن علي بن أبي طالب - رضي الله عنه -","page":"ص0","text":"عن علي بن أبي طالب - رضي الله عنه -: ((أن النبي - صلى الله عليه وسلم - نهى عن نكاح المتعة يوم خيبر , وعن لحوم الحمر الأهلية)) ."},{"id":"umdat-ahkam:460","bookId":"umdat-ahkam","type":"section","seq":460,"chapter":"كتاب النكاح","title":"ص: 210","page":"ص0","text":"نكاح المتعة: هو أن يتزوج الرجل المرأة إلى وقت محدد."},{"id":"umdat-ahkam:461","bookId":"umdat-ahkam","type":"section","seq":461,"chapter":"كتاب النكاح","title":"315- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((لا تنكح الأيم حتى تستأمر , ولا تنكح البكر حتى تستأذن. قالوا: يا رسول الله , فكيف إذنها قال: أن تسكت)) .\nالأيم: هي من لازوج لها، وليست بكرا.\nتستأمر: يطلب الإذن منها صريحا في العقد عليها."},{"id":"umdat-ahkam:462","bookId":"umdat-ahkam","type":"section","seq":462,"chapter":"كتاب النكاح","title":"316- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((جاءت امرأة رفاعة القرظي إلى النبي - صلى الله عليه وسلم - فقالت: كنت عند رفاعة القرظي فطلقني فبت طلاقي. فتزوجت بعده عبد الرحمن بن الزبير وإنما معه مثل هدبة الثوب. فتبسم رسول الله - صلى الله عليه وسلم - وقال: أتريدين أن ترجعي إلى رفاعة؟ لا , حتى تذوقي عسيلته , ويذوق عسيلتك , قالت: وأبو بكر عنده , وخالد بن سعيد بالباب ينتظر أن يؤذن له , فنادى أبا بكر: ألا تسمع إلى هذه: ما تجهر به عند رسول الله - صلى الله عليه وسلم -)) ."},{"id":"umdat-ahkam:463","bookId":"umdat-ahkam","type":"section","seq":463,"chapter":"كتاب النكاح","title":"ص: 211","page":"ص0","text":"فبت طلاقي: طلقني طلاق البتة الذي لارجعة فيه.\nهدبة الثوب: طرف الثوب.\nعسيلته: كناية عن الجماع، شبه لذته بلذة العسل وحلاوته."},{"id":"umdat-ahkam:464","bookId":"umdat-ahkam","type":"section","seq":464,"chapter":"كتاب النكاح","title":"317- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: ((من السنة إذا تزوج البكر على الثيب: أقام عندها سبعا ثم قسم. وإذا تزوج الثيب: أقام عندها ثلاثا ثم قسم)) .\nقال أبو قلابة: ولو شئت لقلت: إن أنسا رفعه إلى النبي - صلى الله عليه وسلم -)) .\nقسم: القسم: هو المبيت عند كل زوجة في نوبتها."},{"id":"umdat-ahkam:465","bookId":"umdat-ahkam","type":"section","seq":465,"chapter":"كتاب النكاح","title":"318- عن ابن عباس رضي الله عنهما قال","page":"ص0","text":"عن ابن عباس رضي الله عنهما قال: قال رسول الله - صلى الله عليه وسلم - ((لو أن أحدهم: إذا أراد أن يأتي أهله قال: بسم الله اللهم جنبنا الشيطان , وجنب الشيطان ما رزقتنا فإنه إن يقدر بينهما ولد في ذلك , لم يضره الشيطان أبدا)) ."},{"id":"umdat-ahkam:466","bookId":"umdat-ahkam","type":"section","seq":466,"chapter":"كتاب النكاح","title":"319- عن عقبة بن عامر - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عقبة بن عامر - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((إياكم والدخول على النساء. فقال رجل من الأنصار: يا رسول الله , أرأيت الحمو؟ قال: الحمو الموت)) ."},{"id":"umdat-ahkam:467","bookId":"umdat-ahkam","type":"section","seq":467,"chapter":"كتاب النكاح","title":"ص: 213","page":"ص0","text":"ولمسلم: عن أبي الطاهر عن ابن وهب قال: \" سمعت الليث يقول: الحمو: أخو الزوج وماأشبهه من أقارب الزوج، ابن عم ونحوه.\nالحمو الموت: يعني أن الخلوة بأقارب الزوج مؤدية إلى الفتنة والهلاك في الدين، فجعله كهلاك الموت"},{"id":"umdat-ahkam:468","bookId":"umdat-ahkam","type":"section","seq":468,"chapter":"كتاب النكاح","title":"320- عن أنس بن مالك - رضي الله عنه -","page":"ج1 ص213","text":"عن أنس بن مالك - رضي الله عنه - ((أن رسول الله - صلى الله عليه وسلم - أعتق صفية , وجعل عتقها صداقها)) .\nصداقها: مهرها.","bab":"باب الصداق"},{"id":"umdat-ahkam:469","bookId":"umdat-ahkam","type":"section","seq":469,"chapter":"كتاب النكاح","title":"321- عن سهل بن سعد الساعدي - رضي الله عنه -","page":"ص0","text":"عن سهل بن سعد الساعدي - رضي الله عنه - ((أن رسول الله - صلى الله عليه وسلم - جاءته امرأة فقالت: إني وهبت نفسي لك: فقامت طويلا، فقال رجل: يا رسول الله , زوجنيها , إن لم يكن لك بها حاجة. فقال: هل عندك من شيء تصدقها؟ فقال: ما عندي إلا إزاري هذا. فقال رسول الله - صلى الله عليه وسلم -: إزارك إن أعطيتها جلست ولا إزار","bab":"باب الصداق"},{"id":"umdat-ahkam:470","bookId":"umdat-ahkam","type":"section","seq":470,"chapter":"كتاب النكاح","title":"ص: 214","page":"ص0","text":"لك، فالتمس شيئا قال: ما أجد. قال: التمس ولو خاتما من حديد، فالتمس فلم يجد شيئا، فقال رسول الله - صلى الله عليه وسلم - هل معك شيء من القرآن؟ قال: نعم، فقال رسول الله - صلى الله عليه وسلم -: زوجتكها بما معك من القرآن)) .","bab":"باب الصداق"},{"id":"umdat-ahkam:471","bookId":"umdat-ahkam","type":"section","seq":471,"chapter":"كتاب النكاح","title":"322- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه -: ((أن رسول الله - صلى الله عليه وسلم - رأى عبد الرحمن بن عوف , وعليه ردع زعفران. فقال النبي - صلى الله عليه وسلم -: مهيم؟ فقال: يا رسول الله تزوجت امرأة , فقال: ما أصدقتها؟","bab":"باب الصداق"},{"id":"umdat-ahkam:472","bookId":"umdat-ahkam","type":"section","seq":472,"chapter":"كتاب النكاح","title":"ص: 215","page":"ص0","text":"قال: وزن نواة من ذهب قال: فبارك الله لك , أولم ولو بشاة)) .","bab":"باب الصداق"},{"id":"umdat-ahkam:473","bookId":"umdat-ahkam","type":"section","seq":473,"chapter":"كتاب النكاح","title":"ص: 217","page":"ص0","text":"ردع زعفران: أثر صفرة الزعفران.\nمهيم: مالك وماشأنك.\nنواة من ذهب: مقدارها خمسة دراهم من الذهب.\nأولم: اصنع وليمة، وهي طعام العرس.","bab":"باب الصداق"},{"id":"umdat-ahkam:474","bookId":"umdat-ahkam","type":"section","seq":474,"chapter":"كتاب الطلاق","title":"323- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص217","text":"عن عبد الله بن عمر رضي الله عنهما، ((أنه طلق امرأته وهي حائض، فذكر ذلك عمر لرسول الله - صلى الله عليه وسلم -، فتغيظ منه رسول الله - صلى الله عليه وسلم -، ثم قال: ليراجعها , ثم ليمسكها حتى تطهر , ثم تحيض فتطهر , فإن بدا له أن يطلقها فليطلقها قبل أن يمسها، فتلك العدة , كما أمر الله عز وجل)) .\nوفي لفظ: ((حتى تحيض حيضة مستقبلة , سوى حيضتها التي طلقها فيها)) ."},{"id":"umdat-ahkam:475","bookId":"umdat-ahkam","type":"section","seq":475,"chapter":"كتاب الطلاق","title":"ص: 218","page":"ج1 ص217","text":"وفي لفظ ((فحسبت من طلاقها , وراجعها عبد الله كما أمره رسول الله - صلى الله عليه وسلم -)) .\nفتغيظ منه: ظهر عليه الغيظ.\nقبل أن يمسها: قبل أن يجامعها."},{"id":"umdat-ahkam:476","bookId":"umdat-ahkam","type":"section","seq":476,"chapter":"كتاب الطلاق","title":"324- عن فاطمة بنت قيس","page":"ص0","text":"عن فاطمة بنت قيس ((أن أبا عمرو بن حفص طلقها البتة , وهو غائب)) .\nوفي رواية: ((طلقها ثلاثا - فأرسل إليها وكيله بشعير , فسخطته. فقال: والله ما لك علينا من شيء: فجاءت رسول الله - صلى الله عليه وسلم - فذكرت ذلك له , فقال: ليس لك عليه نفقة)) وفي لفظ: ((ولا سكنى - فأمرها أن تعتد في بيت أم شريك , ثم قال: تلك امرأة يغشاها أصحابي , اعتدي عند ابن أم مكتوم. فإنه رجل أعمى , تضعين ثيابك , فإذا حللت فآذنيني. قالت: فلما حللت ذكرت له: أن معاوية بن أبي سفيان وأبا جهم خطباني , فقال رسول الله - صلى الله عليه وسلم -: أما أبو جهم: فلا يضع عصاه عن عاتقه. وأما معاوية: فصعلوك لا مال له , انكحي أسامة بن زيد , فكرهته ثم"},{"id":"umdat-ahkam:477","bookId":"umdat-ahkam","type":"section","seq":477,"chapter":"كتاب الطلاق","title":"ص: 219","page":"ص0","text":"قال: انكحي أسامة بن زيد , فنكحته. فجعل الله فيه خيرا , واغتبطت به)) .\nطلقها البتة: طلقها طلاقا بائنا لارجعة فيه.\nفسخطته: السخط هو عدم الرضا.\nتعتد: تقضي عدتها.\nيغشاها أصحابي: يترددون عليها لصلاحها. وفضلها.\nآذنيني: أعلميني.\nعاتقه: العاتق: مابين العنق والمنكب.\nصعلوك: فقير.\nاغتبطت به: سرت به."},{"id":"umdat-ahkam:478","bookId":"umdat-ahkam","type":"section","seq":478,"chapter":"كتاب الطلاق","title":"باب العدة","page":"ص0","text":"العدة: هي اسم للمدة التي تنتظر فيها المرأة وتمتنع عن الزواج بعد وفاة زوجها أوطلاقه لها.","bab":"باب العدة"},{"id":"umdat-ahkam:479","bookId":"umdat-ahkam","type":"section","seq":479,"chapter":"كتاب الطلاق","title":"325- عن سبيعة الأسلمية أنها كانت تحت سعد بن خولة - وهو من بني عامر بن لؤي","page":"ج1 ص219","text":"عن سبيعة الأسلمية أنها كانت تحت سعد بن خولة - وهو من بني عامر بن لؤي , وكان ممن شهد بدرا - فتوفي عنها في حجة الوداع , وهي حامل. فلم تنشب أن وضعت حملها بعد وفاته , فلما تعلت من نفاسها: تجملت للخطاب , فدخل عليها أبو السنابل بن بعكك - رجل من بني عبد الدار - فقال لها: ما لي أراك متجملة؟ لعلك ترجين للنكاح , والله ما أنت بناكح حتى يمر عليك أربعة أشهر وعشر. قالت سبيعة: فلما قال لي","bab":"باب العدة"},{"id":"umdat-ahkam:480","bookId":"umdat-ahkam","type":"section","seq":480,"chapter":"كتاب الطلاق","title":"ص: 220","page":"ج1 ص219","text":"ذلك: جمعت علي ثيابي حين أمسيت , فأتيت رسول - صلى الله عليه وسلم - فسألته عن ذلك؟ فأفتاني بأني قد حللت حين وضعت حملي , وأمرني بالتزويج إن بدا لي)) .\nوقال ابن شهاب: ولاأرى بأسا أن تتزوج حين وضعت، وإن كانت في دمها، غير أنه لايقربها زوجها حتى تطهر.\nفلم تنشب: فلم تلبث.\nفلما تعلت: أي لما طهرت من دمها.\nتجملت: تزينت وتهيأت.","bab":"باب العدة"},{"id":"umdat-ahkam:481","bookId":"umdat-ahkam","type":"section","seq":481,"chapter":"كتاب الطلاق","title":"321- عن زينب بنت أم سلمة قالت","page":"ج1 ص219","text":"عن زينب بنت أم سلمة قالت: ((توفي حميم لأم حبيبة , فدعت بصفرة , فمسحت بذراعيها , فقالت: إنما أصنع هذا ; لأني سمعت رسول الله - صلى الله عليه وسلم - يقول: لا يحل لامرأة تؤمن بالله واليوم الآخر أن تحد على ميت فوق ثلاث , إلا على زوج: أربعة أشهر وعشرا)) .","bab":"باب العدة"},{"id":"umdat-ahkam:482","bookId":"umdat-ahkam","type":"section","seq":482,"chapter":"كتاب الطلاق","title":"ص: 221","page":"ج1 ص219","text":"الحميم: القرابة.\nحميم: قريب لها وهو أبوها أبو سفيان - رضي الله عنه -.\nبصفرة: بطيب.\nأن تحد: منع المعتدة نفسها الزينة وبدنها الطيب.","bab":"باب العدة"},{"id":"umdat-ahkam:483","bookId":"umdat-ahkam","type":"section","seq":483,"chapter":"كتاب الطلاق","title":"327- عن أم عطية رضي الله عنها","page":"ص0","text":"عن أم عطية رضي الله عنها: أن رسول الله - صلى الله عليه وسلم - قال: ((لا تحد امرأة على الميت فوق ثلاث , إلا على زوج: أربعة أشهر وعشرا , ولا تلبس ثوبا مصبوغا إلا ثوب عصب. ولا تكتحل. ولا تمس طيبا , إلا إذا طهرت: نبذة من قسط أو أظفار)) .\nالعصب: ثياب من اليمن فيها بياض وسواد.\nوالنبذة: الشيء اليسير. والقسط: العود أونوع من الطيب تبخر به النفساء.\nوالأظفار: جنس من الطيب لاواحد له من لفظه. وقيل: هو عطر أسود، القطعة منه تشبه الظفر.","bab":"باب العدة"},{"id":"umdat-ahkam:484","bookId":"umdat-ahkam","type":"section","seq":484,"chapter":"كتاب الطلاق","title":"328- عن أم سلمة رضي الله عنها قالت","page":"ص0","text":"عن أم سلمة رضي الله عنها قالت: ((جاءت امرأة إلى رسول الله - صلى الله عليه وسلم - فقالت: يا رسول الله , إن ابنتي توفي عنها زوجها , وقد اشتكت عينها أفنكحلها؟ فقال رسول الله - صلى الله عليه وسلم -: لا - مرتين , أو","bab":"باب العدة"},{"id":"umdat-ahkam:485","bookId":"umdat-ahkam","type":"section","seq":485,"chapter":"كتاب الطلاق","title":"ص: 222","page":"ص0","text":"ثلاثا - ثم قال: إنما هي أربعة أشهر وعشر. وقد كانت إحداكن في الجاهلية ترمي بالبعرة على رأس الحول)) .\nفقالت زينب: كانت المرأة إذا توفي عنها زوجها: دخلت حفشا , ولبست شر ثيابها , ولم تمس طيبا ولا شيئا حتى تمر بها سنة , ثم تؤتى بدابة - حمار أو طير أو شاة - فتفتض به. فقلما تفتض بشيء إلا مات. ثم تخرج فتعطى بعرة , فترمي بها ثم تراجع بعد ما شاءت من طيب أو غيره)) .\nالحول: العام.\nالحفش: البيت الصغير.\nتفتض: تدلك به جسدها.","bab":"باب العدة"},{"id":"umdat-ahkam:486","bookId":"umdat-ahkam","type":"section","seq":486,"chapter":"كتاب اللعان","title":"329- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص223","text":"عن عبد الله بن عمر رضي الله عنهما ((أن فلان بن فلان قال: يا رسول الله , أرأيت أن لو وجد أحدنا امرأته على فاحشة , كيف يصنع؟ إن تكلم تكلم بأمر عظيم , وإن سكت سكت على مثل ذلك. قال: فسكت النبي - صلى الله عليه وسلم - فلم يجبه. فلما كان بعد ذلك أتاه فقال: إن الذي سألتك عنه قد ابتليت به. فأنزل الله عز وجل هؤلاء الآيات في سورة النور ((والذين يرمون أزواجهم)) فتلاهن عليه ووعظه وذكره. وأخبره أن عذاب الدنيا أهون من عذاب الآخرة. فقال: لا , والذي بعثك بالحق , ما كذبت عليها. ثم دعاها , فوعظها , وأخبرها: أن عذاب الدنيا أهون من عذاب الآخرة. فقالت: لا , والذي بعثك بالحق , إنه لكاذب. فبدأ بالرجل فشهد أربع شهادات بالله: إنه لمن الصادقين. والخامسة: أن لعنة الله عليه إن كان من الكاذبين. ثم ثنى بالمرأة. فشهدت أربع شهادات بالله: إنه لمن الكاذبين , والخامسة: أن غضب الله عليها إن كان من الصادقين. ثم فرق بينهما. ثم قال: إن الله يعلم أن أحدكما كاذب فهل منكما تائب؟)) ثلاثا."},{"id":"umdat-ahkam:487","bookId":"umdat-ahkam","type":"section","seq":487,"chapter":"كتاب اللعان","title":"ص: 224","page":"ج1 ص223","text":"وفي لفظ ((لا سبيل لك عليها قال: يا رسول الله , مالي؟ قال: لا مال لك. إن كنت صدقت عليها فهو بما استحللت من فرجها وإن كنت كذبت فهو أبعد لك منها)) ."},{"id":"umdat-ahkam:488","bookId":"umdat-ahkam","type":"section","seq":488,"chapter":"كتاب اللعان","title":"330- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما ((أن رجلا رمى امرأته , وانتفى من ولدها في زمن رسول الله - صلى الله عليه وسلم - فأمرهما رسول الله - صلى الله عليه وسلم - فتلاعنا , كما قال الله تعالى , ثم قضى بالولد للمرأة , وفرق بين المتلاعنين)) .\nوانتفى من ولدها: أنكره وبرىء منه."},{"id":"umdat-ahkam:489","bookId":"umdat-ahkam","type":"section","seq":489,"chapter":"كتاب اللعان","title":"331- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال ((جاء رجل من بني فزارة إلى النبي - صلى الله عليه وسلم - فقال: إن امرأتي ولدت غلاما أسود. فقال النبي - صلى الله عليه وسلم - هل لك إبل؟ قال: نعم. قال: فما ألوانها؟ قال: حمر. قال: فهل يكون فيها من أورق؟ قال: إن فيها لورقا. قال: فأنى أتاها ذلك؟ قال: عسى أن يكون نزعه عرق. قال: وهذا عسى أن يكون نزعه عرق)) ."},{"id":"umdat-ahkam:490","bookId":"umdat-ahkam","type":"section","seq":490,"chapter":"كتاب اللعان","title":"ص: 225","page":"ص0","text":"أورق: هو الذي فيه سواد ليس بصاف.\nنزعه عرق: جذبه أصل من النسب."},{"id":"umdat-ahkam:491","bookId":"umdat-ahkam","type":"section","seq":491,"chapter":"كتاب اللعان","title":"332- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((اختصم سعد بن أبي وقاص وعبد بن زمعة في غلام. فقال سعد: يا رسول الله هذا ابن أخي عتبة بن أبي وقاص , عهد إلي أنه ابنه , انظر إلى شبهه. وقال عبد بن زمعة: هذا أخي يا رسول الله , ولد على فراش أبي من وليدته , فنظر رسول الله - صلى الله عليه وسلم - إلى شبهه , فرأى شبها بينا بعتبة فقال: هو لك يا عبد بن زمعة , الولد للفراش وللعاهر الحجر. واحتجبي منه يا سودة، فلم ير سودة قط)) .\nوليدته: جاريته.\nوللعاهر الحجر: للزاني الخيبة والخسران."},{"id":"umdat-ahkam:492","bookId":"umdat-ahkam","type":"section","seq":492,"chapter":"كتاب اللعان","title":"333- عن عائشة رضي الله عنها أنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها أنها قالت: ((إن رسول الله - صلى الله عليه وسلم - دخل علي مسرورا , تبرق أسارير وجهه. فقال: ألم تري أن"},{"id":"umdat-ahkam:493","bookId":"umdat-ahkam","type":"section","seq":493,"chapter":"كتاب اللعان","title":"ص: 226","page":"ص0","text":"مجززا نظر آنفا إلى زيد بن حارثة وأسامة بن زيد , فقال: إن بعض هذه الأقدام لمن بعض)) .\nوفي لفظ: ((كان مجزز قائفا)) .\nتبرق أسارير وجهه: تلمع وتضيء.\nقائفا: القائف: هو من يعرف إلحاق الأنساب بالشبه ويعرف الآثار."},{"id":"umdat-ahkam:494","bookId":"umdat-ahkam","type":"section","seq":494,"chapter":"كتاب اللعان","title":"334- عن أبي سعيد الخدري - رضي الله عنه - قال","page":"ص0","text":"عن أبي سعيد الخدري - رضي الله عنه - قال: ((ذكر العزل لرسول الله - صلى الله عليه وسلم -. فقال: ولم يفعل ذلك أحدكم؟ - ولم يقل: فلا يفعل ذلك أحدكم، فإنه ليست نفس مخلوقة إلا الله خالقها)) ."},{"id":"umdat-ahkam:495","bookId":"umdat-ahkam","type":"section","seq":495,"chapter":"كتاب اللعان","title":"335- عن جابر بن عبد الله رضي الله عنهما قال","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((كنا نعزل والقرآن ينزل ,"},{"id":"umdat-ahkam:496","bookId":"umdat-ahkam","type":"section","seq":496,"chapter":"كتاب اللعان","title":"ص: 227","page":"ص0","text":"لو كان شيئا ينهى عنه لنهانا عنه القرآن)) .\nالعزل: نزع الذكر من الفرج إذا قارب الإنزال."},{"id":"umdat-ahkam:497","bookId":"umdat-ahkam","type":"section","seq":497,"chapter":"كتاب اللعان","title":"336- عن أبي ذر - رضي الله عنه -","page":"ص0","text":"عن أبي ذر - رضي الله عنه -: أنه سمع رسول الله - صلى الله عليه وسلم - يقول ((ليس من رجل ادعى لغير أبيه - وهو يعلمه - إلا كفر. ومن ادعى ما ليس له: فليس منا , وليتبوأ مقعده من النار ومن دعا رجلا بالكفر , أو قال: عدو الله , وليس كذلك , إلا حار عليه)) ."},{"id":"umdat-ahkam:498","bookId":"umdat-ahkam","type":"section","seq":498,"chapter":"كتاب اللعان","title":"ص: 229","page":"ص0","text":"وليتبوأ: أي فليتخذ له مباءة، وهي المنزل.\nحار عليه: رجع عليه."},{"id":"umdat-ahkam:499","bookId":"umdat-ahkam","type":"section","seq":499,"chapter":"كتاب الرضاع","title":"337- عن ابن عباس رضي الله عنهما قال","page":"ج1 ص229","text":"عن ابن عباس رضي الله عنهما قال: ((قال رسول الله - صلى الله عليه وسلم - في بنت حمزة: لاتحل لي , يحرم من الرضاع ما يحرم من النسب , وهي ابنة أخي من الرضاعة)) ."},{"id":"umdat-ahkam:500","bookId":"umdat-ahkam","type":"section","seq":500,"chapter":"كتاب الرضاع","title":"338- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: قال رسول الله - صلى الله عليه وسلم -: ((إن الرضاعة تحرم ما يحرم من الولادة)) ."},{"id":"umdat-ahkam:501","bookId":"umdat-ahkam","type":"section","seq":501,"chapter":"كتاب الرضاع","title":"339- وعنها قالت","page":"ص0","text":"وعنها قالت: ((إن أفلح - أخا أبي القعيس - استأذن علي بعدما أنزل الحجاب؟ فقلت: والله لا آذن له , حتى أستأذن"},{"id":"umdat-ahkam:502","bookId":"umdat-ahkam","type":"section","seq":502,"chapter":"كتاب الرضاع","title":"ص: 230","page":"ص0","text":"النبي - صلى الله عليه وسلم - فإن أخا أبي القعيس: ليس هو أرضعني , ولكن أرضعتني امرأة أبي القعيس , فدخل علي رسول الله - صلى الله عليه وسلم - فقلت: يا رسول الله: إن الرجل ليس هو أرضعني , ولكن أرضعتني امرأته. فقال: ائذني له , فإنه عمك , تربت يمينك)) .\nقال عروة \" فبذلك كانت عائشة تقول: «حرموا من الرضاعة ما يحرم من النسب»\nوفي لفظ ((استأذن علي أفلح , فلم آذن له. فقال: أتحتجبين"},{"id":"umdat-ahkam:503","bookId":"umdat-ahkam","type":"section","seq":503,"chapter":"كتاب الرضاع","title":"ص: 231","page":"ص0","text":"مني , وأنا عمك؟ فقلت: كيف ذلك؟ قال: أرضعتك امرأة أخي بلبن أخي , قالت: فسألت رسول الله - صلى الله عليه وسلم - فقال: صدق أفلح , ائذني له , تربت يمينك)) أي افتقرت , والعرب تدعو على الرجل , ولا تريد وقوع الأمر به."},{"id":"umdat-ahkam:504","bookId":"umdat-ahkam","type":"section","seq":504,"chapter":"كتاب الرضاع","title":"340- وعنها رضي الله عنها قالت","page":"ص0","text":"وعنها رضي الله عنها قالت ((دخل علي رسول الله - صلى الله عليه وسلم - وعندي رجل , فقال: يا عائشة , من هذا؟ قلت: أخي من الرضاعة. فقال: يا عائشة: انظرن من إخوانكن؟ فإنما الرضاعة من المجاعة)) ."},{"id":"umdat-ahkam:505","bookId":"umdat-ahkam","type":"section","seq":505,"chapter":"كتاب الرضاع","title":"341- عن عقبة بن الحارث - رضي الله عنه -","page":"ص0","text":"عن عقبة بن الحارث - رضي الله عنه - ((أنه تزوج أم يحيى بنت أبي إهاب , فجاءت أمة سوداء , فقالت: قد أرضعتكما , فذكرت ذلك للنبي - صلى الله عليه وسلم - قال: فأعرض عني. قال: فتنحيت , فذكرت ذلك له. قال: كيف؟ وقد زعمت أن قد أرضعتكما)) ."},{"id":"umdat-ahkam:506","bookId":"umdat-ahkam","type":"section","seq":506,"chapter":"كتاب الرضاع","title":"342- عن البراء بن عازب - رضي الله عنه - قال","page":"ص0","text":"عن البراء بن عازب - رضي الله عنه - قال: ((خرج"},{"id":"umdat-ahkam:507","bookId":"umdat-ahkam","type":"section","seq":507,"chapter":"كتاب الرضاع","title":"ص: 232","page":"ص0","text":"رسول الله - صلى الله عليه وسلم - يعني من مكة - فتبعتهم ابنة حمزة , تنادي: يا عم , فتناولها علي فأخذ بيدها , وقال لفاطمة: دونك ابنة عمك , فاحتملتها. فاختصم فيها علي وجعفر وزيد فقال علي: أنا أحق بها , وهي ابنة عمي وقال جعفر: ابنة عمي , وخالتها تحتي. وقال زيد: ابنة أخي. فقضى بها رسول الله - صلى الله عليه وسلم - لخالتها , وقال: الخالة بمنزلة الأم. وقال لعلي: أنت مني , وأنا منك. وقال لجعفر: أشبهت خلقي وخلقي وقال لزيد: أنت أخونا ومولانا)) ."},{"id":"umdat-ahkam:508","bookId":"umdat-ahkam","type":"section","seq":508,"chapter":"كتاب الرضاع","title":"ص: 233","page":"ص0","text":"دونك: خذيها.\nخلقي: الصفات الظاهرة.\nخلقي: الصفات الباطنة.\nمولانا: عتيقنا."},{"id":"umdat-ahkam:509","bookId":"umdat-ahkam","type":"section","seq":509,"chapter":"كتاب القصاص","title":"243- عن عبد الله بن مسعود - رضي الله عنه - قال","page":"ج1 ص233","text":"عن عبد الله بن مسعود - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم - ((لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله وأني رسول الله إلا بإحدى ثلاث: الثيب الزاني , والنفس بالنفس , والتارك لدينه المفارق للجماعة)) . الثيب الزاني: المتزوج الزاني.\nوالنفس بالنفس: قتل من قتل نفسا معصومة ظلما وعدوانا.\nوالتارك لدينه المفارق للجماعة: المرتد."},{"id":"umdat-ahkam:510","bookId":"umdat-ahkam","type":"section","seq":510,"chapter":"كتاب القصاص","title":"344- عن عبد الله بن مسعود - رضي الله عنه - قال","page":"ج1 ص233","text":"عن عبد الله بن مسعود - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((أول ما يقضى بين الناس يوم القيامة في الدماء)) ."},{"id":"umdat-ahkam:511","bookId":"umdat-ahkam","type":"section","seq":511,"chapter":"كتاب القصاص","title":"345- عن سهل بن أبي حثمة - رضي الله عنه - قال","page":"ص0","text":"عن سهل بن أبي حثمة - رضي الله عنه - قال: ((انطلق عبد الله بن سهل ومحيصة بن مسعود إلى خيبر , وهي يومئذ صلح , فتفرقا , فأتى محيصة إلى عبد الله بن سهل - وهو يتشحط في دمه قتيلا - فدفنه , ثم قدم المدينة , فانطلق عبد الرحمن بن سهل ومحيصة وحويصة ابنا مسعود إلى النبي - صلى الله عليه وسلم - فذهب عبد الرحمن يتكلم , فقال النبي - صلى الله عليه وسلم -: كبر , كبر - وهو أحدث القوم - فسكت، فتكلما , فقال: أتحلفون وتستحقون قاتلكم , أو صاحبكم؟ قالوا: وكيف نحلف , ولم نشهد , ولم نر؟ قال: فتبرئكم يهود بخمسين يمينا قالوا: كيف بأيمان قوم كفار؟ فعقله النبي - صلى الله عليه وسلم - من عنده)) .\nوفي حديث حماد بن زيد: ((فقال رسول الله - صلى الله عليه وسلم -: يقسم خمسون منكم على رجل منهم , فيدفع برمته , قالوا: أمر لم نشهده كيف نحلف؟ قالوا: فتبرئكم يهود بأيمان خمسين منهم؟ قالوا:"},{"id":"umdat-ahkam:512","bookId":"umdat-ahkam","type":"section","seq":512,"chapter":"كتاب القصاص","title":"ص: 235","page":"ص0","text":"يا رسول الله , قوم كفار)) .\nوفي حديث سعيد بن عبيد: ((فكره رسول الله - صلى الله عليه وسلم - أن يبطل دمه , فوداه بمائة من إبل الصدقة)) .\nيتشحط: يضطرب ويتخبط.\nكبر , كبر: أي ليتكلم من هو أكبر منك سنا.\nأحدث القوم: أصغرهم.\nفيدفع برمته: الرمة: الحبل. أي أسيرا مقيدا بحبله.\nعقله: أي أعطاه الدية.\nفوداه: دفع ديته."},{"id":"umdat-ahkam:513","bookId":"umdat-ahkam","type":"section","seq":513,"chapter":"كتاب القصاص","title":"346- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه -: ((أن جارية وجد رأسها مرضوضا بين حجرين , فقيل من فعل هذا بك: فلان , فلان؟ حتى ذكر يهودي , فأومأت برأسها , فأخذ اليهودي فاعترف , فأمر النبي - صلى الله عليه وسلم - أن يرض رأسه بين حجرين)) ."},{"id":"umdat-ahkam:514","bookId":"umdat-ahkam","type":"section","seq":514,"chapter":"كتاب القصاص","title":"347- ولمسلم والنسائي عن أنس - رضي الله عنه -","page":"ص0","text":"ولمسلم والنسائي عن أنس - رضي الله عنه - ((أن يهوديا قتل جارية على أوضاح , فأقاده رسول الله - صلى الله عليه وسلم -)) ."},{"id":"umdat-ahkam:515","bookId":"umdat-ahkam","type":"section","seq":515,"chapter":"كتاب القصاص","title":"ص: 236","page":"ص0","text":"مرضوضا: مدقوقا.\nفأومأت: أشارت.\nأوضاح: نوع من الحلي من الفضة\nأقاده: قتله."},{"id":"umdat-ahkam:516","bookId":"umdat-ahkam","type":"section","seq":516,"chapter":"كتاب القصاص","title":"348- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((لما فتح الله - تعالى - على رسوله - صلى الله عليه وسلم - مكة قتلت هذيل رجلا من بني ليث بقتيل كان لهم في الجاهلية , فقام رسول الله - صلى الله عليه وسلم - فقال: إن الله عز وجل قد حبس عن مكة الفيل , وسلط عليها رسوله والمؤمنين , وإنها لم تحل لأحد كان قبلي , ولا تحل لأحد بعدي , وإنما أحلت لي ساعة من نهار , وإنها ساعتي هذه: حرام , لا يعضد شجرها , ولا يختلى خلاها , ولا يعضد شوكها , ولا تلتقط ساقطتها إلا لمنشد. ومن قتل له قتيل: فهو بخير النظرين: إما أن يقتل , وإما أن يودي , فقام رجل من أهل اليمن - يقال له: أبو شاه فقال: يا رسول الله , اكتبوا لي فقال رسول الله - صلى الله عليه وسلم -:"},{"id":"umdat-ahkam:517","bookId":"umdat-ahkam","type":"section","seq":517,"chapter":"كتاب القصاص","title":"ص: 237","page":"ص0","text":"اكتبوا لأبي شاه , ثم قام العباس فقال: يا رسول الله , إلا الاذخر , فإنا نجعله في بيوتنا وقبورنا. فقال رسول الله - صلى الله عليه وسلم -: إلا الإذخر)) .\nلا يعضد: لايقطع.\nلا يختلى خلاها: هو الرطب من الحشيش: أي لايجز ولايقطع.\nلمنشد: هو المعرف على اللقطة.\nبخير النظرين: أخذ الدية أوالقصاص.\nأن يودي: أي يعطي القاتل أوأولياؤه الدية لأولياء المقتول.\nالإذخر: نبت طيب الرائحة."},{"id":"umdat-ahkam:518","bookId":"umdat-ahkam","type":"section","seq":518,"chapter":"كتاب القصاص","title":"349- عن عمر بن الخطاب - رضي الله عنه - أنه استشار الناس في إملاص المرأة","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - أنه استشار الناس في إملاص المرأة، فقال المغيرة بن شعبة: ((شهدت النبي - صلى الله عليه وسلم - قضى فيه بغرة - عبد أو أمة - فقال: لتأتين بمن يشهد معك , فشهد معه محمد بن مسلمة)) إملاص المرأة: أن تلقي جنينها ميتا. أه\nإملاص المرأة: هو أن تضع المرأة ولدها قبل أوانه.\nبغرة: العبد والأمة."},{"id":"umdat-ahkam:519","bookId":"umdat-ahkam","type":"section","seq":519,"chapter":"كتاب القصاص","title":"350- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: ((اقتتلت امرأتان من"},{"id":"umdat-ahkam:520","bookId":"umdat-ahkam","type":"section","seq":520,"chapter":"كتاب القصاص","title":"ص: 238","page":"ص0","text":"هذيل. فرمت إحداهما الأخرى بحجر , فقتلتها وما في بطنها فاختصموا إلى النبي - صلى الله عليه وسلم - فقضى رسول الله - صلى الله عليه وسلم -: أن دية جنينها غرة - عبد , أو وليدة - وقضى بدية المرأة على عاقلتها , وورثها ولدها ومن معهم , فقام حمل بن النابغة الهذلي , فقال: يا رسول الله , كيف أغرم من لاشرب ولا أكل , ولا نطق ولا استهل , فمثل ذلك يطل؟ فقال رسول الله - صلى الله عليه وسلم -: إنما هو من إخوان الكهان)) من أجل سجعه الذي سجع.\nعاقلتها: العاقلة هم الأقارب الذين يقومون بدفع دية الخطأ عن قريبهم القاتل.\nولااستهل: الاستهلال: رفع الصوت\nيطل: يهدر ويلغى.\nالسجع: هو الإتيان بفقرات الكلام منتهية بفواصل."},{"id":"umdat-ahkam:521","bookId":"umdat-ahkam","type":"section","seq":521,"chapter":"كتاب القصاص","title":"351- عن عمران بن حصين - رضي الله عنه -","page":"ص0","text":"عن عمران بن حصين - رضي الله عنه - ((أن رجلا عض يد رجل , فنزع يده من فيه , فوقعت ثنيته , فاختصما إلى النبي - صلى الله عليه وسلم - فقال: يعض أحدكم أخاه كما يعض الفحل , لا دية لك)) ."},{"id":"umdat-ahkam:522","bookId":"umdat-ahkam","type":"section","seq":522,"chapter":"كتاب القصاص","title":"352- عن الحسن بن أبي الحسن البصري - رحمه الله تعالى - قال","page":"ص0","text":"عن الحسن بن أبي الحسن البصري - رحمه الله تعالى - قال: حدثنا"},{"id":"umdat-ahkam:523","bookId":"umdat-ahkam","type":"section","seq":523,"chapter":"كتاب القصاص","title":"ص: 239","page":"ص0","text":"جندب في هذا المسجد , وما نسينا منه حديثا , وما نخشى أن يكون جندب كذب على رسول الله - صلى الله عليه وسلم - قال: قال رسول الله - صلى الله عليه وسلم -: ((كان فيمن كان قبلكم رجل به جرح فجزع , فأخذ سكينا فحز بها يده , فما رقأ الدم حتى مات. قال الله عز وجل: عبدي بادرني بنفسه , حرمت عليه الجنة)) ."},{"id":"umdat-ahkam:524","bookId":"umdat-ahkam","type":"section","seq":524,"chapter":"كتاب القصاص","title":"ص: 241","page":"ص0","text":"فحز يده: قطعها.\nفما رقأ الدم: أي ماانقطع دمه حتى مات."},{"id":"umdat-ahkam:525","bookId":"umdat-ahkam","type":"section","seq":525,"chapter":"كتاب الحدود","title":"353- عن أنس بن مالك - رضي الله عنه - قال","page":"ج1 ص241","text":"عن أنس بن مالك - رضي الله عنه - قال: ((قدم ناس من عكل - أو عرينة - فاجتووا المدينة , فأمر لهم النبي - صلى الله عليه وسلم - بلقاح , وأمرهم أن يشربوا من أبوالها وألبانها فانطلقوا. فلما صحوا قتلوا راعي النبي - صلى الله عليه وسلم - واستاقوا النعم، فجاء الخبر في أول النهار , فبعث في آثارهم. فلما ارتفع النهار جيء بهم , فأمر بهم: فقطعت أيديهم وأرجلهم من خلاف , وسمرت أعينهم , وتركوا في الحرة"},{"id":"umdat-ahkam:526","bookId":"umdat-ahkam","type":"section","seq":526,"chapter":"كتاب الحدود","title":"ص: 242","page":"ج1 ص241","text":"يستسقون , فلا يسقون. قال أبو قلابة: فهؤلاء سرقوا وقتلوا وكفروا بعد إيمانهم , وحاربوا الله ورسوله)) . أخرجه الجماعة. اجتويت البلاد إذا كرهتها وإن كانت موافقة. واستوبأتها إذا لم توافقك.\nعكل: قبيلة عدنانية.\nعرينة: قبيلة قحطانية.\nفاجتووا المدينة: كرهوها لداء أصابهم في أجوافهم.\nلقاح: ناقة حلوب.\nالنعم: واحد الأنعام، وهي الإبل.\nسمرت أعينهم: أي كحلت أعينهم بمسامير محماة بالنار.\nمن خلاف: تقطع اليد اليمنى والرجل اليسرى.\nالحرة: الأرض التي تعلوها حجارة سود.\nيستسقون: يطلبون الماء."},{"id":"umdat-ahkam:527","bookId":"umdat-ahkam","type":"section","seq":527,"chapter":"كتاب الحدود","title":"354- عن عبيد الله بن عبد الله بن عتبة بن مسعود عن أبي هريرة وزيد بن خالد الجهني رضي الله عنهما","page":"ص0","text":"عن عبيد الله بن عبد الله بن عتبة بن مسعود عن أبي هريرة وزيد بن خالد الجهني رضي الله عنهما , أنهما قالا: ((إن رجلا من الأعراب أتى رسول - صلى الله عليه وسلم - فقال: يا رسول الله , أنشدك الله إلا قضيت بيننا بكتاب الله. فقال الخصم الآخر - وهو أفقه منه - نعم , فاقض بيننا بكتاب الله , وأذن لي. فقال النبي - صلى الله عليه وسلم -: قل , فقال: إن ابني كان عسيفا على هذا , فزنى بامرأته , وإني أخبرت أن على ابني الرجم , فافتديت منه بمائة شاة ووليدة , فسألت أهل العلم"},{"id":"umdat-ahkam:528","bookId":"umdat-ahkam","type":"section","seq":528,"chapter":"كتاب الحدود","title":"ص: 243","page":"ص0","text":"فأخبروني أنما على ابني جلد مائة وتغريب عام , وأن على امرأة هذا الرجم. فقال رسول الله - صلى الله عليه وسلم -: والذي نفسي بيده لأقضين بينكما بكتاب الله , الوليدة والغنم رد عليك وعلى ابنك جلد مائة وتغريب عام. واغد يا أنيس - لرجل من أسلم - على امرأة هذا , فإن اعترفت فارجمها , فغدا عليها , فاعترفت , فأمر بها رسول الله - صلى الله عليه وسلم - فرجمت)) .\nالعسيف: الأجير. أه\nأنشدك الله: أسألك بالله."},{"id":"umdat-ahkam:529","bookId":"umdat-ahkam","type":"section","seq":529,"chapter":"كتاب الحدود","title":"355- عن عبيد الله بن عقبة بن مسعود عن أبي هريرة وزيد بن خالد الجهني رضي الله عنهما قالا","page":"ص0","text":"عن عبيد الله بن عقبة بن مسعود عن أبي هريرة وزيد بن خالد الجهني رضي الله عنهما قالا:\n((سئل النبي - صلى الله عليه وسلم - عن الأمة إذا زنت ولم تحصن؟ قال: إن زنت فاجلدوها , ثم إن زنت فاجلدوها , ثم إن زنت فاجلدوها , ثم بيعوها ولو بضفير)) .\nقال ابن شهاب: «ولاأدري، أبعد الثالثة أو الرابعة» . والضفير: الحبل."},{"id":"umdat-ahkam:530","bookId":"umdat-ahkam","type":"section","seq":530,"chapter":"كتاب الحدود","title":"356- عن أبي هريرة رضي الله عنه أنه قال","page":"ص0","text":"عن أبي هريرة رضي الله عنه أنه قال: ((أتى رجل من المسلمين رسول الله - صلى الله عليه وسلم - وهو في المسجد - فناداه: يا رسول الله , إني زنيت , فأعرض عنه. فتنحى تلقاء وجهه فقال: يا رسول الله , إني زنيت , فأعرض عنه , حتى ثنى ذلك عليه أربع مرات. فلما شهد على نفسه أربع شهادات: دعاه رسول الله - صلى الله عليه وسلم - , فقال: أبك جنون؟ قال: لا. قال: فهل أحصنت؟ قال: نعم. فقال رسول الله - صلى الله عليه وسلم -: اذهبوا به فارجموه)) .\nقال ابن شهاب: فأخبرني أبو سلمة بن عبد الرحمن. سمع جابر بن عبد الله يقول «كنت فيمن رجمه , فرجمناه بالمصلي , فلما أذلقته الحجارة هرب , فأدركناه بالحرة , فرجمناه» .\nالرجل هو ماعز بن مالك. وروى قصته جابر بن عبد الله وعبد الله بن عباس وأبو سعيد الخدري وبريدة بن الحصيب الأسلمي.\nهل أحصنت: هل تزوجت.\nأذلقته الحجارة: أصابته بحدها فأوجعته."},{"id":"umdat-ahkam:531","bookId":"umdat-ahkam","type":"section","seq":531,"chapter":"كتاب الحدود","title":"357- عن عبد الله بن عمر رضي الله عنهما أنه قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما أنه قال: ((إن اليهود جاءوا إلى رسول الله - صلى الله عليه وسلم - فذكروا له: أن امرأة منهم ورجلا زنيا. فقال"},{"id":"umdat-ahkam:532","bookId":"umdat-ahkam","type":"section","seq":532,"chapter":"كتاب الحدود","title":"ص: 245","page":"ص0","text":"لهم رسول الله - صلى الله عليه وسلم -: ما تجدون في التوراة , في شأن الرجم؟ فقالوا: نفضحهم ويجلدون. قال عبد الله بن سلام: كذبتم , فيها آية الرجم , فأتوا بالتوراة فنشروها , فوضع أحدهم يده على آية الرجم فقرأ ما قبلها وما بعدها. فقال له عبد الله بن سلام: ارفع يدك. فرفع يده , فإذا فيها آية الرجم , فقال: صدق يا محمد , فأمر بهما النبي - صلى الله عليه وسلم - فرجما. قال: فرأيت الرجل: يجنأ على المرأة يقيها الحجارة)) ."},{"id":"umdat-ahkam:533","bookId":"umdat-ahkam","type":"section","seq":533,"chapter":"كتاب الحدود","title":"ص: 246","page":"ص0","text":"الرجل الذي وضع يده على آية الرجم عبد الله بن صوريا.\nيجنأ على المرأة: يميل عليها وينكب."},{"id":"umdat-ahkam:534","bookId":"umdat-ahkam","type":"section","seq":534,"chapter":"كتاب الحدود","title":"358- عن أبي هريرة - رضي الله عنه -","page":"ص0","text":"عن أبي هريرة - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - قال: ((لو أن رجلا - أو قال: امرأ - اطلع عليك بغير إذنك , فحذفته بحصاة , ففقأت عينه: ما كان عليك جناح)) .\nحذفته: قذفته.\nجناح: إثم ولاقصاص."},{"id":"umdat-ahkam:535","bookId":"umdat-ahkam","type":"section","seq":535,"chapter":"كتاب الحدود","title":"359- عن عبد الله بن عمر رضي الله تعالى عنهما","page":"ج1 ص246","text":"عن عبد الله بن عمر رضي الله تعالى عنهما: ((أن النبي - صلى الله عليه وسلم - قطع في مجن قيمته)) - وفي لفظ: ((ثمنه - ثلاثة دراهم)) .\nالمجن: هو الترس الذي يتقى به ضرب السيف.","bab":"باب حد السرقة"},{"id":"umdat-ahkam:536","bookId":"umdat-ahkam","type":"section","seq":536,"chapter":"كتاب الحدود","title":"360- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: أنها سمعت رسول الله - صلى الله عليه وسلم - يقول: ((تقطع اليد في ربع دينار فصاعدا)) .","bab":"باب حد السرقة"},{"id":"umdat-ahkam:537","bookId":"umdat-ahkam","type":"section","seq":537,"chapter":"كتاب الحدود","title":"361- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها ((أن قريشا أهمهم شأن المخزومية التي سرقت , فقالوا: من يكلم فيها رسول الله - صلى الله عليه وسلم -؟ فقالوا: ومن يجترئ عليه إلا أسامة بن زيد حب رسول الله - صلى الله عليه وسلم - فكلمه أسامة , فقال: أتشفع في حد من حدود الله؟ ثم قام فاختطب , فقال: إنما أهلك الذين من قبلكم أنهم كانوا إذا سرق فيهم الشريف تركوه , وإذا سرق فيهم الضعيف أقاموا عليه الحد , وأيم الله: لو أن فاطمة بنت محمد سرقت لقطعت يدها)) .\nوفي لفظ ((كانت امرأة تستعير المتاع وتجحده , فأمر النبي - صلى الله عليه وسلم - بقطع يدها)) .","bab":"باب حد السرقة"},{"id":"umdat-ahkam:538","bookId":"umdat-ahkam","type":"section","seq":538,"chapter":"كتاب الحدود","title":"362- عن أنس بن مالك - رضي الله عنه -","page":"ج1 ص247","text":"عن أنس بن مالك - رضي الله عنه - ((أن النبي - صلى الله عليه وسلم - أتي برجل قد شرب الخمر, فجلده بجريدة نحو أربعين))","bab":"باب حد الخمر"},{"id":"umdat-ahkam:539","bookId":"umdat-ahkam","type":"section","seq":539,"chapter":"كتاب الحدود","title":"363- عن أبي بردة هانئ بن نيار البلوي - رضي الله عنه -","page":"ص0","text":"عن أبي بردة هانئ بن نيار البلوي - رضي الله عنه -: أنه سمع رسول الله - صلى الله عليه وسلم - يقول: ((لا يجلد فوق عشرة أسواط إلا في حد من حدود الله)) .","bab":"باب حد الخمر"},{"id":"umdat-ahkam:540","bookId":"umdat-ahkam","type":"section","seq":540,"chapter":"كتاب الأيمان والنذور","title":"364- عن عبد الرحمن بن سمرة - رضي الله عنه - قال","page":"ج1 ص249","text":"عن عبد الرحمن بن سمرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((يا عبد الرحمن بن سمرة , لا تسأل الإمارة , فإنك إن أعطيتها عن مسألة وكلت إليها , وإن أعطيتها عن غير مسألة أعنت عليها , وإذا حلفت على يمين فرأيت غيرها خيرا منها , فكفر عن يمينك , وأت الذي هو خير)) ."},{"id":"umdat-ahkam:541","bookId":"umdat-ahkam","type":"section","seq":541,"chapter":"كتاب الأيمان والنذور","title":"365- عن أبي موسى - رضي الله عنه - قال","page":"ص0","text":"عن أبي موسى - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إني والله - إن شاء الله - لا أحلف على يمين , فأرى غيرها خيرا منها إلا أتيت الذي هو خير , وتحللتها)) ."},{"id":"umdat-ahkam:542","bookId":"umdat-ahkam","type":"section","seq":542,"chapter":"كتاب الأيمان والنذور","title":"366- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((إن الله ينهاكم أن تحلفوا بآبائكم)) .\nولمسلم: ((فمن كان حالفا فليحلف بالله أو ليصمت)) .\nوفي رواية قال عمر «فوالله ما حلفت بها منذ سمعت رسول الله - صلى الله عليه وسلم - ينهى عنها , ذاكرا ولا آثرا»\n(يعني: حاكيا عن غيري أنه حلف بها) .\nذاكرا: عامدا."},{"id":"umdat-ahkam:543","bookId":"umdat-ahkam","type":"section","seq":543,"chapter":"كتاب الأيمان والنذور","title":"367- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ج1 ص251","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((قال سليمان بن داود عليهما السلام: لأطوفن الليلة على سبعين امرأة , تلد كل امرأة منهن غلاما يقاتل في سبيل الله , فقيل له: قل: إن شاء الله , فلم يقل , فطاف بهن , فلم تلد منهن إلا امرأة واحدة: نصف إنسان. قال: فقال رسول الله - صلى الله عليه وسلم -: لو قال إن شاء الله لم يحنث , وكان دركا لحاجته)) . قوله: (فقيل له: قل: إن شاء الله) يعني قال له الملك.\nلأطوفن: المراد بذلك المجامعة.\nدركا لحاجته: أدركها ووصل إليها."},{"id":"umdat-ahkam:544","bookId":"umdat-ahkam","type":"section","seq":544,"chapter":"كتاب الأيمان والنذور","title":"368- عن عبد الله بن مسعود - رضي الله عنه - قال","page":"ص0","text":"عن عبد الله بن مسعود - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((من حلف على يمين صبر يقتطع بها مال امرئ"},{"id":"umdat-ahkam:545","bookId":"umdat-ahkam","type":"section","seq":545,"chapter":"كتاب الأيمان والنذور","title":"ص: 252","page":"ص0","text":"مسلم , هو فيها فاجر , لقي الله وهو عليه غضبان)) . ونزلت: ((إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا)) إلى آخر الآية \".\nيمين صبر: هي اليمين الغموس، وهي اليمين التي ألزم بها وحبس عليها، وكانت لازمة من جهة الحكم.\nفاجر: كاذب."},{"id":"umdat-ahkam:546","bookId":"umdat-ahkam","type":"section","seq":546,"chapter":"كتاب الأيمان والنذور","title":"369- عن الأشعث بن قيس - رضي الله عنه - قال","page":"ص0","text":"عن الأشعث بن قيس - رضي الله عنه - قال: ((كان بيني وبين رجل خصومة في بئر فاختصمنا إلى رسول الله - صلى الله عليه وسلم -، فقال رسول الله - صلى الله عليه وسلم -: شاهداك أو يمينه، قلت: إذا يحلف ولا يبالي. فقال رسول الله - صلى الله عليه وسلم -: من حلف على يمين صبر يقتطع بها مال امرئ مسلم , هو فيها فاجر , لقي الله عز وجل وهو عليه غضبان)) ."},{"id":"umdat-ahkam:547","bookId":"umdat-ahkam","type":"section","seq":547,"chapter":"كتاب الأيمان والنذور","title":"370- عن ثابت بن الضحاك الأنصاري - رضي الله عنه - أنه بايع رسول الله - صلى الله عليه وسلم - تحت","page":"ص0","text":"عن ثابت بن الضحاك الأنصاري - رضي الله عنه - أنه بايع رسول الله - صلى الله عليه وسلم - تحت الشجرة , وأن رسول الله - صلى الله عليه وسلم - قال: ((من حلف على يمين بملة غير الإسلام , كاذبا متعمدا , فهو كما قال , ومن قتل نفسه بشيء عذب به يوم القيامة , وليس على رجل نذر فيما لا يملك))"},{"id":"umdat-ahkam:548","bookId":"umdat-ahkam","type":"section","seq":548,"chapter":"كتاب الأيمان والنذور","title":"ص: 253","page":"ص0","text":"وفي رواية: ((ولعن المؤمن كقتله)) . وفي رواية: ((من ادعى دعوى كاذبة ليتكثر بها , لم يزده الله عز وجل إلا قلة)) ."},{"id":"umdat-ahkam:549","bookId":"umdat-ahkam","type":"section","seq":549,"chapter":"كتاب الأيمان والنذور","title":"371- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ج1 ص253","text":"عن عمر بن الخطاب - رضي الله عنه - قال: ((قلت: يا رسول الله , إني كنت نذرت في الجاهلية أن أعتكف ليلة - وفي رواية: يوما - في المسجد الحرام؟ قال: فأوف بنذرك)) .","bab":"باب النذر"},{"id":"umdat-ahkam:550","bookId":"umdat-ahkam","type":"section","seq":550,"chapter":"كتاب الأيمان والنذور","title":"372- عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم -","page":"ج1 ص253","text":"عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم - ((أنه","bab":"باب النذر"},{"id":"umdat-ahkam:551","bookId":"umdat-ahkam","type":"section","seq":551,"chapter":"كتاب الأيمان والنذور","title":"ص: 254","page":"ج1 ص253","text":"نهى عن النذر , وقال: إن النذر لا يأتي بخير. وإنما يستخرج به من البخيل)) .","bab":"باب النذر"},{"id":"umdat-ahkam:552","bookId":"umdat-ahkam","type":"section","seq":552,"chapter":"كتاب الأيمان والنذور","title":"373- عن عقبة بن عامر - رضي الله عنه - قال","page":"ص0","text":"عن عقبة بن عامر - رضي الله عنه - قال: ((نذرت أختي أن تمشي إلى بيت الله الحرام حافية فأمرتني أن أستفتي لها رسول الله - صلى الله عليه وسلم - فاستفتيته فقال: لتمش ولتركب)) .","bab":"باب النذر"},{"id":"umdat-ahkam:553","bookId":"umdat-ahkam","type":"section","seq":553,"chapter":"كتاب الأيمان والنذور","title":"374- عن عبد الله بن عباس رضي الله عنهما أنه قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما أنه قال: ((استفتى سعد بن عبادة رسول الله - صلى الله عليه وسلم - في نذر كان على أمه , توفيت قبل أن تقضيه , قال رسول الله - صلى الله عليه وسلم -: فاقضه عنها)) .","bab":"باب النذر"},{"id":"umdat-ahkam:554","bookId":"umdat-ahkam","type":"section","seq":554,"chapter":"كتاب الأيمان والنذور","title":"375- عن كعب بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن كعب بن مالك - رضي الله عنه - قال: ((قلت: يا رسول الله , إن من توبتي: أن أنخلع من مالي , صدقة إلى الله وإلى رسوله فقال رسول الله - صلى الله عليه وسلم -: أمسك عليك بعض مالك فهو خير لك)) .","bab":"باب النذر"},{"id":"umdat-ahkam:555","bookId":"umdat-ahkam","type":"section","seq":555,"chapter":"كتاب الأيمان والنذور","title":"376- عن عائشة رضي الله عنها قالت","page":"ج1 ص255","text":"عن عائشة رضي الله عنها قالت: قال رسول الله - صلى الله عليه وسلم -: ((من أحدث في أمرنا هذا ما ليس منه فهو رد)) .\nوفي لفظ ((من عمل عملا ليس عليه أمرنا فهو رد)) .\nفهو رد: أي مردود.","bab":"باب القضاء"},{"id":"umdat-ahkam:556","bookId":"umdat-ahkam","type":"section","seq":556,"chapter":"كتاب الأيمان والنذور","title":"377- عن عائشة رضي الله عنها قالت","page":"ص0","text":"عن عائشة رضي الله عنها قالت: ((دخلت هند بنت عتبة - امرأة أبي سفيان - على رسول الله - صلى الله عليه وسلم - فقالت: يا رسول الله , إن أبا سفيان رجل شحيح , لا يعطيني من النفقة ما يكفيني ويكفي بني , إلا ما أخذت من ماله بغير علمه. فهل علي في ذلك من جناح؟ فقال رسول الله - صلى الله عليه وسلم -: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك)) .","bab":"باب القضاء"},{"id":"umdat-ahkam:557","bookId":"umdat-ahkam","type":"section","seq":557,"chapter":"كتاب الأيمان والنذور","title":"378- عن أم سلمة رضي الله عنها","page":"ص0","text":"عن أم سلمة رضي الله عنها ((أن رسول الله - صلى الله عليه وسلم - سمع جلبة خصم بباب حجرته , فخرج إليهم , فقال: ألا إنما أنا بشر , وإنما يأتيني الخصم , فلعل بعضكم أن يكون أبلغ من بعض , فأحسب أنه صادق , فأقضي له. فمن قضيت له بحق مسلم فإنما هي قطعة من نار , فليحملها أو يذرها)) .\nالجلبة: اختلاط الأصوات.\nأبلغ: أفصح.","bab":"باب القضاء"},{"id":"umdat-ahkam:558","bookId":"umdat-ahkam","type":"section","seq":558,"chapter":"كتاب الأيمان والنذور","title":"379- عن عبد الرحمن بن أبي بكرة رضي الله عنهما قال","page":"ص0","text":"عن عبد الرحمن بن أبي بكرة رضي الله عنهما قال: ((كتب أبي - أو كتبت له - إلى ابنه عبد الله بن أبي بكرة وهو قاض بسجستان: أن لا تحكم بين اثنين وأنت غضبان. فإني سمعت رسول الله - صلى الله عليه وسلم - يقول: لايحكم أحد بين اثنين وهو غضبان)) .\nوفي رواية: ((لا يقضين حاكم بين اثنين وهو غضبان)) .","bab":"باب القضاء"},{"id":"umdat-ahkam:559","bookId":"umdat-ahkam","type":"section","seq":559,"chapter":"كتاب الأيمان والنذور","title":"380- عن أبي بكرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي بكرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((ألا أنبئكم بأكبر الكبائر؟ - ثلاثا - قلنا: بلى يا رسول الله , قال: الإشراك بالله وعقوق الوالدين، وكان متكئا فجلس , وقال: ألا وقول الزور , وشهادة الزور , فما زال يكررها حتى قلنا: ليته سكت)) .","bab":"باب القضاء"},{"id":"umdat-ahkam:560","bookId":"umdat-ahkam","type":"section","seq":560,"chapter":"كتاب الأيمان والنذور","title":"381- عن ابن عباس رضي الله عنهما","page":"ص0","text":"عن ابن عباس رضي الله عنهما: أن النبي - صلى الله عليه وسلم - قال: ((لو","bab":"باب القضاء"},{"id":"umdat-ahkam:561","bookId":"umdat-ahkam","type":"section","seq":561,"chapter":"كتاب الأيمان والنذور","title":"ص: 258","page":"ص0","text":"يعطى الناس بدعواهم لادعى ناس دماء رجال وأموالهم , ولكن اليمين على المدعى عليه)) .","bab":"باب القضاء"},{"id":"umdat-ahkam:562","bookId":"umdat-ahkam","type":"section","seq":562,"chapter":"كتاب الأطعمة","title":"382- عن النعمان بن بشير - رضي الله عنه - قال","page":"ج1 ص259","text":"عن النعمان بن بشير - رضي الله عنه - قال: سمعت رسول الله - صلى الله عليه وسلم - يقول - وأهوى النعمان بإصبعيه إلى أذنيه -: ((إن الحلال بين , والحرام بين وبينهما مشتبهات , لا يعلمهن كثير من الناس , فمن اتقى الشبهات: استبرأ لدينه وعرضه , ومن وقع في الشبهات: وقع في الحرام , كالراعي يرعى حول الحمى يوشك أن يرتع فيه , ألا وإن لكل ملك حمى , ألا وإن حمى الله محارمه , ألا وإن في الجسد مضغة إذا صلحت صلح الجسد كله وإذا فسدت فسد الجسد كله. ألا وهي القلب))"},{"id":"umdat-ahkam:563","bookId":"umdat-ahkam","type":"section","seq":563,"chapter":"كتاب الأطعمة","title":"ص: 260","page":"ج1 ص259","text":"بين: ظاهر وواضح، وهو ما نص الله تعالى ورسوله - صلى الله عليه وسلم - أو أجمع المسلمون على تحليله بعينه أو تحريمه بعينهمشتبهات: جمع مشتبه، وهو مشكل؛ لما فيه من عدم الوضوح في الحل والحرمة.\nاتق الشبهات: ابتعد عنها.\nاستبرأ لدينه وعرضه: طلب البراءة لدينه من النقص ولعرضه من الطعن.\nوقع في الشبهات: اجترأ على الوقوع في الشبهات، التي أشبهت الحلال من وجه والحرام من وجه آخر.\nالحمى: المحمي وهو ما يحميه الخليفة أو نائبه من الأرض المباحة لدواب المجاهدين، ويمنع غيرهم عنه\nيوشك: يقرب.\nأن يرتع فيه: أن تأكل منه ماشيته وتقيم فيه.\nمحارمه: المعاصي التي حرمها الله تعالى كالقتل والسرقة.\nمضغة: قطعة من اللحم قدر ما يمضغ في الفم."},{"id":"umdat-ahkam:564","bookId":"umdat-ahkam","type":"section","seq":564,"chapter":"كتاب الأطعمة","title":"383- عن أنس بن مالك رضي الله عنه قال","page":"ص0","text":"عن أنس بن مالك رضي الله عنه قال: ((أنفجنا أرنبا بمر الظهران فسعى القوم فلغبوا , وأدركتها فأخذتها فأتيت بها أبا طلحة , فذبحها وبعث إلى رسول الله - صلى الله عليه وسلم - بوركها وفخذيها. فقبله)) . لغبوا: أعيوا. أه\nأنفجنا: أثرنا."},{"id":"umdat-ahkam:565","bookId":"umdat-ahkam","type":"section","seq":565,"chapter":"كتاب الأطعمة","title":"384- عن أسماء بنت أبي بكر رضي الله عنه قالت","page":"ص0","text":"عن أسماء بنت أبي بكر رضي الله عنه قالت: ((نحرنا على عهد رسول الله - صلى الله عليه وسلم - فرسا فأكلناه)) . وفي رواية ((ونحن بالمدينة)) ."},{"id":"umdat-ahkam:566","bookId":"umdat-ahkam","type":"section","seq":566,"chapter":"كتاب الأطعمة","title":"385- عن جابر بن عبد الله رضي الله عنهما","page":"ص0","text":"عن جابر بن عبد الله رضي الله عنهما: ((أن النبي - صلى الله عليه وسلم - نهى عن لحوم الحمر الأهلية، وأذن في لحوم الخيل)) .\nولمسلم وحده قال ((أكلنا زمن خيبر الخيل وحمر الوحش ,"},{"id":"umdat-ahkam:567","bookId":"umdat-ahkam","type":"section","seq":567,"chapter":"كتاب الأطعمة","title":"ص: 261","page":"ص0","text":"ونهى النبي - صلى الله عليه وسلم - عن الحمار الأهلي)) ."},{"id":"umdat-ahkam:568","bookId":"umdat-ahkam","type":"section","seq":568,"chapter":"كتاب الأطعمة","title":"386- عن عبد الله بن أبي أوفى - رضي الله عنه - قال","page":"ج1 ص260","text":"عن عبد الله بن أبي أوفى - رضي الله عنه - قال: ((أصابتنا مجاعة ليالي خيبر , فلما كان يوم خيبر: وقعنا في الحمر الأهلية , فانتحرناها فلما غلت بها القدور: نادى منادي رسول الله - صلى الله عليه وسلم - أن أكفئوا القدور , وربما قال: ولا تأكلوا من لحوم الحمر شيئا)) ."},{"id":"umdat-ahkam:569","bookId":"umdat-ahkam","type":"section","seq":569,"chapter":"كتاب الأطعمة","title":"387- عن أبي ثعلبة - رضي الله عنه - قال","page":"ص0","text":"عن أبي ثعلبة - رضي الله عنه - قال: ((حرم رسول الله - صلى الله عليه وسلم - لحوم الحمر الأهلية)) ."},{"id":"umdat-ahkam:570","bookId":"umdat-ahkam","type":"section","seq":570,"chapter":"كتاب الأطعمة","title":"388- عن ابن عباس رضي الله عنهما قال","page":"ص0","text":"عن ابن عباس رضي الله عنهما قال: ((دخلت أنا وخالد بن الوليد مع رسول الله - صلى الله عليه وسلم - بيت ميمونة , فأتي بضب محنوذ فأهوى إليه رسول الله - صلى الله عليه وسلم - بيده , فقال بعض النسوة اللاتي في بيت ميمونة: أخبروا رسول الله بما يريد أن يأكل فرفع رسول الله - صلى الله عليه وسلم - يده , فقلت: أحرام هو يا رسول الله؟ قال: لا , ولكنه لم يكن بأرض قومي , فأجدني أعافه , قال خالد: فاجتررته , فأكلته. والنبي - صلى الله عليه وسلم - ينظر)) ."},{"id":"umdat-ahkam:571","bookId":"umdat-ahkam","type":"section","seq":571,"chapter":"كتاب الأطعمة","title":"ص: 262","page":"ص0","text":"المحنوذ: المشوي بالرصف وهي الحجارة المحماة. أه\nالضب: حيوان صغير معروف خشن الذنب.\nأعافه: أكره أكله."},{"id":"umdat-ahkam:572","bookId":"umdat-ahkam","type":"section","seq":572,"chapter":"كتاب الأطعمة","title":"389- عن عبد الله بن أبي أوفى - رضي الله عنه - قال","page":"ص0","text":"عن عبد الله بن أبي أوفى - رضي الله عنه - قال: ((غزونا مع رسول الله - صلى الله عليه وسلم - سبع غزوات , نأكل الجراد))"},{"id":"umdat-ahkam:573","bookId":"umdat-ahkam","type":"section","seq":573,"chapter":"كتاب الأطعمة","title":"390- عن زهدم بن مضرب الجرمي قال","page":"ص0","text":"عن زهدم بن مضرب الجرمي قال: ((كنا عند أبي موسى الأشعري. فدعا بمائدة , وعليها لحم دجاج , فدخل رجل من بني تيم الله , أحمر , شبيه بالموالي فقال: هلم، فتلكأ فقال: هلم , فإني رأيت رسول الله - صلى الله عليه وسلم - يأكل منه)) .\nفتلكأ: تردد."},{"id":"umdat-ahkam:574","bookId":"umdat-ahkam","type":"section","seq":574,"chapter":"كتاب الأطعمة","title":"391- عن ابن عباس رضي الله عنهما أن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن ابن عباس رضي الله عنهما أن النبي - صلى الله عليه وسلم - قال: ((إذا أكل أحدكم طعاما فلا يمسح يده حتى يلعقها , أو يلعقها)) ."},{"id":"umdat-ahkam:575","bookId":"umdat-ahkam","type":"section","seq":575,"chapter":"كتاب الأطعمة","title":"392- عن أبي ثعلبة الخشني رضي الله عنه قال","page":"ج1 ص263","text":"عن أبي ثعلبة الخشني رضي الله عنه قال ((أتيت رسول الله - صلى الله عليه وسلم - فقلت: يا رسول الله , إنا بأرض قوم أهل كتاب، أفنأكل في آنيتهم؟ وفي أرض صيد , أصيد بقوسي وبكلبي الذي ليس بمعلم , وبكلبي المعلم. فما يصلح لي؟ قال: أما ما ذكرت - يعني من آنية أهل الكتاب -: فإن وجدتم غيرها فلا تأكلوا فيها , وإن لم تجدوا فاغسلوها , وكلوا فيها. وما صدت بقوسك , فذكرت اسم الله عليه فكل , وما صدت بكلبك المعلم , فذكرت اسم الله عليه فكل , وما صدت بكلبك غير المعلم فأدركت ذكاته فكل)) .\nبقوسي: آلة رمي قديمة معروفة.\nكلبي المعلم: المدرب.","bab":"باب الصيد"},{"id":"umdat-ahkam:576","bookId":"umdat-ahkam","type":"section","seq":576,"chapter":"كتاب الأطعمة","title":"393- عن همام بن الحارث عن عدي بن حاتم قال","page":"ص0","text":"عن همام بن الحارث عن عدي بن حاتم قال: ((قلت: يا رسول الله , إني أرسل الكلاب المعلمة , فيمسكن علي , وأذكر اسم الله؟ فقال: إذا أرسلت كلبك المعلم وذكرت اسم الله , فكل ما أمسك عليك. قلت: وإن قتلن؟ قال: وإن قتلن , ما لم يشركها كلب ليس منها. قلت: فإني أرمي بالمعراض الصيد , فأصيب؟ فقال: إذا رميت بالمعراض فخزق , فكله وإن أصابه بعرضه فلا تأكله)) .","bab":"باب الصيد"},{"id":"umdat-ahkam:577","bookId":"umdat-ahkam","type":"section","seq":577,"chapter":"كتاب الأطعمة","title":"394- وحديث الشعبي عن عدي نحوه","page":"ص0","text":"وحديث الشعبي عن عدي نحوه , وفيه: ((إلا أن يأكل الكلب , فإن أكل فلا تأكل , فإني أخاف أن يكون إنما أمسك على نفسه. وإن خالطها كلاب من غيرها فلا تأكل، فإنما سميت على كلبك , ولم تسم على غيره)) .\nوفيه ((إذا أرسلت كلبك المكلب فاذكر اسم الله عليه، فإن أمسك عليك فأدركته حيا فاذبحه , وإن أدركته قد قتل ولم يأكل منه فكله، فإن أخذ الكلب ذكاته)) .\nوفيه أيضا ((إذا رميت بسهمك فاذكر اسم الله عليه)) وفيه ((وإن غاب عنك يوما أو يومين)) .\nوفي رواية ((اليومين والثلاثة فلم تجد فيه إلا أثر سهمك فكل إن شئت , فإن وجدته غريقا في الماء فلا تأكل، فإنك لا تدري: الماء قتله , أو سهمك؟)) .","bab":"باب الصيد"},{"id":"umdat-ahkam:578","bookId":"umdat-ahkam","type":"section","seq":578,"chapter":"كتاب الأطعمة","title":"ص: 265","page":"ص0","text":"المعراض: عصا رأسها محنية.\nفخرق: نفذ في الشيء المرمي به.\nالمكلب: المدرب.","bab":"باب الصيد"},{"id":"umdat-ahkam:579","bookId":"umdat-ahkam","type":"section","seq":579,"chapter":"كتاب الأطعمة","title":"395- عن سالم بن عبد الله بن عمر عن أبيه رضي الله عنهما قال","page":"ص0","text":"عن سالم بن عبد الله بن عمر عن أبيه رضي الله عنهما قال: سمعت رسول الله - صلى الله عليه وسلم - يقول ((من اقتنى كلبا - إلا كلب صيد , أو ماشية - فإنه ينقص من أجره كل يوم قيراطان)) . قال سالم: وكان أبو هريرة يقول: ((أو كلب حرث)) ، وكان صاحب حرث.","bab":"باب الصيد"},{"id":"umdat-ahkam:580","bookId":"umdat-ahkam","type":"section","seq":580,"chapter":"كتاب الأطعمة","title":"396- عن رافع بن خديج - رضي الله عنه - قال","page":"ص0","text":"عن رافع بن خديج - رضي الله عنه - قال: ((كنا مع رسول الله - صلى الله عليه وسلم - بذي الحليفة من تهامة , فأصاب الناس جوع فأصابوا إبلا وغنما، وكان النبي - صلى الله عليه وسلم - في أخريات القوم، فعجلوا وذبحوا ونصبوا القدور فأمر النبي - صلى الله عليه وسلم - بالقدور فأكفئت , ثم قسم فعدل عشرة من الغنم ببعير , فند منها بعير فطلبوه فأعياهم , وكان في القوم خيل يسيرة فأهوى رجل منهم بسهم , فحبسه الله. فقال: إن لهذه البهائم أوابد كأوابد الوحش، فما ند عليكم منها فاصنعوا به هكذا، قلت: يا رسول الله , إنا لاقو العدو غدا , وليس معنا مدى. أفنذبح بالقصب؟ قال: ما أنهر الدم , وذكر اسم الله عليه , فكلوه , ليس السن والظفر , وسأحدثكم عن ذلك , أما السن: فعظم , وأما الظفر: فمدى الحبشة)) .","bab":"باب الصيد"},{"id":"umdat-ahkam:581","bookId":"umdat-ahkam","type":"section","seq":581,"chapter":"كتاب الأطعمة","title":"ص: 266","page":"ص0","text":"ند: هرب.\nأعياهم: أعجزهم.\nأوابد: جمع «آبدة» وهي الغريبة المتوحشة، أي أن لها توحشا ونفورا.\nأنهر الدم: أساله وأجراه.\nفمدى الحبشة: جمع «مدية» وهي السكين.","bab":"باب الصيد"},{"id":"umdat-ahkam:582","bookId":"umdat-ahkam","type":"section","seq":582,"chapter":"كتاب الأطعمة","title":"397- عن أنس بن مالك - رضي الله عنه - قال","page":"ج1 ص266","text":"عن أنس بن مالك - رضي الله عنه - قال: ((ضحى النبي - صلى الله عليه وسلم - بكبشين أملحين أقرنين ذبحهما بيده , وسمى وكبر ووضع رجله على صفاحهما)) .\nالأملح: الأغبر وهو الذي فيه سواد وبياض.","bab":"باب الأضاحي"},{"id":"umdat-ahkam:583","bookId":"umdat-ahkam","type":"section","seq":583,"chapter":"كتاب الأطعمة","title":"ص: 267","page":"ج1 ص266","text":"صفاحهما: صفحة كل شيء وجهه وجانبه. والمراد صفاح أعناقهما.","bab":"باب الأضاحي"},{"id":"umdat-ahkam:584","bookId":"umdat-ahkam","type":"section","seq":584,"chapter":"كتاب الأشربة","title":"398- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص267","text":"عن عبد الله بن عمر رضي الله عنهما ((أن عمر قال - على منبر رسول الله - صلى الله عليه وسلم - أما بعد , أيها الناس , إنه نزل تحريم الخمر وهي من خمسة: من العنب , والتمر , والعسل , والحنطة , والشعير. والخمر: ما خامر العقل ثلاث وددت أن رسول الله - صلى الله عليه وسلم - كان عهد إلينا فيها عهدا ننتهي إليه: الجد , والكلالة , وأبواب من الربا)) .\nالكلالة: من لاأب له ولاولد."},{"id":"umdat-ahkam:585","bookId":"umdat-ahkam","type":"section","seq":585,"chapter":"كتاب الأشربة","title":"399- عن عائشة رضي الله عنها","page":"ص0","text":"عن عائشة رضي الله عنها: ((أن رسول الله - صلى الله عليه وسلم - سئل عن البتع؟ فقال: كل شراب أسكر فهو حرام)) . البتع: نبيذ العسل."},{"id":"umdat-ahkam:586","bookId":"umdat-ahkam","type":"section","seq":586,"chapter":"كتاب الأشربة","title":"400- عن عبد الله بن عباس رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عباس رضي الله عنهما قال: ((بلغ عمر: أن فلانا باع خمرا فقال: قاتل الله فلانا , ألم يعلم أن رسول الله - صلى الله عليه وسلم - قال: ((قاتل الله اليهود , حرمت عليهم الشحوم , فجملوها فباعوها؟)) ."},{"id":"umdat-ahkam:587","bookId":"umdat-ahkam","type":"section","seq":587,"chapter":"كتاب الأشربة","title":"ص: 269","page":"ص0","text":"جملوها: أذابوا شحمها."},{"id":"umdat-ahkam:588","bookId":"umdat-ahkam","type":"section","seq":588,"chapter":"كتاب اللباس","title":"401- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ج1 ص269","text":"عن عمر بن الخطاب - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((لا تلبسوا الحرير، فإنه من لبسه في الدنيا لم يلبسه في الآخرة)) ."},{"id":"umdat-ahkam:589","bookId":"umdat-ahkam","type":"section","seq":589,"chapter":"كتاب اللباس","title":"402- عن حذيفة بن اليمان رضي الله عنهما قال","page":"ص0","text":"عن حذيفة بن اليمان رضي الله عنهما قال: سمعت رسول الله - صلى الله عليه وسلم - يقول: ((لا تلبسوا الحرير ولا الديباج , ولا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافهما، فإنها لهم في الدنيا ولكم في الآخرة)) ."},{"id":"umdat-ahkam:590","bookId":"umdat-ahkam","type":"section","seq":590,"chapter":"كتاب اللباس","title":"ص: 270","page":"ص0","text":"الديباج: غليظ الحرير.\nصحافهما: جمع «صفحة» وهو إناء متسع."},{"id":"umdat-ahkam:591","bookId":"umdat-ahkam","type":"section","seq":591,"chapter":"كتاب اللباس","title":"403- عن البراء بن عازب - رضي الله عنه - قال","page":"ص0","text":"عن البراء بن عازب - رضي الله عنه - قال: ((ما رأيت من ذي لمة في حلة حمراء أحسن من رسول الله - صلى الله عليه وسلم -، له شعر يضرب منكبيه , بعيد ما بين المنكبين، ليس بالقصير ولا بالطويل)) .\nذي لمة: صاحب لمة، وهي الشعر يتجاوز شحمة الأذن.\nحلة: الحلة عند العرب مكونة من ثوبين."},{"id":"umdat-ahkam:592","bookId":"umdat-ahkam","type":"section","seq":592,"chapter":"كتاب اللباس","title":"404- عن البراء بن عازب - رضي الله عنه - قال","page":"ص0","text":"عن البراء بن عازب - رضي الله عنه - قال: ((أمرنا رسول الله - صلى الله عليه وسلم - بسبع، ونهانا عن سبع: أمرنا بعيادة المريض , واتباع الجنازة , وتشميت العاطس , وإبرار القسم (أو المقسم) , ونصر المظلوم , وإجابة الداعي , وإفشاء السلام. ونهانا عن خواتيم - أو عن تختم - بالذهب , وعن الشرب بالفضة، وعن المياثر، وعن القسي , وعن لبس الحرير , والإستبرق , والديباج)) ."},{"id":"umdat-ahkam:593","bookId":"umdat-ahkam","type":"section","seq":593,"chapter":"كتاب اللباس","title":"ص: 271","page":"ص0","text":"تشميت العاطس: دعاء له بالرحمة.\nالمياثر: جمع «ميثرة» وهو غطاء للسرج من الحرير يوضع على ظهر الفرس ورحل البعير.\nالقسي: ثياب من الكتان المخلوط بالحرير.\nالإستبرق: ماغلظ من الديباج.\nالديباج: نوع من الحرير رقيق."},{"id":"umdat-ahkam:594","bookId":"umdat-ahkam","type":"section","seq":594,"chapter":"كتاب اللباس","title":"405- عن ابن عمر رضي الله عنهما","page":"ص0","text":"عن ابن عمر رضي الله عنهما ((أن رسول الله - صلى الله عليه وسلم - اصطنع خاتما من ذهب، فكان يجعل فصه في باطن كفه إذا لبسه، فصنع الناس كذلك، ثم إنه جلس على المنبر فنزعه فقال: إني كنت ألبس هذا الخاتم , وأجعل فصه من داخل , فرمى به ثم قال: والله لا ألبسه أبدا فنبذ الناس خواتيمهم)) .\nوفي لفظ ((جعله في يده اليمنى)) .\nنبذ: رمى."},{"id":"umdat-ahkam:595","bookId":"umdat-ahkam","type":"section","seq":595,"chapter":"كتاب اللباس","title":"406- عن عمر بن الخطاب - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم -","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - ((نهى عن لبوس الحرير إلا هكذا , ورفع لنا رسول الله - صلى الله عليه وسلم - أصبعيه: السبابة , والوسطى)) ."},{"id":"umdat-ahkam:596","bookId":"umdat-ahkam","type":"section","seq":596,"chapter":"كتاب اللباس","title":"ص: 272","page":"ص0","text":"ولمسلم ((نهى رسول الله - صلى الله عليه وسلم - عن لبس الحرير إلا موضع أصبعين , أو ثلاث , أو أربع)) ."},{"id":"umdat-ahkam:597","bookId":"umdat-ahkam","type":"section","seq":597,"chapter":"كتاب الجهاد","title":"407- عن عبد الله بن أبي أوفى - رضي الله عنه -","page":"ج1 ص273","text":"عن عبد الله بن أبي أوفى - رضي الله عنه -: أن رسول الله - صلى الله عليه وسلم - في بعض أيامه التي لقي فيها العدو - انتظر , حتى إذا مالت الشمس قام فيهم , فقال: ((أيها الناس , لا تتمنوا لقاء العدو , واسألوا الله العافية فإذا لقيتموهم فاصبروا , واعلموا أن الجنة تحت ظلال السيوف ثم قال النبي - صلى الله عليه وسلم -: اللهم منزل الكتاب , ومجري السحاب , وهازم الأحزاب: اهزمهم , وانصرنا عليهم)) ."},{"id":"umdat-ahkam:598","bookId":"umdat-ahkam","type":"section","seq":598,"chapter":"كتاب الجهاد","title":"408- عن سهل بن سعد - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال","page":"ص0","text":"عن سهل بن سعد - رضي الله عنه - أن رسول الله - صلى الله عليه وسلم - قال: ((رباط يوم في سبيل الله خير من الدنيا وما عليها , وموضع سوط أحدكم في الجنة خير من الدنيا وما عليها ,"},{"id":"umdat-ahkam:599","bookId":"umdat-ahkam","type":"section","seq":599,"chapter":"كتاب الجهاد","title":"ص: 274","page":"ص0","text":"والروحة يروحها العبد في سبيل الله والغدوة خير من الدنيا وما فيها)) .\nالرباط: ملازمة المكان الذي بين المسلمين والكفار لحراسة المسلمين منهم.\nالروحة: السير من الزوال إلى الليل.\nالغدوة: السير في أول النهار إلى الزوال."},{"id":"umdat-ahkam:600","bookId":"umdat-ahkam","type":"section","seq":600,"chapter":"كتاب الجهاد","title":"409- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((انتدب الله (ولمسلم: تضمن الله) لمن خرج في سبيله , لا يخرجه إلا جهاد في سبيلي , وإيمان بي , وتصديق برسلي فهو علي ضامن: أن أدخله الجنة , أو أرجعه إلى مسكنه الذي خرج منه , نائلا ما نال من أجر أو غنيمة)) .\nضامن: مضمون، له الجزاء الحسن في الجنة."},{"id":"umdat-ahkam:601","bookId":"umdat-ahkam","type":"section","seq":601,"chapter":"كتاب الجهاد","title":"410- ولمسلم","page":"ص0","text":"ولمسلم: ((مثل المجاهد في سبيل الله - , والله أعلم بمن جاهد في سبيله - كمثل الصائم القائم , وتوكل الله للمجاهد في سبيله إن توفاه: أن يدخله الجنة , أو يرجعه سالما مع أجر أو غنيمة)) ."},{"id":"umdat-ahkam:602","bookId":"umdat-ahkam","type":"section","seq":602,"chapter":"كتاب الجهاد","title":"411- عن أبي هريرة - رضي الله عنه - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((ما من مكلوم يكلم في سبيل الله , إلا جاء يوم القيامة , وكلمه يدمى: اللون لون الدم , والريح ريح المسك)) .\nمكلوم: مجروح."},{"id":"umdat-ahkam:603","bookId":"umdat-ahkam","type":"section","seq":603,"chapter":"كتاب الجهاد","title":"412- عن أبي أيوب الأنصاري - رضي الله عنه - قال","page":"ص0","text":"عن أبي أيوب الأنصاري - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((غدوة في سبيل الله , أو روحة: خير مما طلعت عليه الشمس وغربت)) أخرجه مسلم"},{"id":"umdat-ahkam:604","bookId":"umdat-ahkam","type":"section","seq":604,"chapter":"كتاب الجهاد","title":"413- عن أنس بن مالك - رضي الله عنه - قال","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - قال: قال رسول الله - صلى الله عليه وسلم -: ((غدوة في سبيل الله , أو روحة: خير من الدنيا وما فيها)) أخرجه البخاري."},{"id":"umdat-ahkam:605","bookId":"umdat-ahkam","type":"section","seq":605,"chapter":"كتاب الجهاد","title":"414- عن أبي قتادة الأنصاري - رضي الله عنه - قال","page":"ص0","text":"عن أبي قتادة الأنصاري - رضي الله عنه - قال: ((خرجنا مع رسول الله - صلى الله عليه وسلم - إلى حنين - وذكر قصة - فقال رسول الله - صلى الله عليه وسلم -: من قتل قتيلا له عليه بينة فله سلبه)) قالها ثلاثا.\nسلبه: السلب: ثياب المقتول وسلاحه ودابته التي قاتل عليها."},{"id":"umdat-ahkam:606","bookId":"umdat-ahkam","type":"section","seq":606,"chapter":"كتاب الجهاد","title":"415- عن سلمة بن الأكوع - رضي الله عنه - قال","page":"ص0","text":"عن سلمة بن الأكوع - رضي الله عنه - قال: ((أتى النبي - صلى الله عليه وسلم - عين من المشركين , وهو في سفره , فجلس عند أصحابه يتحدث , ثم انفتل , فقال النبي - صلى الله عليه وسلم -: اطلبوه واقتلوه فقتلته , فنفلني سلبه)) ."},{"id":"umdat-ahkam:607","bookId":"umdat-ahkam","type":"section","seq":607,"chapter":"كتاب الجهاد","title":"ص: 277","page":"ص0","text":"في رواية ((فقال: من قتل الرجل؟ فقالوا: ابن الأكوع فقال: له سلبه أجمع)) ."},{"id":"umdat-ahkam:608","bookId":"umdat-ahkam","type":"section","seq":608,"chapter":"كتاب الجهاد","title":"416- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((بعث رسول الله - صلى الله عليه وسلم - سرية إلى نجد فخرج فيها , فأصبنا إبلا وغنما , فبلغت سهماننا اثني عشر بعيرا , ونفلنا رسول الله - صلى الله عليه وسلم - بعيرا بعيرا)) ."},{"id":"umdat-ahkam:609","bookId":"umdat-ahkam","type":"section","seq":609,"chapter":"كتاب الجهاد","title":"417- عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما عن النبي - صلى الله عليه وسلم - قال: ((إذا جمع الله عز وجل الأولين والآخرين: يرفع لكل غادر لواء , فيقال: هذه غدرة فلان بن فلان)) .\nغادر: تارك للوفاء، ناقض للعهد."},{"id":"umdat-ahkam:610","bookId":"umdat-ahkam","type":"section","seq":610,"chapter":"كتاب الجهاد","title":"418- عن عبد الله بن عمر رضي الله عنهما","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما ((أن امرأة وجدت في بعض مغازي النبي - صلى الله عليه وسلم - مقتولة , فأنكر النبي - صلى الله عليه وسلم - قتل النساء , والصبيان)) ."},{"id":"umdat-ahkam:611","bookId":"umdat-ahkam","type":"section","seq":611,"chapter":"كتاب الجهاد","title":"419- عن أنس بن مالك - رضي الله عنه -","page":"ص0","text":"عن أنس بن مالك - رضي الله عنه - ((أن عبد الرحمن بن عوف , والزبير بن العوام , شكوا القمل إلى رسول الله - صلى الله عليه وسلم - في غزاة لهما فرخص لهما في قميص الحرير ورأيته عليهما)) ."},{"id":"umdat-ahkam:612","bookId":"umdat-ahkam","type":"section","seq":612,"chapter":"كتاب الجهاد","title":"420- عن عمر بن الخطاب - رضي الله عنه - قال","page":"ص0","text":"عن عمر بن الخطاب - رضي الله عنه - قال: ((كانت أموال بني النضير: مما أفاء الله على رسوله - صلى الله عليه وسلم - مما لم يوجف المسلمون عليه بخيل ولا ركاب وكانت لرسول الله - صلى الله عليه وسلم - خالصا , فكان رسول الله - صلى الله عليه وسلم - يعزل نفقة أهله سنة , ثم يجعل ما بقي في الكراع , والسلاح عدة في سبيل الله عز وجل)) .\nبنو النضير: إحدى طوائف اليهود الذين سكنوا قرب المدينة.\nيوجف: الإيجاف: الإسراع في السير.\nركاب: هي الإبل.\nالكراع: اسم لجمع الخيل."},{"id":"umdat-ahkam:613","bookId":"umdat-ahkam","type":"section","seq":613,"chapter":"كتاب الجهاد","title":"421- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((أجرى النبي - صلى الله عليه وسلم - ما ضمر من الخيل: من الحفياء إلى ثنية الوداع ,"},{"id":"umdat-ahkam:614","bookId":"umdat-ahkam","type":"section","seq":614,"chapter":"كتاب الجهاد","title":"ص: 279","page":"ص0","text":"وأجرى ما لم يضمر: من الثنية إلى مسجد بني زريق. قال ابن عمر: وكنت فيمن أجرى. قال سفيان: من الحفياء إلى ثنية الوداع: خمسة أميال , أو ستة , ومن ثنية الوداع إلى مسجد بني زريق: ميل)) .\nما ضمر: الخيل المضمرة: هي التي علفت حتى سمنت وقويت ثم خفف طعامها تدريجيا لتقوى على السرعة والحركة."},{"id":"umdat-ahkam:615","bookId":"umdat-ahkam","type":"section","seq":615,"chapter":"كتاب الجهاد","title":"422- عن عبد الله بن عمر رضي الله عنهما قال","page":"ص0","text":"عن عبد الله بن عمر رضي الله عنهما قال: ((عرضت على رسول الله - صلى الله عليه وسلم - يوم أحد , وأنا ابن أربع عشرة , فلم يجزني , وعرضت عليه يوم الخندق , وأنا ابن خمس عشرة , فأجازني)) ."},{"id":"umdat-ahkam:616","bookId":"umdat-ahkam","type":"section","seq":616,"chapter":"كتاب الجهاد","title":"423- وعنه","page":"ص0","text":"وعنه ((أن رسول الله - صلى الله عليه وسلم - قسم في النفل: للفرس سهمين , وللرجل سهما)) ."},{"id":"umdat-ahkam:617","bookId":"umdat-ahkam","type":"section","seq":617,"chapter":"كتاب الجهاد","title":"ص: 280","page":"ص0","text":"النفل: الغنيمة."},{"id":"umdat-ahkam:618","bookId":"umdat-ahkam","type":"section","seq":618,"chapter":"كتاب الجهاد","title":"424- وعنه","page":"ص0","text":"وعنه ((أن رسول الله - صلى الله عليه وسلم -: كان ينفل بعض من يبعث في السرايا لأنفسهم خاصة سوى قسم عامة الجيش)) ."},{"id":"umdat-ahkam:619","bookId":"umdat-ahkam","type":"section","seq":619,"chapter":"كتاب الجهاد","title":"425- عن أبي موسى - عبد الله بن قيس - عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي موسى - عبد الله بن قيس - عن النبي - صلى الله عليه وسلم - قال: ((من حمل علينا السلاح فليس منا)) ."},{"id":"umdat-ahkam:620","bookId":"umdat-ahkam","type":"section","seq":620,"chapter":"كتاب الجهاد","title":"426- عن أبي موسى - رضي الله عنه - قال","page":"ص0","text":"عن أبي موسى - رضي الله عنه - قال: ((سئل رسول الله - صلى الله عليه وسلم - عن الرجل: يقاتل شجاعة , ويقاتل حمية، ويقاتل رياء. أي ذلك في سبيل الله؟ فقال رسول الله - صلى الله عليه وسلم -: من قاتل لتكون كلمة الله هي العليا , فهو في سبيل الله)) ."},{"id":"umdat-ahkam:621","bookId":"umdat-ahkam","type":"section","seq":621,"chapter":"كتاب الجهاد","title":"ص: 281","page":"ص0","text":"شجاعة: ليشتهر بين الناس بالشجاعة.\nحمية: انتصارا لقومه ووطنه من غير قصد إعلاء كلمة الله.\nرياء: طلبا للثناء والمدح من الناس."},{"id":"umdat-ahkam:622","bookId":"umdat-ahkam","type":"section","seq":622,"chapter":"كتاب العتق","title":"427- عن عبد الله بن عمر رضي الله عنهما","page":"ج1 ص281","text":"عن عبد الله بن عمر رضي الله عنهما: أن رسول الله - صلى الله عليه وسلم - قال: ((من أعتق شركا له في عبد , فكان له مال يبلغ ثمن العبد: قوم عليه قيمة عدل , فأعطى شركاءه حصصهم , وعتق عليه العبد , وإلا فقد عتق منه ما عتق)) .\nشركا له: جزءا ونصيبا.\nقيمة عدل: من غير زيادة ولانقصان."},{"id":"umdat-ahkam:623","bookId":"umdat-ahkam","type":"section","seq":623,"chapter":"كتاب العتق","title":"428- عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال","page":"ص0","text":"عن أبي هريرة - رضي الله عنه - عن النبي - صلى الله عليه وسلم - قال: ((من أعتق شقصا من مملوك , فعليه خلاصه كله في ماله , فإن لم يكن له مال قوم المملوك قيمة عدل , ثم استسعي العبد , غير مشقوق عليه)) ."},{"id":"umdat-ahkam:624","bookId":"umdat-ahkam","type":"section","seq":624,"chapter":"كتاب العتق","title":"ص: 282","page":"ص0","text":"شقصا: الشقص: هو القليل من كل شيء.\nاستسعي: ألزم السعي فيما يفك به بقية رقبته من الرق.\nغير مشقوق عليه: لايكلف مايشق عليه من الخدمة."},{"id":"umdat-ahkam:625","bookId":"umdat-ahkam","type":"section","seq":625,"chapter":"كتاب العتق","title":"429- عن جابر بن عبد الله رضي الله عنهما قال","page":"ج1 ص282","text":"عن جابر بن عبد الله رضي الله عنهما قال: ((دبر رجل من الأنصار غلاما له - ,","bab":"باب بيع المدبر"},{"id":"umdat-ahkam:626","bookId":"umdat-ahkam","type":"section","seq":626,"chapter":"كتاب العتق","title":"430- وفي لفظ","page":"ج1 ص282","text":"وفي لفظ: ((بلغ النبي - صلى الله عليه وسلم -: أن رجلا من أصحابه أعتق غلاما له عن دبر - لم يكن له مال غيره فباعه رسول الله - صلى الله عليه وسلم - بثمانمائة درهم , ثم أرسل ثمنه إليه)) .\nدبر: هو نقيض القبل من كل شيء، والمراد هنا بعد موته.","bab":"باب بيع المدبر"}]};